window.__D("text/torat-shmuel/c056",{"p":[[2001910303,"הזריעה אינו מצמיח כ\"א ע\"י מים והיינו שמים הוא בחי' תורה, ולזה למדו רז\"ל בספ\"ק דב\"ק די\"ז ע\"א ע\"פ אשריכם זורעי וגו' כל העוסק בתורה וגמ\"ח זוכה לנחלת שני שבטים שנא' זורעי על כל מים משלחי רגל השור והחמור כו', וזהו אשר תזרע בשדה שע\"י הזריעה של תו\"מ עי\"ז נמשך הקצירה שהיא מ\"ת (והיינו כנ\"ל שהקצירה היא תשלום שכר, וכמו שפי' בלק\"ת בד\"ה וספרתם דחה\"ש פ\"ג<sup data-n=\"2869\">86</sup> ראשית קצירכם הו\"ע השגת הנפש בחי' גילוי אור א\"ס ב\"ה בעלמא דאתגליא איך הוא ממכ\"ע וסוכ\"ע, ור\"ל קצירכם הו\"ע השגת הנפש בחי' ההשפעה מלמעלה נק' קציר, וקציר שעורים זהו ההשגה שמבחי' שיעור ה' היינו בחי' ממכ\"ע, ובשבועות חג הקציר של חטים הוא גילוי בחי' חטה מאכל אדם<sup data-n=\"2870\">87</sup>, והוא גילוי מה שלמעלה מהדעת והשגה כו' (כי מה שהתינוק קורא אבא זה אינו ע\"פ השגה כ\"א זהו מלמעלה מהדעת, רק שנתלבש בבחי' שלמטה מן הדעת ע' בד\"ה וספרתם הנ\"ל), ובחי' זו נמשכה לישראל במ\"ת, וזה קרוב למ\"ש בזח\"א ויצא דקנ\"ז ב' בענין לחם מן הארץ שעי\"ז השיגו בבחי' ארץ העליונה שהיא השכינה בחי' ממכ\"ע, וכדי להשיג בחי' קוב\"ה סוכ\"ע בחי' שמים זהו ע\"י לחם מן השמים יעו\"ש, וכך עד\"ז הו\"ע קציר שעורים וקציר חטים, וכמ\"ש מזה בד\"ה וחג הקציר בס' חורף תרט\"ז דקנ\"ט ע\"א<sup data-n=\"2871\">88</sup>, ועמ\"ש בד\"ה כי תבואו אל הארץ כו' שש שנים תזרע שדך<sup data-n=\"2873\">90</sup>, איך התומ\"צ הם בבחי' זריעה, שההלכה שאדם לומד בעוה\"ז שנים אוחזין בטלית<sup data-n=\"2874\">91</sup> כו' הוא כמו הזרע שנרקב בארץ, ונכלל בכח הצומח ועי\"ז מצמיח, כן לימוד ההלכה זו נכלל בבחי' העלאת מ\"ן<sup data-n=\"2875\">92</sup> בבחי' ציון הנק' שדה, ומזה נצמח להאדם לימוד והבנת שרש הלכה זו למעלה מה שהוא למעלה במקור שורשה בעדן העליון, ונמשך משם לג\"ע העליון כו' והיינו כי מציון תצא תורה, וע' מזה ג\"כ בלק\"ת פ' בהר בד\"ה כי תבואו אל הארץ ושם<sup data-n=\"2876\">93</sup> ספ\"ב<sup data-n=\"2872\">89</sup>, וי\"ל שגם לג\"ע התחתון נמשך הארה מבחי' זו וכמ\"ש בסש\"ב פל\"ט מענין זיו תורתן ועבודתם כו' וכמו שפי' זה בלק\"ת בד\"ה במדבר סיני דרוש השני פ\"א בהג\"ה<sup data-n=\"2877\">94</sup> ע\"ש, וז\"ע הקצירה בד\"כ, ובדרך פרט) זהו שאנו מברכים בכ\"י נותן התורה<sup data-n=\"2878\">95</sup> שנמשך בכל יום המשכת התו' והיינו שבכ\"י נמשך המשכה עליונה יותר (והיינו לפי ערך הזריעה כן הוא הצמיחה שהוא בחי' הקציר בחי' מ\"ת שבכל יום כו').",[["2869","86","<b>בלק\"ת . . פ\"ג</b>: במדבר י, ג."],["2870","87","<b>חטה מאכל אדם</b>: ראה פסחים ג, סע\"ב. מאמרי אדה\"א במדבר ח\"ב ס\"ע שטז ואילך."],["2871","88","<b>בד\"ה וחג הקציר . . ע\"א</b>: אוה\"ת משפטים ע' א'קפט."],["2873","90","<b>בד\"ה כי תבואו . . שדך</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קפו."],["2874","91","<b>שנים אוחזין בטלית</b>: משנה ב\"מ ב, א."],["2875","92","<b>מ\"ן</b>: ראה לקמן מאמר ד\"ה וירא ישראל את היד הגדולה ובהערה 158."],["2876","93","<b>בלק\"ת פ' בהר. . ספ\"ב</b>: מ, ג."],["2872","89","<b>בד\"ה כי . . ושם ספ\"ב</b>: לשון אוה\"ת משפטים כאן ע' א'קפד."],["2877","94","<b>בלק\"ת בד\"ה במדבר . . בהג\"ה</b>: ב, סע\"א ואילך."],["2878","95","<b>שאנו מברכים בכ\"י נותן התורה</b>: בברכת התורה. ראה גם סה\"מ תר\"ל כאן ע' קלו. מאמרי אדה\"א דברים ח\"ג ס\"ע תתכא ואילך."]]],[2001910304,"ח) <b>וחג</b> האסיף<sup data-n=\"2879\">96</sup> בצאת השנה באספך<sup data-n=\"2880\">97</sup> היינו שחג הסוכות הוא למעלה יותר, והיינו כי חגה\"ס הוא בחי' תשובה וע\"כ נק' חג האסיף, דהנה כתי' כי אבי ואמי עזבוני<sup data-n=\"2881\">98</sup> וה' יאספני, אבי ואמי הוא תושב\"כ ותושבע\"פ וכמ\"ש שמע בני מוסר אביך<sup data-n=\"2882\">99</sup> זו תושב\"כ ואל תטוש תורת אמך זו תושבע\"פ, והיינו כשפגם בתומ\"צ אז אבי ואמי עזבוני כו', וכמ\"ש בילקוט שאלו לחכ'<sup data-n=\"2883\">100</sup> חוטא מה עונשו, א\"ל חטאים תרדוף רעה<sup data-n=\"2884\">101</sup>, וכן שאלו לתורה השיבה יביא קרבן<sup data-n=\"2885\">102</sup> ויתכפר לו, אך הקרבן הוא רק על שוגג<sup data-n=\"2886\">103</sup> ולא על המזיד<sup data-n=\"2887\">104</sup>, שאלו להקב\"ה וא' יעשה תשובה ויתכפר לו, וזהו שנא' טוב וישר<sup data-n=\"2888\">105</sup> ה' ע\"כ יורה חטאים בדרך, וזהו וה' יאספני, וזהו ענין חג הסוכות שאז הוא זמן אסיפה, והיינו לפי שמקודם הוא בחי' ר\"ה ויו\"כ שנא' בהתאסף ראשי עם<sup data-n=\"2889\">106</sup> יחד שבטי ישראל שמתקבץ כל הבחי' יחד והיינו שמתקבצי' כל הניצוצי' שנתפזרו בכל ימות השנה, וכמ\"ש אם יהי' נדחך<sup data-n=\"2890\">107</sup> בקצה השמים, ובר\"ה ויו\"כ על ידי התשובה מתאספי' יחד, וזהו שנק' חג הסוכות חג האסיף, וזהו מ\"ש ואספת דגנך ותירושך ויצהריך שהוא בחי' אסיפה של כהנים לוים ישראלים<sup data-n=\"2891\">108</sup>, דגנך הוא ישראל וכמ\"ש (זכרי' ססי' ט') כי מה טובו ומה יפיו דגן בחורים, ופי' במד\"ר תולדות פס\"ו<sup data-n=\"2892\">109</sup> ע\"פ ורוב דגן<sup data-n=\"2893\">110</sup> אלו הבחורים שנא' דגן בחורים, וע' בס' דברים ע\"פ ואספת דגנך דקס\"ט ע\"ב<sup data-n=\"2894\">111</sup> שפי' שי\"ל שדגנך הם ישראלים, ותירושך הוא בחי' לוים ואין אומרים שירה אלא על היין<sup data-n=\"2895\">112</sup>, ויצהריך הם כהנים שנמשחו בשמן<sup data-n=\"2896\">113</sup>, וכשמתאספי' יחד עי\"ז נעשה המשכה עליונה יותר",[["2879","96","<b>וחג האסיף</b>: ראה גם להבא להלן אוה\"ת משפטים ע' א'קפה ואילך. סה\"מ תר\"ל ע' קלז. ע' ריג [אוה\"ת פינחס ע' א'רכ]. תרל\"ג ח\"א כאן ע' קמט ואילך."],["2880","97","<b>וחג האסיף . . באספך</b>: משפטים כג, טז."],["2881","98","<b>כי אבי ואמי עזבוני</b>: תהלים כא, י."],["2882","99","<b>שמע בני מוסר אביך</b>: משלי א, ח. ראה גם אגה\"ק סכ\"ט (קנא, א). מאמרי אדה\"ז תקע\"א ע' פא. מאמרי אדה\"א דברים ח\"ד ע' א'תנ. וש\"נ."],["2883","100","<b>בילקוט שאלו לחכ'</b>: ראה לעיל מאמר ד\"ה וברך את לחמך ובהערה 47."],["2884","101","<b>חטאים תרדוף רעה</b>: משלי יג, כא. ראה גם לקמן בשני ההנחות כאן."],["2885","102","<b>קרבן</b>: כ\"ה בירושלמי מכות פ\"ב, ה\"ו. אבל בילקוט שמעוני יחזקאל יח, ד (רמז שנח). תהלים כה, ח (רמז תשב): אשם. ובזית רענן לתהלים שם: דרוב אשמות בא על מזיד — ראה בסמוך הערה 104."],["2886","103","<b>הקרבן . . על השוגג</b>: ראה רמב\"ם הל' שגגות רפ\"א ואילך. אגה\"ק סוסכ\"ח."],["2887","104","<b>הקרבן . . ולא על המזיד</b>: ראה סה\"מ תרל\"ג ח\"א כאן ע' קמט בשולי היריעה. תר\"ם ח\"ב ע' תר. וש\"נ."],["2888","105","<b>טוב וישר ה'</b>: תהלים כה, ח."],["2889","106","<b>בהתאסף ראשי עם</b>: ברכה לג, ה."],["2890","107","<b>אם יהי' נדחך</b>: נצבים ל, ד."],["2891","108","<b>ואספת דגנך . . ישראלים</b>: עקב יא, יד. ראה גם (בנוסף להבא בסמוך בפנים) מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרפג. מאמר ד\"ה והי' עקב — <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450489\" data-slug=\"or-hatorah-hb\" data-id=\"8316450489\">אוה\"ת עקב ע' תפט</a> וע' תתשלז [נדפס בקונט' בפ\"ע קה\"ת תשט\"ז — ושם ע' 14 בהערת כ\"ק אדמו\"ר זי\"ע: ”צ\"ע. וראה ויקרא פא, ב\". לכאו' צ\"ל: ”צ\"ע. וראה ויק\"ר פ\"א, ב\"] . ע' תצט — ובכרך ו ע' ב'שה. שע\"ת קמא סע\"א ואילך. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 119. (בחלק ההנחות) בהנחה כאן על יד הערה 130."],["2892","109","<b>פס\"ו</b>: סימן ג."],["2893","110","<b>ורוב דגן</b>: תולדות כז, כח."],["2894","111","<b>בס' דברים . . ע\"ב</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450613\" data-slug=\"or-hatorah-hb\" data-id=\"8316450613\">אוה\"ת עקב ע' תריג</a>."],["2895","112","<b>ואין אומרים . . היין</b>: ברכות לה, א."],["2896","113","<b>כהנים שנמשחו בשמן</b>: שני תיבות האחרונים ליתא באוה\"ת שם. ראה תשא ל, ל. פקודי מ, יג. טו. רמב\"ן צו ח, יא. רמב\"ם הל' כלי המקדש פ\"א ה\"ז."]]],[2001910305,"וכמ\"ש ואגודתו על ארץ יסדה, שכשיש אגודה שהוא בחי' התכללות מג'<sup data-n=\"2897\">114</sup> בחי' יחד עי\"ז נמשך המשכה עליונה יותר, וזהו בשלשה אומר נברך<sup data-n=\"2898\">115</sup> משא\"כ יחיד, והנה בחגה\"ס הוא בחי' אגודה כו' כי ד' מינים שבלולב<sup data-n=\"2899\">*116</sup> שהם נאגדים באגודה אחת<sup data-n=\"2900\">116</sup> וגם הד' מינים מורה על האחדות<sup data-n=\"2901\">117</sup> שהלולב הוא כפות<sup data-n=\"2902\">118</sup> והעלין שלו גדילין יחד<sup data-n=\"2903\">119</sup> וכן הדס<sup data-n=\"2904\">120</sup> וערבה<sup data-n=\"2905\">121</sup> כו', וע\"כ עי\"ז נמשך המשכה גבוה יותר כו', שלמעלה מבחי' תורה שהוא בחי' אבי ואמי שהוא בחי' י\"ה<sup data-n=\"2906\">122</sup>, וע\"כ אף כי אבי ואמי עזבוני ואעפ\"כ וה' יאספני שהיא המשכה שלמעלה מש' הוי', וזהו והלך לפניך צדקיך וכבוד ה' יאספך<sup data-n=\"2907\">123</sup> שיוכלל באלקות וכמ\"ש והיתה נפש אדוני צרורה<sup data-n=\"2908\">124</sup> בצרור החיים את הוי' אלקיך ממש.",[["2897","114","<b>ואגודתו על ארץ . . התכללות מג'</b>: עמוס ט, ו. רש\"י שבת קט, ב ד\"ה ג' קלחים. וראה גם סוכה יג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380880\" data-slug=\"likkutei-torah\" data-id=\"4001380880\">לקו\"ת תצא מ, ד</a>."],["2898","115","<b>בשלשה אומר נברך</b>: ברכות פ\"ז, מ\"ג (מט, ב). ראה סידור שער בהמ\"ז קב, א ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450538\" data-slug=\"or-hatorah-hb\" data-id=\"8316450538\">אוה\"ת עקב ע' תקלח</a> ואילך. סה\"מ תרכ\"ו ע' ריח. לקמן מאמר ד\"ה וחג הקציר בכורי מעשיך על יד הערה 108 ואילך."],["2899","*116","<b>ד' מינים שבלולב</b>: סוכה לא, א. מנחות כז, א."],["2900","116","<b>ד' מינים . . באגודה אחת</b>: כ\"ה בהכת\"י."],["2901","117","<b>הד' מינים . . האחדות</b>: ראה סידור שער הלולב רסא, ג — רסב, ג. רסד, ד — רסה, א. מאמרי אדה\"א דברים ח\"ד ע' א'שי ואילך. סה\"מ תרל\"ו ח\"ב ע' שנח — שסא. המשך וככה תרל\"ז פרק פז. סה\"מ תר\"ם ח\"ב תקעט-תקפ. תרנ\"ב ע' ג-ד. סה\"מ מלוקט א' ע' רנג-רנד."],["2902","118","<b>שהלולב הוא כפות</b>: ראה סוכה לב, א. סה\"מ מלוקט שם."],["2903","119","<b>והעלין שלו גדילין יחד</b>: ראה סידור שם רסב, ב."],["2904","120","<b>וכן הדס</b>: ראה סוכה לב, ב."],["2905","121","<b>וכן . . וערבה</b>: ראה שבת כ, א וברש\"י שם. מאמרי אדה\"א דברים ח\"ד ע' א'שיב בהערה."],["2906","122","<b>אבי ואמי . . י\"ה</b>: ראה זהר ויקרא יא, ב. רע\"מ צו לד, א. ת\"ז תנ\"ה פח, א. תנ\"ו פט, ב. ביאוה\"ז ח\"ש קל, א."],["2907","123","<b>והלך לפניך צדקיך וכבוד ה' יאספך</b>: ישעי' נח, ח [ושם: כבוד — ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 136]."],["2908","124","<b>והיתה נפש אדוני צרורה</b>: שמו\"א כה, כט."]]],[2001910306,"<h3>וירא ישראל</h3>\n<b>שש\"פ מ\"א</b>\n<b>וירא</b> ישראל את היד הגדולה<sup data-n=\"2909\">1</sup> אשר עשה ה' במצרים וייראו העם את ה' ויאמינו בה'<sup data-n=\"2910\">2</sup>, הנה איתא ברבות פ' שמות תוך פ' ה'<sup data-n=\"2911\">3</sup> לפי שאמר פרעה מי ה' אשר אשמע בקולו<sup data-n=\"2912\">4</sup> לכך לקה על הים שהוא אותיות מי<sup data-n=\"2913\">5</sup> דהיינו חמשים מכות, וזהו וירא ישראל את היד הגדולה שהיא חמשים מכות שלקו המצרים על הים כי כמה לקו באצבע<sup data-n=\"2914\">6</sup> עשר מכות ועל הים לקו חמשים מכות<sup data-n=\"2915\">7</sup>, וצ\"ל שהרי היד הגדולה הוא בחי' חסד<sup data-n=\"2916\">8</sup> ואיך מיד הגדולה שהוא בחי' חסד נמשך דוקא המכות שהוא בחי' דין וגבורה<sup data-n=\"2917\">9</sup>, ועוד צ\"ל מה שנא' מתחלה וירא ישראל ואח\"כ ויאמינו, מאחר שראו מה",[["2909","1","<b>וירא ישראל את היד הגדולה</b>: מאמר זה והמשכו הוא מאמר ד\"ה זה שנדפס בסה\"מ תרכ\"ז ע' רמז ואילך. וש\"נ. וכאן הוא בתוספת הגהות וכו'. ד\"ה פדה בשלום שבסה\"מ תרע\"ח ע' צב ואילך. תש\"ז ע' 201 ואילך כנראה שמיוסד על מאמר זה.\nההמשך נרשם בכת\"י מעתיק היינו א) העתק המאמר דתרכ\"ז בכותרת — בכת\"י לא נודע למי —: ”שש\"פ מ\"א\" וברפ\"ה בכותרת כנ\"ל: ”שבת שאחר הפסח פ' אחרי\" עם הגהות ותיקונים בגוכתי\"ק. ב) וכן נרשמו עוד הגהות בע' בפ\"ע בכותרת: ”לד\"ה וירא ישראל דתקס\"ב\". ג) לאח\"ז נרשם ההמשך עוה\"פ בכת\"י מעתיק בלי הכותרות: עם איזה תיקונים בגוכתי\"ק.\nמאמר ד\"ה זה מכ\"ק אדה\"ז משנת תקס\"ד שנדפס בתוס' הגהות וכו' באוה\"ת בשלח ע' תלב [ראה רשימת המאמרים דשנת תקס\"ד במאמרי אדה\"ז תקס\"ד ע' שמו. וש\"נ]. הנה בגוכתי\"ק כאן מציינו בג' אופנים והם: א) שהוא משנת ”תקס\"ב\" כנזכר בפיסקא שלפ\"ז: ”לד\"ה וירא ישראל דתקס\"ב\". ב) לקמן [במאמר ד\"ה והנה תורה היא בחי' קו האמצעי] פ\"ה בשולי הגליון על יד הערה ב מציין עוה\"פ לד\"ה זה אבל שם א\"א לברר באם נכתב תקס\"ב או תקס\"ד. ג) לקמן ד\"ה הים ראה וינוס על יד הערה 24: ”כמ\"ש בד\"ה וירא ישראל דתקס\"ב תקס\"ד\".\nולכאו' הפי' בכ\"ז בבוך 1146 [ראה אודות בוך זה במאמרי אדה\"ז תקס\"ד ע' שמא] שבו נמצא מאמר זה, הנה בריש דף מפתח הדרושים נרשם: ”תקס\"ב תקס\"ד\". לכן לפעמים מייחסו ע\"ש התחלתו ”תקס\"ב\". הבוך נק' לפעמים: ”ביכל תקס\"ד\" וכיו\"ב — לכן אפשר לציין: ”תקס\"ד\". או על שם השער של מפתח הדרושים: ”תקס\"ב תקס\"ד\".\nבסה\"מ תרכ\"ז שם בהערה: המאמר נחלק בתחילה לו' פרקים, ואח\"כ החל כ\"ק אדמו\"ר מהר\"ש לחלק את הפרקים באופן אחר, אך החלוקה זו לא נסתיימה, ונסמנו פרקים אלו בשולי הגליון. יש לציין שחלוקה זו היא כפי שנחלק המאמר לפנינו.\nמאמר זה נזכר בסה\"מ תר\"ן ריש ע' שלז. תרס\"ח ע' קמח ב\"פ.\nחלוקת הקטעים הם ע\"פ סה\"מ תרכ\"ז.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו ושם הפתיחא: ”והמים להם חומה מימינם ומשמאלם\" ובכותרת: ליל אחש\"פ."],["2910","2","<b>וירא ישראל . . ויאמינו בה'</b>: בשלח יד, לא."],["2911","3","<b>ברבות פ' שמות . . ה'</b>: סוף סימן יד. הועתק לשונו באוה\"ת בשלח ע' תכח."],["2912","4","<b>מי ה' אשר אשמע בקולו</b>: שמות ה, ב."],["2913","5","<b>הים שהוא אותיות מי</b>: זהו פי' אחר במדרש שם. וראה הלשון לקמן פ\"ז ד\"ה ומעתה י\"ל בתחילתו."],["2914","6","<b>כמה לקו באצבע</b>: וארא ח, טו."],["2915","7","<b>כמה לקו . . חמשים מכות</b>: הלשון ע\"פ מכילתא בשלח יד, ל."],["2916","8","<b>היד הגדולה . . חסד</b>: ראה מאו\"א מערכת יד אות ה."],["2917","9","<b>ואיך מיד הגדולה . . וגבורה</b>: ראה גם אוה\"ת בשלח ע' תכז ואילך. ע' תנח ואילך. ע' תע ואילך. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערות 18-16."]]],[2001910307,"שייך להאמין אח\"כ<sup data-n=\"2918\">10</sup>, וכמ\"ש רז\"ל במדרש שה\"ש בפסוק אתי מלבנון<sup data-n=\"2919\">11</sup> דך\"ו ע\"ב אית מאן דחזי<sup data-n=\"2920\">12</sup> ולא מהימן בתמי'<sup data-n=\"2921\">13</sup>.\n<b>אך</b> הענין הוא, דהנה צ\"ל מ\"ש (תהלים סי'<sup data-n=\"2923\">15</sup> ל\"ד) יראו את ה'<sup data-n=\"2922\">14</sup> קדושיו כי אין מחסור ליריאיו, שהרי נאמר מתחלה במזמור ל\"ג יראו מה'<sup data-n=\"2924\">16</sup> כל הארץ ולמה נאמר כאן יראו את ה' קדושיו דוקא, וגם מהו נתינת הטעם ע\"ז כי אין מחסור ליריאיו. אך הענין הוא, דהנה יש ב' בחי' יראה<sup data-n=\"2925\">17</sup>, יראה תתאה ויראה עילאה, והנה מ\"ש יראו מה' כל הארץ היינו בחי' יר\"ת<sup data-n=\"2926\">18</sup> דהיינו בחי' יראה הנמשכת מהתבוננו' התהוות העולמות וכמ\"ש שם יראו מה' כל הארץ כו' כי הוא אמר ויהי<sup data-n=\"2927\">19</sup>, דהיינו כשיתבונן איך שבאמירה אחת דוקא נברא העולם וכמשארז\"ל בעשרה מאמרות נבה\"ע ומה ת\"ל והלא במאמר א' יכול להבראות<sup data-n=\"2928\">20</sup>, וכן נאמר ברוך שאמר והי' העולם דהיינו שבאמירה אחת<sup data-n=\"2929\">21</sup> נבה\"ע, וכשיתבונן בזה אז תפול עליו יראה ופחד, אך עכ\"ז נק' בחי' יר\"ת לפי שיראה זו נמשך מהתבוננות העולמות שהוא רק בחי' זיו והארה בעלמא, ששרש העולמות נמשך רק מבחי' מאמר ודבור לבד בהבראם בה' בראם<sup data-n=\"2930\">22</sup> שהיא בחי' אתא קלילא<sup data-n=\"2931\">23</sup> דלית בי' מששא, ולזה נק' בחי' יראה תתאה. והנה בבחי' יראה זו כולם שוים ולזה נאמר כאן יראו מה' כל הארץ, והיינו בחי' יראה מרחוק<sup data-n=\"2932\">24</sup> שהוא רחוק מה', פי' מהוי' אינו עצמיות כ\"א הארה בעלמא שהוא בחי' דבור ע\"מ (שבהם נז' רק ש' אלקי' כנודע של\"ב פעמים ש' אלקים נא' בע\"מ<sup data-n=\"2933\">25</sup> שהוא בחי' כח הפועל בנפעל<sup data-n=\"2934\">26</sup> שאמר ויהי, ולכן נא' בראשית ברא<sup data-n=\"2935\">27</sup>, משא\"כ בש' הוי' עצמו כתי'",[["2918","10","<b>ועוד צ\"ל . . להאמין אח\"כ</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' נא. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950460\" data-slug=\"or-hatorah-hb\" data-id=\"8315950460\">אוה\"ת בשלח ע' תס</a>. לקמן בהנחה שם."],["2919","11","<b>במדרש שה\"ש . . אתי מלבנון</b>: שה\"ש ד, ח. שהש\"ר שם ב. הועתק לשונו באוה\"ת בשלח ע' תל."],["2920","12","<b>מאן דחזי</b>: בשהש\"ר שם: בר נש דחמי."],["2921","13","<b>בתמי'</b>: מתנות כהונה שם."],["2923","15","<b>סי'</b>: כשמציינים לתנ\"ך לפעמים משתמשים בתיבת ”סימן\". ולפעמים בתיבת ”קפיטל\". ראה גם לעיל מאמר ד\"ה זכור את יום השבת ובהערה 17."],["2922","14","<b>תהלים סי' ל\"ד) יראו את ה'</b>: פסוק י."],["2924","16","<b>במזמור ל\"ג יראו מה'</b>: פסוק ח [ושם: ייראו — וכ\"ה באוה\"ת בשלח כאן ע' תלב. אבל באוה\"ת שם הנה גם בפסוק יראו את ה' נדפס: ייראו]."],["2925","17","<b>ב' בחי' יראה</b>: ראה הנסמן באוה\"ת שבהערה הבאה."],["2926","18","<b>יראו מהוי' . . יר\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380361\" data-slug=\"likkutei-torah\" data-id=\"4001380361\">לקו\"ת במדבר יג, ב</a>. ד\"ח שער התפלה נב, א ואילך. אוה\"ת בשלח כאן ע' תלב. ע' תס ואילך. לעיל מאמר ד\"ה ועבדתם את ה\"א פ\"ג."],["2927","19","<b>כי הוא אמר ויהי</b>: תהלים לג, ט."],["2928","20","<b>בעשרה מאמרות . . להבראות</b>: אבות רפ\"ה. ראה לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י הערה 19."],["2929","21","<b>ברוך שאמר . . שבאמירה אחת</b>: נוסח ברכת ברוך שאמר. ראה גם שע\"ת עג, א ובהערה 26. לקו\"ת ואתחנן ב, א."],["2930","22","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["2931","23","<b>בה' . . אתא קלילא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381022\" data-slug=\"likkutei-torah\" data-id=\"4001381022\">לקו\"ת האזינו עד, ד</a>: והה' הוא אות קלילא דלית בי' מששא כמבואר באקדמות. תו\"ח ח\"ש קכא, ג ובהערה 48."],["2932","24","<b>יראה מרחוק</b>: ראה גם בענין יראה לקמן מאמר ד\"ה הים ראה וינוס על יד הערה 75."],["2933","25","<b>של\"ב פעמים ש' אלקים נא' בע\"מ</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["2934","26","<b>כח הפועל בנפעל</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת) סוף ש\"ג."],["2935","27","<b>בראשית ברא</b>: בראשית א, א. ראה גם לעיל מאמר ד\"ה ועבדתם את ה\"א רפ\"ב. וש\"נ."]]],[2001910308,"יהללו את ש' הוי' כי הוא ציוה ונבראו<sup data-n=\"2936\">28</sup> מאליו כמ\"ש בלק\"ת בד\"ה קול דודי<sup data-n=\"2937\">29</sup>, וזהו מהוי' היינו מבחי' הארת ש' הוי' ולא עצמיות ש' הוי', ומ\"מ נק' מהוי' לפי שמה שהוא אמר ויהי דהיינו המאמרות דש' אלקים זהו עצמו מה שהוא ציוה ויעמוד<sup data-n=\"2938\">30</sup> שזה קאי על ש' הוי' כמ\"ש ש' הוי' צוה כו' ויעמידם לעד לעולם<sup data-n=\"2939\">31</sup>, לכן נק' מהוי' כו') אבל יראו את ה' קדושיו קאי על בחי' יר\"ע<sup data-n=\"2940\">32</sup> דהיינו יראה הנמשכת מהתבוננות עצמותו ית', איך שלך ה' הגדולה<sup data-n=\"2941\">33</sup> שמדת הגדולה בטל וטפל לך כו' (ופי' לך ה' הגדולה כמארז\"ל ברכות דנ\"ח ע\"א הגדולה זה מע\"ב שבחי' גדולה זו בטל וטפל לך כי גדול הוי' כו' ולגדולתו אין חקר<sup data-n=\"2942\">34</sup> שלגדולתו העצמיות אין חקר כלל כדפי' בת\"א בד\"ה וישט המלך לאסתר דקנ\"ז ע\"ב<sup data-n=\"2943\">35</sup>, שגדולה זו הוא ענוה והשפלה, ולכן לך ה' הגדולה שבחי' גדולתו זו בטל וטפל כו'), וזהו יראו את ה' קדושיו היינו שהוא טפל לבחי' הוי' וכמו שארז\"ל את בשרו<sup data-n=\"2944\">36</sup> את הטפל לבשרו<sup data-n=\"2945\">37</sup> כו', ופי' קדושיו הוא בחי' המצות וכמו שאנו מברכים על כל מצוה אשר קדשנו במצותיו שהם מבחי' קדש העליון, וע\"י המצות מגיעים לבחי' יראו את ה' וכמו שארז\"ל במשנה סוטה<sup data-n=\"2946\">38</sup> קדושה מביאה לידי ענוה<sup data-n=\"2947\">39</sup> וענוה מביאה לידי יראת חטא, (וכמ\"ש בפ' ואתחנן ויצונו ה'<sup data-n=\"2948\">40</sup> לעשות את כל החקים האלה ליראה את ה' אלקינו), והנה בפי' מצוה יש שני פירושי', א' לשון ציווי כמו צו את בנ\"י<sup data-n=\"2950\">42</sup>, והב' ל' צוותא<sup data-n=\"2949\">41</sup> וחיבור וכמו שארז\"ל בפ\"ק דברכות ד\"ו סע\"ב כי זה כל האדם<sup data-n=\"2951\">43</sup> כל העולם כולו לא נברא אלא לצוות לזה.\nב) <b>ולהבין</b> פי' וענין מצוה לפי' הב' שהוא בחי' התחברות, הענין הוא דהנה ארז\"ל בשבת פ\"ט דפ\"ח ע\"א, ע\"פ ויהי ערב כו' יום הששי<sup data-n=\"2953\">45</sup>, תנאי התנה הקב\"ה עם מע\"ב אם יקבלו ישראל את התורה מוטב וא\"ל<sup data-n=\"2952\">44</sup> כו', וכן איתא במד\"ר בראשית פ\"ה<sup data-n=\"2954\">46</sup> ובבשלח פך\"א<sup data-n=\"2955\">47</sup> לאיתנו לתנאו<sup data-n=\"2956\">48</sup>, וקרי\"ס הי' הקדמה למ\"ת<sup data-n=\"2957\">49</sup> כנודע,",[["2936","28","<b>יהללו . . ציוה ונבראו</b>: תהלים קמח, ה. ראה גם לעיל שם ובהערה 79."],["2937","29","<b>בלק\"ת בד\"ה קול דודי</b>: שה\"ש יד, ג."],["2938","30","<b>שהוא ציוה ויעמוד</b>: תהלים לג, ט."],["2939","31","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו."],["2940","32","<b>יראו את ה' . . יר\"ע</b>: ראה הנסמן לעיל בהערה 18."],["2941","33","<b>שלך ה' הגדולה</b>: דברי הימים-א כט, יא."],["2942","34","<b>גדול . . ולגדולתו אין חקר</b>: תהלים קמה, ג."],["2943","35","<b>בת\"א . . ע\"ב</b>: במהדורת קה\"ת מג\"א צד, ב."],["2944","36","<b>את בשרו</b>: משפטים כא, כח."],["2945","37","<b>את הטפל לבשרו</b>: ב\"ק מא, ב."],["2946","38","<b>במשנה סוטה</b>: ועד\"ז לקמן פ\"ו פיסקא וזהו יראו. סה\"מ תרכ\"ז כאן ע' רמח וע' רנה. ראה במשניות שם בסופה. ראה גם במהרש\"א ותויו\"ט שם. אוה\"ת וישב ח\"ב ע' 518: שלהי סוטה . . והברייתא."],["2947","39","<b>קדושה מביאה לידי ענוה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380646\" data-slug=\"likkutei-torah\" data-id=\"4001380646\">לקו\"ת מטות פא, א</a> ואילך."],["2948","40","<b>בפ' ואתחנן ויצונו ה'</b>: ואתחנן ו, כד."],["2950","42","<b>צו את בנ\"י</b>: אמור כד, ב."],["2949","41","<b>מצוה . . ל' צוותא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">לקו\"ת בחוקותי מה, ג</a>. סה\"מ תרל\"ח ע' קכב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071030\" data-slug=\"likkutei-sichot\" data-id=\"1300071030\">לקו\"ש צו כרך ז ע' 30</a> ואילך."],["2951","43","<b>כי זה כל האדם</b>: קהלת יב, יג."],["2953","45","<b>ויהי ערב . . הששי</b>: בראשית א, לא."],["2952","44","<b>ארז\"ל בשבת . . תנאי . . וא\"ל</b>: בשינוי לשון קצת. ראה גם לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום הערה 27."],["2954","46","<b>במד\"ר בראשית פ\"ה</b>: סימן ה."],["2955","47","<b>ובבשלח פך\"א</b>: סימן ו."],["2956","48","<b>לאיתנו לתנאו</b>: בשלח יד, כז. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061097\" data-slug=\"likkutei-sichot\" data-id=\"1300061097\">לקו\"ש בשלח כרך ו' ע' 86</a> ואילך. וש\"נ."],["2957","49","<b>וקרי\"ס הי' הקדמה למ\"ת</b>: ראה שער האמונה לב, ב ובהערה 9. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540550\" data-slug=\"torat-chaim\" data-id=\"2300540550\">תו\"ח בשלח ח\"א קמח, ג</a>. וש\"נ."]]],[2001910309,"וצ\"ל מהו שייך ברה\"ע לתורה. אך הענין הוא, דהנה איתא במדרש<sup data-n=\"2958\">50</sup> ובזהר ויקרא די\"א סע\"ב<sup data-n=\"2959\">51</sup> עשרה עשרה הכף<sup data-n=\"2960\">52</sup> שעשה\"ד הוא מכוון כנגד עשרה מאמרות דבור של אנכי<sup data-n=\"2961\">53</sup> הוא כנגד מאמר יהי אור<sup data-n=\"2962\">54</sup> כו', וע' שם בזהר שחשיב כל העשה\"ד וע\"מ, שנמצא מובן שעש\"מ תלוים בעשה\"ד דוקא שקיום העולם תלוי בתורה, וכמ\"ש אם לא בריתי יומם ולילה חקת שמים וארץ לא שמתי<sup data-n=\"2963\">55</sup>, וכמארז\"ל הנ\"ל שתנאי התנה כו' אם יקבלו ישראל את התורה. והענין הגם דאיתא בגמ' רפ\"ב דחגיגה שבעשרה דברים<sup data-n=\"2964\">56</sup> ברא הקב\"ה את העולם בחכ' ובתבונה ובדעת כו' שנא' ה' בחכמה יסד ארץ כונן שמים בתבונה<sup data-n=\"2965\">57</sup> ובדעתו<sup data-n=\"2966\">58</sup> תהומות נבקעו<sup data-n=\"2967\">59</sup>, וזהו מ\"ש בראשית ברא אלקים ות\"י בחוכמתא ברא<sup data-n=\"2968\">60</sup>, מ\"מ הנה כתיב רבות עשית אתה ה' אלקי נפלאותיך ומחשבותיך אלינו<sup data-n=\"2969\">61</sup>, פי' נפלאותיך ומחשבותיך כו' והיינו שבחי' עשית דהיינו בחי' בריאת העולם נמשך מבחי' נפלאותיך וכמ\"ש בס\"י בשלשים ושתים נתיבות<sup data-n=\"2970\">62</sup> פליאות חכ' חקק כו' וברא את עולמו, ובחי' ענין שלשים ושתים נ\"ח הם כנגד עשרה מאמרות וכ\"ב אותיות<sup data-n=\"2971\">63</sup>, ומחשבותיך הוא בחי' חכ' שנמשך למדות, דהנה כתי' כי ששת ימים<sup data-n=\"2972\">64</sup> עשה ה' את השמים שהתהוות העולמות נתהוה ע\"י בחי' מדות שהמדות הם ששה מדות כו' וכדי שיומשך מבחי' חכ' למדות זהו ע\"י המח' כי מחשבה הוא ממשיך מן החכ' למדות כו', וזהו נפלאותיך ומחשבותיך ששרש העולמות נמשך מבחי' נפלאותיך ומחשבותיך דהיינו מבחי' חכמה ומדות כו', אך כ\"ז הוא אלינו דהיינו שמה שנק' נפלאותיך כו', דהיינו פליאות חכ' הוא רק אלינו, אבל לגבי עצמות אוא\"ס אין ערוך אליך<sup data-n=\"2973\">65</sup> ממש וכמ\"ש כולם בחכ' עשית<sup data-n=\"2974\">66</sup> שאפי' ח\"ע נחשבת כעשי' גשמי'<sup data-n=\"2975\">67</sup> ונק' אדון הנפלאות<sup data-n=\"2976\">68</sup>,",[["2958","50","<b>במדרש</b>: ראה פסיקתא רבתי פיסקא עשה\"ד פכ\"א, יט. מדרש לקח טוב יתרו כ, ב."],["2959","51","<b>ובזהר ויקרא די\"א סע\"ב</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' הערה 52."],["2960","52","<b>עשרה עשרה הכף</b>: נשא ז, פו."],["2961","53","<b>אנכי</b>: יתרו כ, ב."],["2962","54","<b>יהי אור</b>: בראשית א, ג. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 58. שע\"ת יב, ג הערה 42. סה\"מ תר\"ם ח\"א ע' קצ."],["2963","55","<b>אם לא בריתי . . שמתי</b>: ירמי' לג, כה."],["2964","56","<b>רפ\"ב דחגיגה שבעשרה דברים</b>: ראה שם יב, א."],["2965","57","<b>הוי' בחכ' . . בתבונה</b>: משלי ג, יט."],["2966","58","<b>ובדעתו</b>: וכ\"ה גם בסה\"מ תרכ\"ז כאן (ובבוך 1063 שם). בחגיגה שם: בדעת דכתיב בדעתו."],["2967","59","<b>ובדעתו תהומות נבקעו</b>: משלי שם כ [ושם: בדעתו — ראה גם הערה שלפנ\"ז]."],["2968","60","<b>בראשית . . ות\"י בחוכמתא ברא</b>: בראשית א, א. ראה תרגום ירושלמי שם. סה\"מ תר\"ם ח\"ב ע' תקלג. וש\"נ."],["2969","61","<b>רבות עשית . . אלינו</b>: תהלים מ, ו. בסה\"מ תרכ\"ז כאן ניתוסף: אין ערוך אליך.\nראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370148\" data-slug=\"torah-or\" data-id=\"3901370148\">תו\"א מקץ לא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381289\" data-slug=\"likkutei-torah\" data-id=\"4001381289\">לקו\"ת שה\"ש מ, סע\"ב</a> ואילך."],["2970","62","<b>כמ\"ש בס\"י בשלושים ושתים נתיבות</b>: פ\"א, מ\"א."],["2971","63","<b>עשרה מאמרות וכ\"ב אותיות</b>: ראה מאו\"א מערכת ל\"ב נתיבות אות יט וביאיר נתיב שם. ראה גם אוה\"ת יתרו כרך ז ע' ב'תרפד."],["2972","64","<b>כי ששת ימים</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, רע\"ב. האזינו חצר, ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["2973","65","<b>אין ערוך אליך</b>: תהלים מ, ו. ראה לעיל הערה 61."],["2974","66","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["2975","67","<b>שאפי' ח\"ע . . כעשי' גשמי'</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה ובהערה 67."],["2976","68","<b>אדון הנפלאות</b>: ברכת ישתבח וברכת יוצר. ראה גם לקמן פ\"ז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370210\" data-slug=\"torah-or\" data-id=\"3901370210\">תו\"א ויחי מו, ב</a> ואילך."]]],[2001910310,"עושה פלא<sup data-n=\"2977\">69</sup>, שאפי' בחי' פלא היינו ל\"ב נתיבות פליאות חכמה, כעשיי' גשמיות נחשבת לפניו ית', ולכן אין ערוך אליך.\n<b>והנה</b> מאחר שאין ערוך אליך לזה צריך להמשיך אוא\"ס בע\"מ, וכמ\"ש את ה' האמרת היום<sup data-n=\"2978\">70</sup> שצריך להמשיך המשכת אוא\"ס בע\"מ (ופי' האמרת להמשיך אותו ית' שיהי' אומר גם עכשיו המאמרות, כי לעולם ה' דברך נצב בשמים<sup data-n=\"2979\">71</sup> שפי' במד\"ת<sup data-n=\"2980\">72</sup> ובסש\"ב ח\"ב בשם הבעש\"ט ז\"ל<sup data-n=\"2981\">73</sup> שדבר ה' עומד תמיד בשמים להוותו ולהחיותו, ואם הי' מסתלק כרגע הי' נעשה אין ואפס מן השמים, וכ\"ה בכל הנבראים שלכל נברא יש איזה צירוף מע\"מ המחי' אותו ע\"י חילופים ותמורות כמ\"ש בסש\"ב ח\"ב ע\"ש, וא\"כ מוכרח שיאמר תמיד המאמרות שהם מחיים ומהוים כלליות הנבראים שנבראו בשמים ובארץ) וזהו ע\"י התורה כי אורייתא מח\"ע נפקת<sup data-n=\"2982\">74</sup> ואורייתא וקודב\"ה כולא חד<sup data-n=\"2983\">75</sup> ולכן ע\"י התורה ממשיכים אוא\"ס בע\"מ, וזהו ענין שעשה\"ד הוא מכוון כנגד עש\"מ דהיינו שע\"י עשה\"ד עי\"ז נמשך בע\"מ, דהנה עשה\"ד הוא כללות כל המצות<sup data-n=\"2984\">76</sup> (שאנכי כולל רמ\"ח מ\"ע ולא יהי' לך<sup data-n=\"2986\">78</sup> כולל שס\"ה ל\"ת<sup data-n=\"2985\">77</sup> כמ\"ש בסש\"ב רפ\"ך ובזח\"ב יתרו דצ\"א ע\"א, ובד\"פ יותר הנה) רמ\"ח פקודין הוא רמ\"ח אברים<sup data-n=\"2988\">80</sup> דמלכא<sup data-n=\"2987\">79</sup> (ושס\"ה ל\"ת הם שס\"ה<sup data-n=\"2990\">82</sup> גידים<sup data-n=\"2989\">81</sup>, וכללותם הוא בחי' אדם), והנה אנו רואים שבאדם אף שיש לו רמ\"ח אברים (ושס\"ה גידים) אעפ\"כ נכללים בעשר בחי' דהיינו שהראש הוא כולל תלת מוחין חב\"ד וגלגלתא דחפי' על מוחא<sup data-n=\"2991\">83</sup>, וגוף ותרין דרועין שהיא בחי' חג\"ת, ונו\"ה תרין שוקין ויסוד הוא סיומא דגופא אות ברית קדש<sup data-n=\"2992\">84</sup>, וכך רמ\"ח פקודין שהוא בחי' רמ\"ח אברי' דמלכא",[["2977","69","<b>עושה פלא</b>: בשלח טו, יא. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370282\" data-slug=\"torah-or\" data-id=\"3901370282\">תו\"א בשלח סג, א</a>. מאמרי אדה\"א דברים ח\"ג ע' תתמט. וש\"נ."],["2978","70","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["2979","71","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט."],["2980","72","<b>שפי' במד\"ת</b>: קיט, לו. ראה גם סה\"מ תר\"ם ח\"א ע' רלה. וש\"נ. תרל\"ח ע' כב. וש\"נ."],["2981","73","<b>ובסש\"ב ח\"ב בשם הבעש\"ט ז\"ל</b>: פ\"א. ראה גם לקמן מאמר ד\"ה שיר המעלות ממעמקים רפ\"ב. ד\"ה ושאבתם מים בששון פ\"ג. הנסמן בסה\"מ תרל\"ח ותר\"ם שם־ כתר שם טוב קה\"ת מהדורת תשנ\"ט בהוספות סע\"ז."],["2982","74","<b>אורייתא מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2983","75","<b>ואורייתא וקודב\"ה כולא חד</b>: מובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא (פ\"ד</a> ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."],["2984","76","<b>עשה\"ד הוא . . המצות</b>: ראה רש\"י משפטים כד, יב."],["2986","78","<b>ולא יהי' לך</b>: יתרו כ, ג."],["2985","77","<b>רמ\"ח מ\"ע . . שס\"ה ל\"ת</b>: מכות כג, סע\"ב."],["2988","80","<b>רמ\"ח אברים</b>: אהלות פ\"א, מ\"ח."],["2987","79","<b>רמ\"ח פקודין הוא רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["2990","82","<b>שס\"ה גידים</b>: ראה הערה שלפנ\"ז. ע\"ח שער פנו\"ח ש\"מ, דרוש יב: אותן הגידין שזכרו רז\"ל אינן אותן הלבנים. עשרה מאמרות מאמר חיקור דין ח\"א, פי\"א ובכנפי יונה ח\"א, פע\"א בשם הראב\"ע בס' העצמים [לונדון תרס\"א ע' כו] שס\"ה גידין כפולין. סה\"מ תרכ\"ח ע' קכט ואילך בשם המד\"ר."],["2989","81","<b>ושס\"ה ל\"ת הם שס\"ה גידים</b>: תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב."],["2991","83","<b>וגלגלתא דחפי' על מוחא</b>: ראה זהר אד\"ר נשא קכח, ב."],["2992","84","<b>וגוף ותרין דרועין . . קדש</b>: ראה ת\"ז בהקדמה יז, א."]]],[2001910311,"נכללים בעשר בחי' שזהו ענין עשה\"ד, ולכן יש בעשה\"ד תרי\"ג אותיות כנגד תרי\"ג מצות (וז' הנוספות הם נגד ז\"מ דרבנן<sup data-n=\"2994\">86</sup> כמ\"ש במד\"ר<sup data-n=\"2993\">85</sup>) לפי שהם כללות כל המצות שנק' בשם אדם וכמ\"ש זאת התורה אדם<sup data-n=\"2995\">87</sup> כו' שהתורה הוא בחי' אדם, והגם שברה\"ע הי' ג\"כ בעשרה דברים ובע\"מ י\"ל שהם ע\"ס שבמל', א\"נ ע\"מ הם ע\"ס שבמל' והעשרה דברים שברא בהם הקב\"ה בחכ' כו' הם בחי' מל' שבכל ספירה כנודע שמבחי' מל' שבחכ'<sup data-n=\"2996\">88</sup> נעשה חכ' שבמל', אבל התורה היינו בחי' עשרת הדברות הם ע\"ס עצמם, או שהעשרה דברים שבהם ברא הם ע\"ס דז\"א שכולל גם מוחין דז\"א, והעשרת הדברות הם ע\"ס שבחכ' והשראת אוא\"ס הוא בחכ' דוקא כמ\"ש בסש\"ב פל\"ה בהג\"ה, לכן ע\"י עשה\"ד נמשך המשכת אוא\"ס גם בעשרה דברים הנ\"ל ובעש\"מ שהוא בחי' ע\"ס דז\"א ומל'.\nג) <b>והנה</b> דרך כלל נחלק התורה בג' בחי' תורה ועבודה וגמ\"ח, שזהו משארז\"ל על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח<sup data-n=\"2997\">89</sup>, פי' עבודה שהוא בחי' הקרבנות<sup data-n=\"2998\">90</sup> הוא בבחי' העלאה ממטה למעלה<sup data-n=\"2999\">91</sup>, וגמ\"ח הוא בחי' המשכה<sup data-n=\"3000\">92</sup> מלמעלה למטה, ותורה היא בחי' קו האמצעי כו'. ולהבין ענין העבודה שהוא בחי' העלאה, הנה עיקר הקרבנות שהוא בחי' קדשי קדשים הי' שחיטתן בצפון<sup data-n=\"3001\">93</sup> וכמ\"ש ושחט אותו על ירך המזבח צפונה<sup data-n=\"3002\">94</sup> כו' וכתי' הר ציון ירכתי צפון<sup data-n=\"3003\">95</sup>, וכן ארז\"ל במשנה העולה קדש קדשים שחיטתה בצפון<sup data-n=\"3004\">96</sup>, וצ\"ל מפני מה קד\"ק שחיטתן בצפון דוקא שהרי צפון הוא בחי' גבורה<sup data-n=\"3005\">97</sup>, וכן תפלה שבמקום קרבנות<sup data-n=\"3006\">98</sup> צ\"ל",[["2994","86","<b>תרי\"ג מצות . . ז\"מ דרבנן</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה קדש ישראל לה' ובהערות 131 ואילך."],["2993","85","<b>בעשה\"ד תרי\"ג אותיות . . במד\"ר</b>: ראה שם פי\"ח, כא. תנחומא קרח יב. כתר תורה הובא בתורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, סע\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380277\" data-slug=\"likkutei-torah\" data-id=\"4001380277\">לקו\"ת בחוקותי מו, ד</a>: ”וברבות נשא פי\"ג [טוטז] איתא תרי\"ג אותיות יש מן אנכי עד אשר לרעך ושבעה יתירות כנגד שבעה ימי בראשית עכ\"ל\"."],["2995","87","<b>זאת התורה אדם</b>: חוקת יט, יד. ראה זהר רע\"מ משפטים קיז, ב. צו כט, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370354\" data-slug=\"torah-or\" data-id=\"3901370354\">תו\"א תרומה עט, ג</a>. מאמרי אדה\"א דברים ח\"ד ע' א'שכז. וש\"נ."],["2996","88","<b>שמבחי' מל' שבחכ'</b>: ראה ע\"ח שער מיעוט הירח של\"ו, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תשצה. שעה\"י קמא, ב ובהערה 41. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550485\" data-slug=\"torat-chaim\" data-id=\"2300550485\">תו\"ח יתרו ח\"ב רסח, ג</a>. סה\"מ תרל\"ח ע' ח ובהערה 71."],["2997","89","<b>על שלשה דברים . . גמ\"ח</b>: אבות פ\"א, מ\"ב."],["2998","90","<b>עבודה . . הקרבנות</b>: ראה מפרשים לאבות שם. סה\"מ תרל\"ח ע' לד הערה 79."],["2999","91","<b>הקרבנות . . העלאה ממטה למעלה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא פל\"ד</a>. אגה\"ת ספי\"ב. אגה\"ק סוס\"כ. סכ\"ח. סה\"מ תר\"ם ח\"א ע' יד. וש\"נ. לקמן מאמר ד\"ה כתר יתנו לך ספ\"ג."],["3000","92","<b>וגמ\"ח . . המשכה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670436\" data-slug=\"torat-chaim\" data-id=\"2300670436\">תו\"ח בראשית כו, ג</a>."],["3001","93","<b>קדשי קדשים הי' שחיטתן בצפון</b>: זבחים פ\"ה, מ\"א-ה. ראה סה\"מ תרכ\"ז ע' רמט ואילך. וש\"נ. וראה גם ש\"א ט, ב ואילך ובהערה 39. סה\"מ תרל\"א ח\"א ע' קי. וש\"נ."],["3002","94","<b>ושחט אותו . . צפונה</b>: ויקרא א, יא."],["3003","95","<b>הר ציון ירכתי צפון</b>: תהלים מח, ג. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן ובהערות 101־ 102."],["3004","96","<b>העולה . . שחיטתה בצפון</b>: זבחים פ\"ה, מ\"ד."],["3005","97","<b>צפון . . גבורה</b>: ראה זהר בראשית כט, ב ובאור החמה שם. פרדס שעה\"כ שכ\"ג, פי\"ח מערכת צפון. מאו\"א מערכת צפון אות כו וביאיר נתיב שם. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תמא."],["3006","98","<b>תפלה שבמקום קרבנות</b>: ברכות כו, א-ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380630\" data-slug=\"likkutei-torah\" data-id=\"4001380630\">לקו\"ת פינחס עז, ג</a>. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."]]],[2001910312,"ג\"כ ע\"ד שמאלו תחת לראשי<sup data-n=\"3007\">99</sup>. אך הענין הוא דהנה צפון אף שהוא בחי' גבורה מ\"מ הנה יש מעלה בבחי' גבורה שהוא בבחי' תגבורת החיות<sup data-n=\"3008\">100</sup> וכמו גבורות גשמים<sup data-n=\"3009\">101</sup> שיורדין בגבורה, והם השפעת החיים וחסד וכמו שאומרים מוריד הגשם<sup data-n=\"3010\">102</sup> מכלכל חיים בחסד, וכן הדם שהוא בחי' גבורה<sup data-n=\"3011\">103</sup> מ\"מ עיקר החיות של האדם מלובש בדם כמ\"ש כי הדם הוא הנפש<sup data-n=\"3012\">104</sup>, והיינו מפני כי תגבורת החיות הוא מבחי' הגבורה דוקא, וכתי' ימי שנותינו כו' ואם בגבורות שמונים שנה<sup data-n=\"3013\">105</sup>, שמבחי' הגבורה שהוא תגבורת החיות נמשך אריכת ימים יותר<sup data-n=\"3014\">106</sup> כו', וזהו ג\"כ הטעם מה שקד\"ק שחיטתן בצפון בחי' גבורה לפי שקרבנות הם בבחי' העלאה ממטה למעלה שהיו מקריבין בהמה גשמי' ע\"ג המזבח והי' נכללת באש שלמטה ואש שלמעלה<sup data-n=\"3015\">107</sup> בחי' ארי' דאכיל קרבנין<sup data-n=\"3016\">108</sup>, וכל העלאה הוא ע\"י גבורות, והיינו מטעם הנ\"ל כי להיות כי הגבורה הוא בחי' תגבורת החיות לכן כל בחי' העליות הוא ע\"י הגבורה דוקא, כי כדי שיהי' בו כח להתעלות זהו ע\"י בחי' תגבורת החיות כו', ולכן הי' שחיטתן בצפון, וזהו העולה קדש קדשים שחיטתה בצפון, לפי שעולה היא העלאה בבחי' קדש הקדשים שהוא בחי' גבוה מאד לכן שחיטתה בצפון כו' שהעלי' הוא ע\"י הגבורות. והנה עכשיו תפלות כנגד תמידין תקנו<sup data-n=\"3017\">109</sup>, ולכן צריך שיהי' התפלה ג\"כ בבחי' העלאה בבחי' רשפי אש התשוקה להיות נכלל למעלה, וצריך לשרוף את כל ההרהורין בישין ומחשבות זרות אשר לא לה' המה כמו שהיו שורפין את הקרבן ע\"ג המזבח וכמו שע\"י שריפת הקרבן עי\"ז הי' עולה לה' בבחי' אשה ריח ניחוח<sup data-n=\"3018\">110</sup>, כך ע\"י שריפת הנה\"ב שהוא שורף את כל המחשבות והרהורין בישין עי\"ז עולה לה' לריח ניחוח, והיינו שהרתיחות הדמים שיש לו להבלי העולם יהפוך אותם להיות בתשוקה ורשפי אש לאלקות.\n<b>ובזה</b> יובן מ\"ש במדרש שה\"ש בפסוק לסוסתי ברכבי פרעה<sup data-n=\"3020\">112</sup> דף יו\"ד<sup data-n=\"3019\">111</sup> והמים להם חומה מימינם ומשמאלם<sup data-n=\"3021\">113</sup>, והמים להם חומה מימינם זה ק\"ש",[["3007","99","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["3008","100","<b>גבורה . . תגבורת החיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a>. לעיל מאמר ד\"ה וברך את לחמך ובהערה 88."],["3009","101","<b>גבורות גשמים</b>: תענית ב, א. ראה גם לקו\"ת ואתחנן יג, ג. סה\"מ תר\"ם ח\"א ע' פא. וש\"נ."],["3010","102","<b>שאומרים מוריד הגשם</b>: בברכת אתה גבור בתפלת העמידה."],["3011","103","<b>הדם . . גבורה</b>: ראה מאו\"א מערכת דם אות טז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550165\" data-slug=\"torat-chaim\" data-id=\"2300550165\">תו\"ח פקודי ח\"ב תמו, ד</a> ובהערה 38."],["3012","104","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["3013","105","<b>ימי שנותינו . . שמונים שנה</b>: תהלים צ, י."],["3014","106","<b>אריכת ימים יותר</b>: ראה גם סה\"מ תרע\"ח ע' צג־ תש\"ז ע' 202: ואמרז\"ל ע\"ז [גיטין כח, א] כיון דאפליג איפליג הרי שזהו חיות שבבחי' הפלגה לא כמו בחי' חיות התמידי."],["3015","107","<b>ואש שלמעלה</b>: תו\"כ ויקרא א, ז. יומא כא, ב."],["3016","108","<b>ארי' דאכיל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13. סה\"מ תר\"ם ח\"א ע' מ ואילך."],["3017","109","<b>תפלות כנגד תמידין תקנו</b>: ראה ברכות כו, ב. לקו\"ת פינחס שם."],["3018","110","<b>אשה ריח ניחוח</b>: ויקרא א, ט."],["3020","112","<b>לסוסתי ברכבי פרעה</b>: שה\"ש א, ט."],["3019","111","<b>במדרש שה\"ש . . לסוסתי . . דף יו\"ד</b>: בדפוס אמשטרדם ת\"א. שהש\"ר פ\"א, ט ד. הובא גם באוה\"ת בשלח כאן ע' תלה. בסה\"מ תרע\"ח ותש\"ז שם: דאי' בילקוט ע\"פ והמים כו' מימינם ומשמאלם. ולפנינו שם ליתא. ראה גם מכילתא שבהערה 114."],["3021","113","<b>והמים להם חומה מימינם ומשמאלם</b>: בשלח יד, כב. כט."]]],[2001910313,"ומשמאלם זה תפלה, והקשו המפרשים למה נק' התפלה משמאלם, והמ\"כ תירץ<sup data-n=\"3022\">114</sup> לפי שתפלה הוא חיי שעה<sup data-n=\"3023\">115</sup> ותורה היא חיי עולם<sup data-n=\"3024\">116</sup>, ולכן נק' התפלה משמאלם כי בד\"כ העוה\"ב נק' ימין ועוה\"ז נק' שמאל<sup data-n=\"3025\">117</sup> ולכן תפלה שהיא בקשת חיי העוה\"ז לכן נק' בחי' שמאל, וזהו תירוץ, אך הפי' האמיתי הוא לפי שתפלה צ\"ל ג\"כ בבחי' רשפי אש התשוקה בבחי' רצוא להיות נכלל למעלה שזהו ע\"י גבורה בחי' שמאל דוקא כנ\"ל.\nד) <b>ועוי\"ל</b> דלכך נק' התפלה בחי' שמאל לפי שהתפלה צ\"ל בבחי' שמאל דוחה<sup data-n=\"3027\">119</sup> ועי\"ז נעשה תחת לראשי<sup data-n=\"3026\">118</sup>, וכמו שארז\"ל אין עומדין להתפלל אלא מתוך כובד ראש<sup data-n=\"3028\">120</sup> (שהוא בחי' הכנעה ושפלות שמשפיל א\"ע), וזהו שאומרים בתפלה סלח לנו<sup data-n=\"3029\">121</sup> כי חטאנו, ולכאו' אינו מובן למה אומרים זה בשמ\"ע שהוא אחר פסוד\"ז וק\"ש, שהרי בק\"ש כבר קיבל ע\"ע בחי' מס\"נ באחד<sup data-n=\"3030\">122</sup> וגם בחי' אהבה בכל מאדך<sup data-n=\"3031\">123</sup> שנתקרב יותר אל אלקות ולמה אומרים אח\"כ סלח לנו כי חטאנו, והי' מהראוי לאומרו קודם פסוד\"ז וק\"ש, אך הענין הוא דהנה כתי' (משלי סי' י\"ז ך\"א<sup data-n=\"3032\">124</sup>) מצרף לכסף וכור לזהב ואיש לפי מהללו, וכן כתי' (משלי סי' ך\"ה ה'<sup data-n=\"3033\">125</sup>) הגו סיגים מכסף ויצא לצורף כלי, והיינו שמתחלה מעורב הסיגים עם הכסף ונראה גם הסיגים שהוא כסף, אך ע\"י המצרף שהוא מצרף ומפריד הסיגים מכסף ואז נראה לכל שהוא סיגים, וכך הוא בעבודת האדם שמתחלה קודם התפלה דרך איש ישר בעיניו<sup data-n=\"3034\">126</sup>, וכשאינו עושה עבירה בפו\"מ וגם הוא לומד תורה אז נדמה לו שהוא קרוב לאלקות, אך באמת כספך הי' לסיגים<sup data-n=\"3035\">127</sup>, דהיינו שכסף הוא בחי' האהבה<sup data-n=\"3036\">128</sup>, והאהבה שקודם התפלה עדיין היא מעורבת עם סיגים ופסולת כו', אך ע\"י פסוד\"ז וק\"ש שמקבל ע\"ע בחי' מס\"נ באחד ואהבה עי\"ז נפרד הפסולת ואז הוא",[["3022","114","<b>והמ\"כ תירץ</b>: ראה שם ד\"ה תפלה. וראה גם פי' זה ינחמינו על המכילתא בשלח יד, כח [אלא ששם הגירסא תורה ולא ק\"ש]."],["3023","115","<b>שתפלה הוא חיי שעה</b>: שבת י, א."],["3024","116","<b>ותורה היא חיי עולם</b>: שבת שם."],["3025","117","<b>העוה\"ב . . ימין ועוה\"ז . . שמאל</b>: ראה ב\"ר פנ\"ט, ב. ערכי הכנויים לבעל סדה\"ד מערכת ימין עה\"ב. אוה\"ת חנוכה ע' שלז ואילך."],["3027","119","<b>שמאל דוחה</b>: סוטה מז, א."],["3026","118","<b>שהתפלה . . שמאל דוחה . . תחת לראשי</b>: ראה תו\"א תשא פה, ג ואילך."],["3028","120","<b>אין עומדין . . כובד ראש</b>: ברכות ל, ב. ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקו ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540911\" data-slug=\"torat-chaim\" data-id=\"2300540911\">תו\"ח בשלח ח\"א קעז, א</a>. סה\"מ תרכ\"ט ע' קסו. וש\"נ."],["3029","121","<b>שאומרים בתפלה סלח לנו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370498\" data-slug=\"torah-or\" data-id=\"3901370498\">תו\"א תשא קיא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380431\" data-slug=\"likkutei-torah\" data-id=\"4001380431\">לקו\"ת בהעלותך ל, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380858\" data-slug=\"likkutei-torah\" data-id=\"4001380858\">תצא לה, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670423\" data-slug=\"torat-chaim\" data-id=\"2300670423\">ש\"ש סה, ג</a>. מאמרי אדה\"א שמות ח\"א ע' קפב. וש\"נ. תו\"ח וירא קד, ב ובהערה 20. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 120."],["3030","122","<b>מס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["3031","123","<b>אהבה בכל מאדך</b>: ואתחנן ו, ה."],["3032","124","<b>משלי סי' י\"ז ך\"א</b>: באוה\"ת בשלח כאן ע' תלה: סי' י\"ז ג' [ושם הובא רק ראשית הכתוב]. בסה\"מ תרכ\"ז כאן ע' רנ: ך\"ג ך\"א. צ\"ל: כז, כא."],["3033","125","<b>ך\"ה ה'</b>: וכ\"ה בסה\"מ תרכ\"ז כאן. צ\"ל: כה, ד."],["3034","126","<b>דרך איש ישר בעיניו</b>: משלי כא, ב."],["3035","127","<b>כספך הי' לסיגים</b>: ישעי' א, כב."],["3036","128","<b>שכסף . . האהבה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310055\" data-slug=\"tanya\" data-id=\"3401310055\">תניא פ\"נ</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370126\" data-slug=\"torah-or\" data-id=\"3901370126\">תו\"א וישב כו, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540091\" data-slug=\"torat-chaim\" data-id=\"2300540091\">תשא פו, ד</a>. תו\"ח וארא ח\"א נג, ג. וש\"נ."]]],[2001910314,"מבין ומרגיש איך שהוא עדיין רחוק מאלקות, וזהו ואיש לפי מהללו שלפי ההילול ושבח שבפסוד\"ז וק\"ש עי\"ז הוא נצרף ונפרד הרע מהטוב כו', ולכן אומר בשמ\"ע סלח לנו כי חטאנו, וזהו ענין שמאל דוחה שבתפלה נעשה בחי' שמאל דוחה, שדוחה ומשפיל א\"ע, והנה עי\"ז שהוא דוחה ומשפיל א\"ע ואומר כי חטאנו ועי\"ז נעשה בחי' תחת לראשי שעי\"ז נעשה בחי' נשיאות ראש שהוא בחי' העלאה מלמטלמ\"ע בבחי' אהבה ברשפי אש התשוקה, וכמ\"ש אם נבלת בהתנשא<sup data-n=\"3037\">129</sup> כל המשפיל א\"ע<sup data-n=\"3038\">130</sup> הקב\"ה מגביהו, וזהו מ\"ש בגמ' פסחים ד\"נ ע\"א גבי רב יוסף ברי' דריב\"ל שראה עליונים למטה ותחתונים למעלה א\"ל עולם ברור ראית, שבחי' עולם ברור תחתונים למעלה, שכל מה שהוא בעיניו תחתון יותר בעוה\"ז הוא למעלה יותר בעולם העליון כו' (וכמו שאמר רב מתיבתא בזח\"ג פ' שלח<sup data-n=\"3039\">131</sup> מאן דאיהו רב איהו זעיר ומאן דאיהו זעיר איהו רב כו').\n<b>והנה</b> בקרבנות הי' ג\"כ בחי' שמאל דוחה, והיינו שזה הי' עבודת תרומת הדשן<sup data-n=\"3040\">132</sup>, דהנה הדשן הוא האפר והפסולת שנשאר מהקרבן, שהטוב של הקרבן עולה לריח ניחוח לה' והאפר נשאר שהוא ענין בחי' שמאל דוחה, והנה בתרומת הדשן יש ג\"כ שני בחי' דהיינו מה שהיו מניחין הדשן אצל המזבח וכמ\"ש והרים את הדשן ושמו אצל המזבח<sup data-n=\"3041\">133</sup> והי' נבלע שם<sup data-n=\"3042\">134</sup>, והב' מה שהיו מוציאים הדשן מחוץ למחנה וכמ\"ש והוציא את הדשן אל מחוץ למחנה<sup data-n=\"3043\">135</sup>, והיינו שהאפר גופא הגם שהוא פסולת אעפ\"כ יש בו גם בחי' טוב עדיין שהוא יכול לעלות למעלה וכמ\"ש ביעקב ויאבק איש עמו<sup data-n=\"3044\">136</sup> עד עלות השחר, וארז\"ל שהעלו אבק עד כסה\"כ<sup data-n=\"3045\">137</sup>, ופי' בזהר וישלח דק\"ע<sup data-n=\"3046\">138</sup> אבק דאשתאר מן נורא, והיינו שיעקב העלה גם בחי' האבק, וכמו\"כ הדשן שהיו מניחין אצל המזבח הטוב שבו הי' נבלע במקומו, וזהו עלייתו, אך הדשן שהיו מוציאין מחוץ למחנה היינו מה שלא הי' יכול לעלות, ובעבודה ב' בחי' אלו זהו ענין מרירות על הריחוק ועצבות<sup data-n=\"3047\">139</sup>, שהמרירות אף שהיא בחי' שמאל דוחה, אעפ\"כ עי\"ז נעשה תחת לראשי, בחי' ימין מקרבת<sup data-n=\"3048\">140</sup> שעי\"ז נעשה ויצעקו אל ה'<sup data-n=\"3049\">141</sup> בצר",[["3037","129","<b>אם נבלת בהתנשא</b>: משלי ל, לב."],["3038","130","<b>כל המשפיל א\"ע</b>: ערובין יג, ב (כגי' הע\"י). וכ\"ה גם בסה\"מ תרכ\"ז כאן ע' רנא. שע\"ת כג, א הערה 12. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 132."],["3039","131","<b>בזח\"ג פ' שלח</b>: קסח, סע\"א. ראה גם תוספתא ח\"ש קכב, ב (בשינוי הסדר)."],["3040","132","<b>בקרבנות . . שמאל דוחה . . תרומת הדשן</b>: ראה סידור שחרית ל, ג ואילך. ד\"ח נד, ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770097\" data-slug=\"or-hatorah-hb\" data-id=\"8316770097\">אוה\"ת בשלח ס\"ע תלה</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600727\" data-slug=\"or-hatorah-hb\" data-id=\"8316600727\">ע' תסג</a>. שה\"ש כרך ב ע' תשכז. סה\"מ תרכ\"ט ע' רסב. הנסמן בסה\"מ תרכ\"ז כאן."],["3041","133","<b>והרים את הדשן . . המזבח</b>: צו ו, ג [בדילוג]."],["3042","134","<b>והי' נבלע שם</b>: ראה רש\"י ויקרא א, טז ד\"ה אל מקום הדשן. פסחים כו, א ד\"ה תרומת הדשן. מנחות עד, א ד\"ה אלא אבית הדשן דלמטה. תוד\"ה נבלעין במקומן יומא כא, א."],["3043","135","<b>והוציא את הדשן . . למחנה</b>: צו ו, ד."],["3044","136","<b>ויאבק איש עמו</b>: וישלח לב, כב. ראה תו\"א וישלח כו, ד."],["3045","137","<b>שהעלו אבק עד כסה\"כ</b>: ראה חולין צא, א."],["3046","138","<b>דק\"ע</b>: ע\"א."],["3047","139","<b>מרירות . . ועצבות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א</a>."],["3048","140","<b>ימין מקרבת</b>: סוטה מז, א."],["3049","141","<b>ויצעקו אל ה'</b>: תהלים קז, ו. כח."]]],[2001910315,"להם, ואח\"כ ע\"י המרירות יבא לבחי' שמחה<sup data-n=\"3050\">142</sup>, כי כל המשפיל א\"ע הקב\"ה מגביהו, וזוכה לנשיאות ראש, והיינו ע\"י התבוננות שמתבונן אחר השפלות והכנעה איך דגם חשך לא יחשיך ממך<sup data-n=\"3051\">143</sup>, ומרחוק ה' נראה לי<sup data-n=\"3052\">144</sup>, בזאת יהי' מן השפלות העלאת מ\"ן<sup data-n=\"3053\">145</sup> להכלל באחדות ה' כו', משא\"כ עצבות הוא אסקופה הנדרסת<sup data-n=\"3054\">146</sup> לכל העוונות שמייאש א\"ע מכל וכל וזהו מקור לכל העוונות ולכן צריך לדחות את העצבות מכל וכל, וזהו ענין האפר שהוציאו מחוץ למחנה כו', וז\"ע הקרבנות בחי' עבודה תיקון קו השמאל כו'.\n<b>אך</b> הנה הקרבן הי' מקריב אותו הכהן<sup data-n=\"3055\">147</sup> דוקא שהוא בחי' חסד<sup data-n=\"3056\">148</sup>, דהנה עיקר המכוון מבחי' שמאל דוחה הוא כדי שיהי' לאכללא שמאלא בימינא<sup data-n=\"3057\">149</sup> שזהו עיקר תיקון קו השמאל, שעיקר המכוון מבחי' העלאה הוא כדי שיהי' אח\"כ בחי' המשכה מלמעלה למטה בחי' ימין מקרבת. וזה הי' חטא קרח שרצה להפריד את השמאל<sup data-n=\"3058\">150</sup> מבחי' ימין ולא רצה שיהי' נכלל שמאל בימין ע\"כ נענש, כמ\"ש בזהר ר\"פ קרח, כי עכשיו העיקר הוא קו הימין, כי מבחי' קו הימין לא נמצא יניקת החיצונים כ\"כ כמו מקו השמאל כמ\"ש בלק\"ת בד\"ה זאת חקת<sup data-n=\"3059\">151</sup> התורה פ\"ב, ובכמה דוכתי, ולזה הקרבנות הי' ע\"י הכהן דוקא שהוא איש החסד כו'. וזהו ענין גמ\"ח שהוא בחי' המשכה מלמעלה למטה, וזהו ג\"כ ענין מדת אברהם שהי' ג\"כ איש החסד<sup data-n=\"3060\">152</sup> שכל עיקר עבודתו הי' כדי להמשיך אלקות מלמעלה למטה ולזה הי' מאכיל ומשקה גם לערביים<sup data-n=\"3061\">153</sup> והי' אומר להם דעו למי מברכים<sup data-n=\"3062\">154</sup> שהי' מודיע אלקותו ית' בעולם, ועי\"ז הי' ממשיך אלקות מלמעלה למטה שיהי' ש\"ש מתאהב ע\"י<sup data-n=\"3063\">155</sup>, וזהו מ\"ש אלה תולדות יצחק<sup data-n=\"3064\">156</sup> בן אברהם אברהם הוליד את יצחק שנא' ב\"פ אברהם<sup data-n=\"3065\">157</sup>, שבתחלה",[["3050","142","<b>ע\"י המרירות . . שמחה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a> ופל\"א."],["3051","143","<b>דגם חושך לא יחשיך ממך</b>: תהלים קלט, יב."],["3052","144","<b>ומרחוק ה' נראה לי</b>: ירמי' לא, ב."],["3053","145","<b>מ\"ן</b>: ראה לקמן הערה 158."],["3054","146","<b>אסקופה הנדרסת</b>: ערובין צח, א. ראה גם מאמרי אדה\"א נ\"ך ע' לא ואילך. וש\"נ."],["3055","147","<b>הקרבן הי' מקריב . . הכהן</b>: ויקרא פ\"א, ה ואילך."],["3056","148","<b>הכהן . . חסד</b>: ראה זהר נשא קמה, ב. צו כז, א. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["3057","149","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["3058","150","<b>חטא קרח . . להפריד את השמאל</b>: ראה גם סה\"מ תרכ\"ז ע' שמג ואילך ובהנסמן בריש המאמר שם."],["3059","151","<b>קו הימין . . בלק\"ת . . חקת</b>: נו, ג. ראה גם ביאוה\"ז — להצ\"צ — ויחי כרך ב ע' תשמא ואילך. סה\"מ תר\"ן ע' שצ. לעיל מאמר ד\"ה ובירך את לחמך על יד הערה 92."],["3060","152","<b>אברהם . . איש החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["3061","153","<b>אברהם . . מאכיל . . לערביים</b>: ראה ב\"מ פו, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670266\" data-slug=\"torat-chaim\" data-id=\"2300670266\">תו\"ח לך פג, ד</a> הערה 57."],["3062","154","<b>דעו למי מברכים</b>: ראה סוטה י, ב."],["3063","155","<b>ש\"ש מתאהב ע\"י</b>: יומא פו, א. ראה מאמרי אדה\"א שמות ח\"ב ע' שנ. וש\"נ. דברים ח\"א ע' קלה. וש\"נ. סה\"מ תרע\"ח ע' ע ואילך."],["3064","156","<b>אלה תולדות יצחק</b>: תולדות כה, יט [ושם: ואלה — ראה גם תו\"א שבהערה הבאה. לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב בהנחה כאן]."],["3065","157","<b>אלה תולדות . . ב\"פ אברהם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370081\" data-slug=\"torah-or\" data-id=\"3901370081\">תו\"א תולדות יז, סע\"א</a> ואילך."]]],[2001910316,"צ\"ל מדת אברהם שהוא בחי' חסד כדי לעורר את בחי' העלאה שהוא בחי' המשכת המ\"ד כדי לעורר העלאת המ\"ן<sup data-n=\"3066\">158</sup>, ואח\"כ ע\"י העלאה בחי' יצחק קו השמאל נמשך המשכה מבחי' קו הימין בחי' ימינו תחבקני<sup data-n=\"3067\">159</sup> שהיא בחי' המשכת המ\"ד לאחר העלאת המ\"ן כו'.",[["3066","158","<b>המ\"ד . . המ\"ן</b>: זהר בראשית יז, סע\"ב. יח, רע\"א. ראה גם בענין מ\"ד ומ\"ן מאמרי אדה\"ז תקס\"ג ח\"א ע' קפג ואילך."],["3067","159","<b>ימינו תחבקני</b>: המשך הכתוב שמאלו תחת לראשי — שה\"ש ב, ו [ושם: וימינו]."]]],[2001910317,"<h3>והנה תורה</h3>\n<b></b><b>שבת שאחר הפסח פ' אחרי</b>\nה) <b>והנה</b> תורה היא בחי' קו<sup data-n=\"3069\">161</sup> האמצעי<sup data-n=\"3068\">160</sup>, והענין הוא דהנה התורה נק' ג\"כ בשם מצוה וכמ\"ש תורת ה' תמימה<sup data-n=\"3070\">162</sup> משיבת נפש שהוא קאי על התורה ולזה יש שם ו' פסוקים<sup data-n=\"3071\">163</sup> שהוא כנגד ששה סדרי<sup data-n=\"3073\">165</sup> משנה<sup data-n=\"3072\">164</sup> ובכל פסוק חמשה תיבין כנגד חמשה חומשי תורה, ונאמר שם מצות ה' ברה<sup data-n=\"3074\">166</sup> כו' שהתורה נק' ג\"כ בשם מצוה שהוא בחי' התחברות. והענין הוא דהנה איתא ברע\"מ פ' פנחס דף רך\"ב ע\"ב שדוד הי' מחבר תורה שלמעלה בהקב\"ה<sup data-n=\"3075\">167</sup>. והענין הוא דהנה מבואר למעלה<sup data-n=\"3076\">168</sup> שאע\"פ שבריאת העולמות נמשך מבחי' נפלאותיך ומחשבותיך<sup data-n=\"3077\">169</sup> שהוא בחי' ל\"ב נ\"ח, אעפ\"כ הוא רק אלינו אבל אין ערוך אליך שלעצמות אוא\"ס נחשבת כעשי' גשמי' עושה פלא. וזהו מ\"ש בזהר לאו אורחא דמלכא לאשתעי במילין דהדיוטא כו' שעש\"מ<sup data-n=\"3078\">170</sup> נק' מילין דהדיוטא כו', לפי שעש\"מ נעשו מקור לעולמות בע\"ג,",[["3069","161","<b>תורה . . קו האמצעי</b>: ראה לעיל רפ\"ג."],["3068","160","<b>והנה תורה היא בחי' קו האמצעי</b>: מאמר זה הוא המשך למאמר ד\"ה וירא ישראל את היד הגדולה שנדפס לפנ\"ז — ראה בהערה 1 שם."],["3070","162","<b>תורת ה' תמימה</b>: תהלים יט, ח."],["3071","163","<b>ו' פסוקים</b>: וכ\"ה בסה\"מ תרכ\"ז כאן ע' רנב.\nראה במד\"ר פי\"ג, טז בסופו: ”ג' פסוקים של תורה שבהם ו' סדרי משנה והן מן שתים שתי' [כ\"ה בבמד\"ר ובאוה\"ת שבפיסקא הבאה] פסקה וכל פסקה ופסקה מן חמשה תיבות\". ראה אוה\"ת (יהל אור) תהלים ע' סח: ”וששה פסקות שהם ששה סדרי משנה\". שבועות ע' קלא: ”וגם נחלקים לג' פסוקים שבכל אחד יו\"ד תיבות ולא הי' ששה פסוקים שבכל אחד ה' תיבות\". ראה גם רש\"י שבהערה הבאה.\nהבמד\"ר מובא גם באוה\"ת תהלים ע' סו [ושם: דרנ\"ד ב' — בדפוס אמשטרדם ת\"א]. שבועות ע' קל [ושם: דרנ\"ב ב' וצ\"ל: דרנ\"ד ב']."],["3073","165","<b>ששה סדרי משנה</b>: ראה לעיל מאמר ד\"ה להבין וכו' בענין הציץ הערה 157."],["3072","164","<b>כנגד ששה סדרי משנה</b>: ראה גם (בנוסף לבמד\"ר) ילקוט שמעוני לתהלים שם רמז רדעת. מדרש תהלים שם. רש\"י לתהלים שם פסוק ט."],["3074","166","<b>מצות ה' ברה</b>: תהלים יט, ט."],["3075","167","<b>איתא ברע\"מ . . שדוד . . בהקב\"ה</b>: לעיל מאמר ד\"ה אז ישיר משה רפ\"ג ושם: בס' הבהיר. וש\"נ."],["3076","168","<b>מבואר למעלה</b>: פ\"ב פיסקא ולהבין."],["3077","169","<b>נפלאותיך ומחשבותיך</b>: תהלים מ, ו."],["3078","170","<b>לאו אורחא דמלכא . . שעש\"מ</b>: נסמן לעיל במאמר ד\"ה קדש ישראל לה' פ\"ב הערה 83."]]],[2001910318,"והנה גבול לגבי בלתי בע\"ג הוא אין ערוך כלל<sup data-n=\"3079\">171</sup> יותר משאין ערוך טפה בים אוקיינוס<sup data-n=\"3080\">172</sup> לכן נק' עש\"מ מילין דהדיוטא כו', ופי' מילין דהדיוטא זהו ע\"ד משארז\"ל שיחת חולין של ת\"ח צריכין לימוד<sup data-n=\"3081\">173</sup>, והנה אף ששיחת חולין שלו צריכין לימוד שיש בהם ג\"כ חכ', מ\"מ אין השיחת חולין שלו ערך כלל לגבי עצמות חכמתו, וכך עש\"מ אף שנמשכו מבחי' נפלאותיך ומבחי' מחשבותיך מ\"מ אין ערוך לעצמות חכמתו שהיא בחי' תורה, כי התורה היא למעלה הרבה מבחי' חכ' שבמע\"ב שנק' מאד עמקו מחשבותיך<sup data-n=\"3082\">174</sup> כו'.\n<b>וזהו</b> מ\"ש ואהי' אצלו שעשועי' יום יום<sup data-n=\"3083\">175</sup> שהתורה קדמה לעולם אלפים שנה<sup data-n=\"3084\">176</sup> שהוא למעלה מבחי' עולם, לפי ששרש העולם נמשך מבחי' מדות<sup data-n=\"3085\">177</sup> וכמ\"ש זכור רחמיך וחסדיך<sup data-n=\"3086\">178</sup> כי מעולם, וכתי' כי אמרתי עולם חסד יבנה<sup data-n=\"3087\">179</sup>, וע' בפי' חסד יבנה ובפי' כי מעולם בד\"ה שלש רגלים תחוג לי בשנה<sup data-n=\"3088\">180</sup>, שבחי' מדות שייך לעולם, וקודם שנברא העולם לא הי' על מי להתחסד או לרחם, משא\"כ בחי' חכ' שייך גם קודם שנבה\"ע שהרי החכ' אינה רק גילוי לזולתו שהרי יכול לישב בעצמו ולהשכיל השכלות כו', ועד\"ז יובן ענין מה שקדמה תורה לעולם אלפים שנה לפי שאורייתא מח\"ע נפקת שחכ' שייך קודם שנבה\"ע, וזהו שהתורה נק' משל הקדמוני<sup data-n=\"3089\">181</sup> שהוא משל לבחי' קדמונו ש\"ע, ומה שנתלבשה התורה בגשמיות זהו רק נובלות חכ' שלמעלה תורה<sup data-n=\"3090\">182</sup> שהוא עד\"מ רק כמו בחי' שערות לבד שאף שהשערות מקבלים יניקה מהמוח<sup data-n=\"3091\">183</sup> מ\"מ זהו רק הארה מצומצמת לבד, ולזה כשחותכין את השערות אינו מרגיש שום כאב כלל, וכן עד\"ז התורה שנמשכה למטה אינו רק כמו ע\"ד בחי'",[["3079","171","<b>גבול לגבי בלתי בע\"ג . . כלל</b>: ראה גם לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 69."],["3080","172","<b>טיפה בים אוקיינוס</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' קסד. סהמ\"צ להצ\"צ ע' צא ואילך. מאמרי אדה\"א נ\"ך ע' שלח ואילך."],["3081","173","<b>שיחת חולין . . לימוד</b>: סוכה כא, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380863\" data-slug=\"likkutei-torah\" data-id=\"4001380863\">לקו\"ת תצא לו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380866\" data-slug=\"likkutei-torah\" data-id=\"4001380866\">לז, ב</a>. מאמרי אדה\"א דברים ח\"א ע' ריז. וש\"נ. ח\"ד ע' א'ריט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670071\" data-slug=\"torat-chaim\" data-id=\"2300670071\">תו\"ח בראשית א, ד</a> ובהערה 54. לקמן מאמר ד\"ה ושאבתם מים בששון פ\"ה."],["3082","174","<b>מאד עמקו מחשבותיך</b>: תהלים צב, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381256\" data-slug=\"likkutei-torah\" data-id=\"4001381256\">לקו\"ת שה\"ש לא, סע\"ד</a> ואילך."],["3083","175","<b>ואהי' אצלו שעשועי' יום יום</b>: משלי ח, ל."],["3084","176","<b>שהתורה קדמה לעולם אלפים שנה</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."],["3085","177","<b>ששרש העולם . . מדות</b>: ראה גם אוצרות חיים בתחלתו. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, רע\"א</a>. סה\"מ תרל\"ח ס\"ע שצ. וש\"נ. תר\"ם ח\"א ע' קפה. וש\"נ."],["3086","178","<b>זכור רחמיך וחסדיך</b>: תהלים כה, ו [בדילוג השם]."],["3087","179","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["3088","180","<b>שלש רגלים תחוג לי בשנה</b>: נדפס לעיל — ושם פ\"א פיסקא ולהבין."],["3089","181","<b>שהתורה נק' משל הקדמוני</b>: שמו\"א כד, כג וברש\"י שם. ראה תו\"א מג\"א צח, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תב. שמות ח\"ב ע' שפג. סה\"מ תרל\"ח ע' רפז."],["3090","182","<b>נובלות חכ' שלמעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["3091","183","<b>שהשערות מקבלים יניקה מהמוח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370367\" data-slug=\"torah-or\" data-id=\"3901370367\">תו\"א תצוה פב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370490\" data-slug=\"torah-or\" data-id=\"3901370490\">קי, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380526\" data-slug=\"likkutei-torah\" data-id=\"4001380526\">לקו\"ת קרח נג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380871\" data-slug=\"likkutei-torah\" data-id=\"4001380871\">תצא לח, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380874\" data-slug=\"likkutei-torah\" data-id=\"4001380874\">לט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381275\" data-slug=\"likkutei-torah\" data-id=\"4001381275\">שה\"ש לו, ד</a>. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה להבין וכו' ב' פי' בציץ הערה 19."]]],[2001910319,"שערות, וע' מזה בלק\"ת בביאור תורה צוה בפ' הברכה<sup data-n=\"3092\">184</sup>, וכמ\"ש קווצותיו תלתלים<sup data-n=\"3093\">185</sup> תלי תלים של הלכות<sup data-n=\"3094\">186</sup> כו', שנמשלה לבחי' שערות כו', ולזה צריך לחבר את התורה כמו שהיא למטה עם התורה שלמעלה.\n<b>והנה</b> כדי שיהי' התחברות זו צריך מתחלה לחבר את התורה שלמעלה בהקב\"ה כי באמת לגבי עצמותו כו' גם התורה שלמעלה אף שהיא חכמתו ורצונו ית' מ\"מ אין ערוך אליו כלל רק שהוא מתלבש בתורה וכמו שארז\"ל הקב\"ה יושב ועוסק בתורה<sup data-n=\"3095\">187</sup> דהיינו שהוא משפיל ומתלבש א\"ע בתורה, ולזה צריך להמשיך אוא\"ס בתורה, וזהו ענין התורה לשמה דהיינו לשם התו'<sup data-n=\"3096\">188</sup> כדי שיומשך אוא\"ס בתורה, וזהו דוד הי' מחבר תוש\"מ בהקב\"ה שהמשיך אוא\"ס בתורה, ועי\"ז שהמשיך אוא\"ס בתורה עי\"ז נתחבר גם התורה שנמשכה למטה בתורה שלמעלה, כי המשכת אוא\"ס שממשיכין בתורה שלמעלה זהו ע\"י לימוד התורה לשמה דהיינו מה שלומד את בחי' התורה שנמשכה למטה, כי כל הקורא בתורה הקב\"ה קורא ושונה כנגדו<sup data-n=\"3097\">189</sup> ועי\"ז ממשיך להיות הקב\"ה יושב ועוסק חיבור תורה שלמעלה בהקב\"ה, וכיון שע\"י תורה זו נמשך אוא\"ס בתורה שלמעלה מתחבר גם בחי' תורה שלמטה ג\"כ לתורה שלמעלה כי באמת הוא כולא חד וכמ\"ש ועל תורתך שלמדתנו<sup data-n=\"3098\">190</sup>, על תורתך קאי על התורה כמו שהיא למעלה, ושלמדתנו הוא כמו שנמשכה למטה וכולא חד כו'. אך הנה כל האומר אין לי אלא תורה<sup data-n=\"3099\">191</sup> אפי' תורה אין לו כו', והיינו שהתורה צריך ג\"כ לבחי' עבודה שהיא בחי' תפלה<sup data-n=\"3100\">192</sup> כי רוח אמשיך רוח ואייתי רוח<sup data-n=\"3101\">193</sup> כמ\"ש (איוב סי' ל\"ד י\"ד) אם ישים אליו לבו רוחו ונשמתו אליו יאסוף, וזהו ע\"י התפלה שאז מתעורר אצלו בחי' אהבה לה' בבחי' רשפי אש.\n<b>והכח</b> הזה בנש\"י להמשיך בחי' אוא\"ס בג' קוין לפי שהם בנים למקום שנא' בנים אתם להוי' אלקיכם<sup data-n=\"3102\">194</sup>, שכמו הבן נמשך ממוח האב<sup data-n=\"3103\">195</sup> כמ\"כ נש\"י מיוחדי'",[["3092","184","<b>בלק\"ת . . בפ' הברכה</b>: צה, ב ואילך.\nלפעמים מציין כ\"ק אדמו\"ר הצ\"צ (בלקו\"ת) פ' וזאת הברכה ולפעמים פ' הברכה — ראה גם סה\"מ תר\"ם ח\"א ע' קיט. וש\"נ."],["3093","185","<b>קווצותיו תלתלים</b>: שה\"ש ה, יא."],["3094","186","<b>תלי תלים של הלכות</b>: ערובין כא, סע\"ב."],["3095","187","<b>הקב\"ה יושב ועוסק בתורה</b>: ע\"ז ג, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381136\" data-slug=\"likkutei-torah\" data-id=\"4001381136\">לקו\"ת שה\"ש א, ד</a>. אוה\"ת בהעלותך ע' שסב ואילך."],["3096","188","<b>לשמה דהיינו לשם התו'</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה פ\"ב ופ\"ג ובהנסמן לשם."],["3097","189","<b>כל הקורא . . ושונה כנגדו</b>: בסה\"מ תר\"ם ח\"ב ריש ע' תתקלד: אי' בגמ' — ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540132\" data-slug=\"torat-chaim\" data-id=\"2300540132\">תו\"ח וארא ח\"א נח, ג</a>. וש\"נ."],["3098","190","<b>ועל תורתך שלמדתנו</b>: נוסח ברכת המזון. ראה גם סה\"מ תרל\"ח ע' קנג. וש\"נ."],["3099","191","<b>כל האומר אין לי אלא תורה</b>: ראה יבמות קט, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380094\" data-slug=\"likkutei-torah\" data-id=\"4001380094\">לקו\"ת ויקרא ה, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670436\" data-slug=\"torat-chaim\" data-id=\"2300670436\">שע\"ת עט, ג</a>. תו\"ח בראשית כו, ג ובהערה 34. לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ספ\"ג ובהנסמן שם."],["3100","192","<b>עבודה . . תפלה</b>: ראה גם לעיל פ\"ג."],["3101","193","<b>רוח אמשיך רוח ואייתי רוח</b>: ראה זהר תרומה קסב, רע\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדה\"א בראשית ע' רל. וש\"נ."],["3102","194","<b>בנים אתם להוי' אלקיכם</b>: פ' ראה יד, א."],["3103","195","<b>הבן נמשך ממוח האב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540177\" data-slug=\"torat-chaim\" data-id=\"2300540177\">תו\"ח בא ח\"א קטז, סע\"ב</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111005\" data-slug=\"likkutei-sichot\" data-id=\"1300111005\">לקו\"ש שמות כרך יא ע' 5</a> הערה 48."]]],[2001910320,"ודבקי' בעצמותו ית' כהתקשרות הבן אל האב, ולא כמו התלמיד לרב, וזהו באתי לגני<sup data-n=\"3104\">196</sup> אחותי, פי' באתי לגני בחי' גן סדרים דאוריי'<sup data-n=\"3105\">197</sup> זהו ע\"י בחי' אחותי כלה בחי' כליות<sup data-n=\"3106\">198</sup> הנפש של נש\"י בתפלה* עי\"ז נמשך אוא\"ס בתורה, וזהו ענין ברכו בתורה<sup data-n=\"3107\">199</sup> כו', ואח\"כ ע\"י לימוד התורה עי\"ז נמשך המשכה מבחי' חכ' שבתורה בע\"מ שהם מקור וחיות העולמות, וזהו שעשה\"ד הם מכוונים נגד ע\"מ**, וזהו על שלשה דברים העולם עומד היינו שיהי' לעולם עמידה וקיום חזק זהו ע\"י שלשה דברים שהיא בחי' תורה ועבודה וגמ\"ח כו'. וזהו ענין שהתורה והמצות נק' בשם מצוה לפי שהוא לשון צוותא והתחברות שהם מחברים אוא\"ס עם העולמות כו'.\n\n*)בדרוש<sup data-n=\"8517\">א</sup> וירא ישראל דתקס\"ב<sup data-n=\"8518\">ב</sup> פי' רבינו ז\"ל מפני שהתקשרות ישראל באורייתא ואורייתא בקוב\"ה זהו עצמיות ולא כתלמיד לרב, ולא זכר מס\"נ דתפילה, רק מפני שפי' באתי לגני גן סדרי' כו' זהו ע\"י כלה כליון דנש\"י לכן פי' אאמ\"ו ז\"ל בהגהות לד\"ה הנ\"ל דתרי\"ח<sup data-n=\"8519\">ג</sup> שזהו ג\"כ ע\"י תפלה כו'.\n**)ובמד\"רד ר\"פ ויקהל<sup data-n=\"8521\">ה</sup> ד\"א ואל מי תדמיוני ואשוה<sup data-n=\"8522\">ו</sup> כו' מי ברא אלה<sup data-n=\"8523\">ז</sup>, בזכות מי נבראו אלה תולדות השמים והארץ<sup data-n=\"8524\">ח</sup> ובזכות מי הם עומדים בזכות אלה שמות בנ\"י<sup data-n=\"8525\">ט</sup>, ואלה בזכות מי הם עומדים בזכות אלה העדות והחוקי'<sup data-n=\"8526\">י</sup>, וזהו תנאי התנה הקב\"ה עם מע\"ב, כי קיום העולם הוא ע\"י התורה והמצות דוקא, וזהו ל'<sup data-n=\"8527\">יא</sup> צותא וחיבור<sup data-n=\"8520\">ד</sup>.\nלהעיר<sup data-n=\"8528\">יב</sup> מהמד\"ר אלה תולדות כו' בזכות מי עומדי' בזכות אלה העדות, אלה כו'.",[["3104","196","<b>באתי לגני</b>: שה\"ש ה, א."],["3105","197","<b>גן סדרים דאוריי'</b>: ראה זהר מדהנ\"ע וירא קד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'רג. וש\"נ."],["3106","198","<b>כליות</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן ע' רנד."],["3107","199","<b>ברכו בתורה</b>: ראה גם לעיל מאמר ד\"ה וברך את לחמך פ\"ו. ד\"ה וענין מתיבתא דרקיע.\n\n<b>א</b> ) <b>בדרוש</b>: נרשם בגוכתי\"ק בשני צדדי הגליון בראשו ולא צויין מקומו בפנים.\n\n<b>ב</b> ) <b>וירא ישראל דתקס\"ב</b>: בגוכתי\"ק אינו ברור אם נרשם דתקס\"ב או דתקס\"ד — ראה גם לעיל בריש המאמר וירא ישראל הערה 1.\n\n<b>ג</b> ) <b>בהגהות . . דתרי\"ח</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950439\" data-slug=\"or-hatorah-hb\" data-id=\"8315950439\">אוה\"ת בשלח ע' תלט</a>.\n\n<b>ה</b> ) <b>ובמד\"ר ר\"פ ויקהל</b>: פמ\"ח, [ב]. ראה גם סה\"מ תר\"ם ח\"א ע' רנ. וש\"נ.\n\n<b>ו</b> ) <b>ואל מי תדמיוני ואשוה</b>: ישעי' מ, כה.\n\n<b>ז</b> ) <b>מי ברא אלה</b>: שם מ, כו.\n\n<b>ח</b> ) <b>אלה תולדות השמים והארץ</b>: בראשית ב, ד.\n\n<b>ט</b> ) <b>אלה שמות בנ\"י</b>: שמות א, א [ושם: ואלה — אבל כ\"ה גם בשמו\"ר שם. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה קדש ישראל לה' ובהערה 56].\n\n<b>י</b> ) <b>אלה העדות והחוקי'</b>: ואתחנן ד, מה.\n\n<b>יא</b> ) <b>וזהו ל' צותא וחיבור</b>: בסה\"מ תרכ\"ז כאן ליתא.\n\n<b>ד</b> ) <b>ובמד\"ר . . וחיבור</b>: נרשם בכת\"י מעתיק בשולי היריעה ולא נסמן מקומו בפנים. ובסה\"מ תרכ\"ז כאן נדפס זה בפנים כאן.\n\n<b>יב</b> ) <b>להעיר</b>: נרשם בכת\"י מעתיק באותיות קטנות."]]],[2001910321,"וא\"ו) <b>והנה</b> פי' הב' בתיבת מצוה שהוא ל' ציווי וכמ\"ש צו את בנ\"י כו' שהוא ענין ציווי המלך, הוא ענין בחי' יראה שהוא בחי' קבלת עול והיינו שהמצות צריך לקיים דוקא בבחי' עול<sup data-n=\"3108\">200</sup> לבד בלי טעם כלל, כי ענין הביטול הרצון שמקיים את המצוה בבחי' עול הוא למעלה יותר משהוא מקיים את המצוה ע\"פ טעם וכוונה וכמ\"ש שמואל לשאול הלא שמוע מזבח טוב<sup data-n=\"3109\">201</sup> שהביטול הרצון שבלי טעם וכוונה הוא למעלה מזבח, ששאול הלך עפ\"י הטעם ורצה לזבוח מראשית החרם<sup data-n=\"3110\">202</sup> של עמלק, ולזה טעה ואם הי' מקיים בלי טעם וכוונה רק בבחי' עול לבד לא הי' טועה כו', וזהו שהמצות צריך לקיים בבחי' עול מ\"ש בלבד ויראה תתאה דוקא, לפי שהתחלת העבודה היא ביראה דוקא וכמ\"ש בזאת יבא אהרן<sup data-n=\"3111\">203</sup> אל הקדש בזאת הוא בחי' יר\"ת ודא הוא תרעא לאעלאה<sup data-n=\"3112\">204</sup>, ואף שאהרן כה\"ג הוא בחי' אה\"ר<sup data-n=\"3113\">205</sup> מ\"מ בזאת יבא אל הקדש בבחי' יראה דוקא לפי שנתב\"ס<sup data-n=\"3114\">206</sup> כו', ושרש יר\"ת הוא מבחי' יר\"ע<sup data-n=\"3115\">207</sup>, וע\"כ כדי לבוא אל הקדש הוא ע\"י יראה דוקא.\n<b>וזהו</b> יראו את ה' קדושיו שקדושיו שהוא בחי' קדושת המצות צ\"ל דוקא בבחי' יראו את ה' דהיינו בבחי' יר\"ת דוקא, ונק' את הוי' לפי שבמל' גופא יש שני בחי' יראה, יראו מה' כל הארץ ובחי' יראו את ה', והיינו כי במל' יש שני בחי' א' כמו שהיא נעשה מקור לעולמות הנפרדים שהיא בחי' מל' דאצי' שנעשה כתר וע\"י לבריאה<sup data-n=\"3116\">208</sup> שהוא בחי' אותיות הדבור שהאותיות נראים נפרדים שזהו בחי' יבשה עלמא דאתגלי', ובחי' הב' היינו כמו שהמל' הוא עדיין באצי' ממש שאז נק' בחי' ים<sup data-n=\"3117\">209</sup> דהיינו בחי' עלמא דאתכסי'<sup data-n=\"3118\">210</sup> שהוא כמו למשל אותיות המח' כו' שהם כלולים עדיין בעצמותו כו', וזהו יראו את ה' דהיינו שהיראה היא בבחי' את הוי', את הוא בחי' אותיות שמא' ועד תי\"ו<sup data-n=\"3119\">211</sup>, ואת הוי' היינו כמו שהאותיות הוא עדיין כלול בעצמותו שהוא בחי' אותיות המח', והנה אפילו בחי' זו נק' ג\"כ בחי' יר\"ת לבד, לפי",[["3108","200","<b>שהמצות צריך לקיים . . עול</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380468\" data-slug=\"likkutei-torah\" data-id=\"4001380468\">לקו\"ת שלח לט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">מ, א</a>."],["3109","201","<b>הלא שמוע מזבח טוב</b>: שמו\"א טו, כב [ושם: הנה — ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380797\" data-slug=\"likkutei-torah\" data-id=\"4001380797\">לקו\"ת פ' ראה כ, ב</a>. ג. סה\"מ שבפיסקא הבאה].\nראה מאמרי אדה\"ז אתהלך לאזנא ע' קטו. נביאים ע' ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380797\" data-slug=\"likkutei-torah\" data-id=\"4001380797\">לקו\"ת פ' ראה כ, ב</a>. מאמרי אדה\"א נ\"ך ע' א ואילך. סה\"מ תרל\"ח ע' תמו. וש\"נ."],["3110","202","<b>לזבוח מראשית החרם</b>: שמו\"א שם, כא."],["3111","203","<b>בזאת יבא אהרן</b>: אחרי טז, ג. ראה זהר אחרי נו, ב."],["3112","204","<b>ודא הוא תרעא לאעלאה</b>: ראה זהר בהקדמה ח, רע\"א. יא, ב."],["3113","205","<b>שאהרן כה\"ג . . אה\"ר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תו\"א תצוה פב, א</a> ואילך."],["3114","206","<b>שנתב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["3115","207","<b>ושרש יר\"ת . . יר\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370512\" data-slug=\"torah-or\" data-id=\"3901370512\">תו\"א ויקהל קיד, ד</a>. מאמרי אדה\"א דברים ח\"ב ע' תרנט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670200\" data-slug=\"torat-chaim\" data-id=\"2300670200\">תו\"ח בראשית כא, ג</a> ובהערה 22."],["3116","208","<b>מל' דאצי' . . כתר וע\"י לבריאה</b>: ראה ע\"ח שער כסה\"כ שמ\"ו, פ\"ב. פ\"ד. פ\"ו. שער העקודים ש\"ו, פ\"ב."],["3117","209","<b>מל' . . יבשה . . ים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380133\" data-slug=\"likkutei-torah\" data-id=\"4001380133\">לקו\"ת צו יד, ב</a>. סה\"מ תרל\"ח ע' יב. וש\"נ."],["3118","210","<b>עלמא דאתגלי' . . דאתכסי'</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, רע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."],["3119","211","<b>את . . אותיות שמא' ועד תי\"ו</b>: ראה זהר בראשית כט, ב. רקאנטי בראשית ב, א. שער הכוונות ענין העמידה דרוש ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380774\" data-slug=\"likkutei-torah\" data-id=\"4001380774\">לקו\"ת עקב טו, א</a>. מאמרי אדה\"א שמות ח\"ב ע' שלז. וש\"נ."]]],[2001910322,"שיראה זו היא ג\"כ במל' רק שיראה זו היא בבחי' מל' כמו שהיא באצי', אך המצות הם למעלה מבחי' מל', וזהו יראו את הוי' קדושיו, שכדי לבוא לבחי' קדושיו שהוא בחי' מצות זהו ע\"י בחי' יראו את הוי' מתחלה, שז\"ע קבעמ\"ש. והנה מה שמבואר למעלה שבחי' יראו את הוי' היינו בחי' יר\"ע, וע\"י קדושיו שהוא בחי' מצות מגיעים לבחי' יר\"ע, זהו ג\"כ אמת, כי הנה איתא במשנה קדושה מביאה לידי ענוה וענוה לידי יראת חטא, ופי' יראת חטא אינו יראת העונש לבד, אלא שהוא ירא מהחטא עצמו<sup data-n=\"3120\">212</sup>, וזהו ע\"י קדושה דוקא, כי כשמתבונן איך שהמצוה היא למעלה מאד וע\"י המצוה נעשה התחברות וגילוי אלקות בעולמות, עי\"ז הוא ירא מהחטא יותר דהיינו מעצם החטא, והיינו לפי שכמו שהמצוה מעלה ומגביה את הנפש, כמו\"כ להיפך החטא מוריד ומשפיל מאד וכמ\"ש ואת נפש אויביך יקלענה בתוך כף הקלע<sup data-n=\"3121\">213</sup> כו'<sup data-n=\"3122\">214</sup>, וזהו יראו את הוי' קדושיו שע\"י קדושיו דוקא יוכל לבוא לבחי' יראו את הוי' שהוא בחי' יר\"ע כו'.\n<b>וזהו</b> מ\"ש כי אין מחסור ליריאיו<sup data-n=\"3123\">215</sup>, והענין הוא דהנה ארז\"ל במד\"ר ס\"פ ל\"ח בסוף פ' נח<sup data-n=\"3124\">216</sup>, כ\"מ<sup data-n=\"3125\">217</sup> שנא' אין<sup data-n=\"3126\">218</sup> הוה לה, ותהי שרי עקרה<sup data-n=\"3127\">219</sup> אין לה ולד והוה<sup data-n=\"3128\">220</sup> לה, ולחנה אין לה ילדים<sup data-n=\"3129\">221</sup> והוה לה, ציון<sup data-n=\"3131\">223</sup> דורש אין לה<sup data-n=\"3130\">222</sup> והוה לה, והיינו כי האין ממלא החסרון, ולכן הוה לה. והענין הוא דהנה אין הוא בחי' מ\"ש והחכ' מאין תמצא<sup data-n=\"3132\">224</sup> שאין הוא בחי' כתר<sup data-n=\"3133\">225</sup> ולכך נק' אין לפי שהוא למעלה מהשגה ממש שבבחי' חכ' יש קצת השגה וכמ\"ש במשה וראית את אחורי<sup data-n=\"3134\">226</sup> שמשה השיג אחוריי' דאבא, משא\"כ בכתר אין שם שום השגה ותפיסא ואיהו תפיס בכולהו עלמין<sup data-n=\"3135\">227</sup> ולית מאן",[["3120","212","<b>ירא מהחטא עצמו</b>: ראה גם תויו\"ט סוף סוטה (ד\"ה וענוה). ר\"ח שער היראה ש\"א, ספ\"ג (ד\"ה עוד בחי' ד' — יד, א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת בלק נג, ד</a>. מטות פב, א. סה\"מ תר\"ם ח\"א ע' תעא. וש\"נ."],["3121","213","<b>ואת נפש אויביך . . הקלע</b>: שמו\"א כה, כט."],["3122","214","<b>כו'</b>: כ\"ה גם בסה\"מ תרכ\"ז כאן ע' רנה."],["3123","215","<b>כי אין מחסור ליריאיו</b>: המשך הכתוב יראו את ה' קדושיו — תהלים לד, י."],["3124","216","<b>במד\"ר ס\"פ ל\"ח סוף פ' נח</b>: ראה גם אוה\"ת ישעי' כרך ב' ע' תתיא. סה\"מ תרכ\"ז כאן ע' רנה ואילך. (לקמן בחלק ההנחות] הנחה ד\"ה שוש תשיש הא' והב' על יד הערות 89. 91 ואילך."],["3125","217","<b>כ\"מ</b>: שם: בכל מקום. באוה\"ת שם כבפנים."],["3126","218","<b>אין</b>: במדרש ובאוה\"ת שם: אין לה."],["3127","219","<b>ותהי שרי עקרה</b>: נח יא, ל [כ\"ה במהדורת אמשטרדם ת\"א. ובדפוסים הנפוצים: שרה. — באוה\"ת כבפנים]"],["3128","220","<b>והוה</b>: במדרש ובאוה\"ת שם: הוה."],["3129","221","<b>ולחנה אין . . ילדים</b>: שמו\"א א, ב."],["3131","223","<b>ציון דורש אין לה</b>: ירמי' ל, יז [ושם וכן במדרש ובאוה\"ת שם: ציון היא]."],["3130","222","<b>לה</b>: בבכתוב וכן במדרש ובאוה\"ת שם ליתא."],["3132","224","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה אגה\"ק סי\"ז קכו, רע\"א. מאמרי אדה\"א דברים ח\"ג ע' תשעט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670072\" data-slug=\"torat-chaim\" data-id=\"2300670072\">תו\"ח בראשית ז, ד</a> ובהערה 49. בא ח\"א קא, ג. וש\"נ. לעיל מאמר ד\"ה להבין וכו' בענין הציץ על יד הערה 169 ואילך."],["3133","225","<b>שאין הוא בחי' כתר</b>: ראה זהר שלח קנח, ב [וכן צ\"ל ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940042\" data-slug=\"or-hatorah-hb\" data-id=\"8159940042\">אוה\"ת</a> ישעי' שם]. מאמרי אדה\"א ויקרא ח\"ב ע' תנח. וש\"נ. הנחות תקע\"ז ע' ב. וש\"נ."],["3134","226","<b>וראית את אחורי</b>: תשא לג, כג. ראה גם לקמן מאמר ד\"ה וחג הקציר בכורי מעשיך על יד הערה טז. (ובחלק ההנחות שם על יד הערה 57]. מאמרי אדה\"ז הנחות הר\"פ ע' קנט. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061259\" data-slug=\"likkutei-sichot\" data-id=\"1300061259\">לקו\"ש שמות כרך ו ע' 249</a> ואילך."],["3135","227","<b>ואיהו תפיס בכולהו עלמין</b>: ראה זהר רע\"מ פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670220\" data-slug=\"torat-chaim\" data-id=\"2300670220\">תו\"ח נח סו, ג</a> הערה 30."]]],[2001910323,"דתפיס בי', ולכך נק' אין. והנה אין ואני הם אותיות שוים<sup data-n=\"3136\">228</sup>, והיינו כי אני הוא בחי' מל'<sup data-n=\"3137\">229</sup>, ושרש המל' שהוא בחי' יראה<sup data-n=\"3138\">230</sup> הוא בבחי' כתר<sup data-n=\"3139\">231</sup> לפי שיראה הוא בחי' ביטול היש, כי אהבה היא בבחי'<sup data-n=\"3140\">232</sup> יש, יש מי שאוהב<sup data-n=\"3141\">233</sup>, משא\"כ יראה היא בחי' ביטול מכל וכל, ולכך ע\"י הביטול מגיע בבחי' אין. וזהו משארז\"ל גדולים מעשה צדיקים<sup data-n=\"3142\">234</sup> ממעשה שמים וארץ, לפי שמעשה שמו\"א הם בחי' יש מאין, אבל מעשה צדיקים הוא בבחי' ביטול היש לאין כו', והיינו שע\"י הביטול מגיע בבחי' אין, ועי\"ז מתעורר גם מבחי' אין העצמי. וזהו מ\"ש הטעם כי אין מחסור ליריאיו, יראו את ה' קדושיו כי אין מחסור דהיינו שגם ע\"י בחי' יר\"ת (והיינו בחי' יר\"ע שביר\"ת כנ\"ל היינו בחי' יראו את הוי' שבבחי' יר\"ת) שהוא בחי' ביטול היש עי\"ז כי אין מחסור ליריאיו שעי\"ז נמשך מבחי' אין וזהו מחסור ליריאיו שהוא ממלא כל החסרונות<sup data-n=\"3143\">235</sup>, דהנה פעם כתי' בעירום ובחוסר כל<sup data-n=\"3144\">236</sup> והיינו לפי שנא' תחת אשר לא עבדת<sup data-n=\"3145\">237</sup> כו' בשמחה ובטוב לבב מרב כל, כל הוא בחי' דאחיד בשמיא ובארעא<sup data-n=\"3146\">238</sup> שע\"י בחי' כל נמשך משמיא בארעא, אך תחת אשר לא עבדת עי\"ז נעשה למטה חסר כל, אך בחי' האין מחסור ליריאיו שהוא",[["3136","228","<b>אין ואני הם אותיות שוים</b>: ראה פרדס שער אם הא\"ס הוא הכתר ש\"ג, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקמד־ מאמרי אדה\"א דברים ח\"א ע' רלד־ הנחות תקע\"ז ע' ב."],["3137","229","<b>אני הוא בחי' מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"א מערכת אני. פע\"ח בתחלתו. ע\"ח שער העקודים ש\"ו, פ\"ג. לעיל מאמר ד\"ה והי' אור הלבנה ובהערה 16."],["3138","230","<b>ושרש המל' . . יראה</b>: ראה ת\"ז בהקדמה ו, א. לעיל ריש פיסקא וזהו יראו."],["3139","231","<b>ושרש המל' . . בבחי' כתר</b>: לקו\"ת חוקת נח, א."],["3140","232","<b>אהבה היא בבחי' יש</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380685\" data-slug=\"likkutei-torah\" data-id=\"4001380685\">לקו\"ת מסעי צ, ב</a>."],["3141","233","<b>יש מי שאוהב</b>: מובא בכ\"מ בדא\"ח ומהם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370251\" data-slug=\"torah-or\" data-id=\"3901370251\">תו\"א וארא נו, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370302\" data-slug=\"torah-or\" data-id=\"3901370302\">יתרו סז, ג</a>. סה\"מ תרל\"ח ס\"ע קלה. וש\"נ."],["3142","234","<b>גדולים מעשה צדיקים</b>: ראה כתובות ה, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370295\" data-slug=\"torah-or\" data-id=\"3901370295\">תו\"א בשלח סו, סע\"ב</a> ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תתי. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670399\" data-slug=\"torat-chaim\" data-id=\"2300670399\">תו\"ח בראשית כה, ג</a> ובהערה 29. סה\"מ תרל\"ט ח\"ב ע' תפב. וש\"נ."],["3143","235","<b>אין מחסור . . ממלא כל החסרונות</b>: ראה גם ד\"ח שער התפלה נז, ד ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950446\" data-slug=\"or-hatorah-hb\" data-id=\"8315950446\">אוה\"ת בשלח ע' תמו</a> ואילך. ע' תסה. ישעי' שם. (יהל אור) תהלים ע' קכד. סה\"מ תרכ\"ז כאן ע' רנו. תרכ\"ט ע' סז. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה כי תבואו וכו' ושבתה הארץ על יד הערה 111. (לקמן בחלק ההנחות] הנחה ד\"ה שוש תשיש הא' והב' על יד הערות 95. 96."],["3144","236","<b>בעירום ובחוסר כל</b>: תבא כח, מח [ושם: ובעירום]."],["3145","237","<b>תחת אשר לא עבדת</b>: תבוא שם, מז. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>. מאמרי אדה\"א נ\"ך ע' כז ואילך ובהנסמן שם."],["3146","238","<b>דאחיד בשמיא ובארעא</b>: ראה זהר בראשית לא, א. ראה גם סה\"מ תרל\"ח ע' עט. וש\"נ. לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 164."]]],[2001910324,"ממלא את כל החסרונות לפי שהוא למעלה מבחי' חכ', כי בחכ' יש קצת דין<sup data-n=\"3147\">239</sup> ולזה נעשה למטה חסר כל, אבל כשנמשך מבחי' אין עי\"ז נשלם כל החסרונות לפי דלית שמאלא בהאי עתיקא<sup data-n=\"3148\">240</sup> ועי\"ז נשלם החסרון.\nז) <b>ובזה</b> יובן מ\"ש בקרי\"ס וייראו העם את הוי'<sup data-n=\"3149\">241</sup>, דהנה ארז\"ל ראתה שפחה על הים מה שלא ראה יחזקאל בן בוזי<sup data-n=\"3151\">243</sup> הכהן<sup data-n=\"3150\">242</sup>, ורש\"י ז\"ל בפי' החומש ע\"פ זה אלי<sup data-n=\"3152\">244</sup> פי' ראתה שפחה על הים מה שלא ראו נביאים, ובמד\"ר בשלח ס\"פ ך\"ג<sup data-n=\"3153\">245</sup> א\"ר ברכי' כמה גדולי' יורדי הים, משה רבן של כל הנביאים<sup data-n=\"3154\">246</sup> כמה נתחבט לפני המקום הראני נא את כבודך<sup data-n=\"3155\">247</sup> ולבסוף הראה לו בסימן והי' בעבור כבודי<sup data-n=\"3156\">248</sup>, ועולי הים כל אחד מראה באצבעו ואומר זה אלי, ולכאו' אינו מובן שהרי נבואה הוא בחי' גבוה מאד ואיך ראתה שפחה על הים כו'. אך הענין הוא דהנה ים ויבשה הוא בחי' עלמא דאתכסי' ועלמא דאתגלי'<sup data-n=\"3157\">249</sup>, וכמו שאנו רואים ההפרש שבין ים ליבשה, שהברואים שביבשה הם בבחי' נפרדים כו', משא\"כ הברואים שבים הם מובלעים בהים והים מכסה עליהם, וכמו ההפרש שבין מח' לדבור שהדבור הוא בחי' גילוי לזולתו ונעשה\n\n<i>נרשם בשולי היריעה ללא ציון מקומו בפנים:</i>\nלהעיר<sup data-n=\"8529\">יג</sup> מענין שהחכ' נק' יר\"ע<sup data-n=\"8530\">יד</sup> לפי שיראה לעלות אל הכתר<sup data-n=\"8531\">טו</sup>, לענין יראה ביטול מכל וכל כמשל מי שהוא בפחדי<sup data-n=\"8532\">טז</sup> יראה מתבטל ונאבד כל עצמותו.\nלהעיר ממ\"ש בא\"ב כמדומני סוף שער הציצית<sup data-n=\"8533\">יז</sup> שגם ביראת עונש יש יראת הרוממות שהרי העונש הוא לפי ערך הפגם בבחי' הרוממות כו', וא\"כ מובן איך ע\"י יר\"ת נמשך מבחי' אין למלאות המחסור כו'.",[["3147","239","<b>בחכ' יש קצת דין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370021\" data-slug=\"torah-or\" data-id=\"3901370021\">תו\"א בראשית ה, ד</a>. סה\"מ תר\"ם ח\"א ע' שז. וש\"נ. לקמן מאמר ד\"ה וחג הקציר בכורי מעשיך ובהערה 46."],["3148","240","<b>דלית שמאלא בהאי עתיקא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["3149","241","<b>וייראו העם את הוי'</b>: בשלח יד, לא."],["3151","243","<b>יחזקאל בן בוזי הכהן</b>: יחזקאל א, ג."],["3150","242","<b>ראתה שפחה . . בוזי הכהן</b>: מכילתא בשלח טו, ב [ושם: יחזקאל וכל שאר הנביאים]. ובילקוט שמעוני שם (רמז רמד): יחזקא' וישעי'. בבחיי שם: יחזקאל בן בוזי. בית אלקים להמבי\"ט שער היסודות פי\"ג. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830052\" data-slug=\"or-hatorah-hb\" data-id=\"8158830052\">אוה\"ת פ' ראה ע' תשלח</a>. סה\"מ תרכ\"ז כאן ע' רנו. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה קדש ישראל לה' ובהערה 10 בשם רש\"י.\nראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540775\" data-slug=\"torat-chaim\" data-id=\"2300540775\">תו\"ח בשלח ח\"א קצד, ב</a> ואילך. סה\"מ תרל\"א ח\"א ע' רסד ואילך."],["3152","244","<b>ורש\"י . . זה אלי</b>: בשלח טו, ב."],["3153","245","<b>ובמד\"ר בשלח ס\"פ ך\"ג</b>: בדילוגים וכו'. ראה גם אוה\"ת בשלח ע' תמב — נדפס גם בביאוה\"ז להצ\"צ כרך ב' ע' תשמז. סה\"מ תרל\"א ח\"א ע' רסז ואילך."],["3154","246","<b>משה רבן של כל הנביאים</b>: לשון שמו\"ר פכ\"א, ד. דב\"ר פ\"ב, א. רמב\"ם הל' יסודי התורה פ\"ז, ה\"ו."],["3155","247","<b>הראני נא את כבודך</b>: תשא לג, יח."],["3156","248","<b>והי' בעבור כבודי</b>: תשא שם, כב."],["3157","249","<b>ים ויבשה . . דאתכסי' . . דאתגלי'</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה ובהערה 104.\n\n<b>יג</b> ) <b>להעיר</b>: שני קטעים אלו הבאים לקמן נרשמו בגוכתי\"ק על העתקת המעתיק. אמנם כשהעתיק המעתיק עוה\"פ את המאמר עם התיקונים וכו' הנה משום מה לא נכללו בו שני הגהות אלו.\n\n<b>יד</b> ) <b>שהחכ' נק' יר\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370184\" data-slug=\"torah-or\" data-id=\"3901370184\">תו\"א מקץ מ, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370187\" data-slug=\"torah-or\" data-id=\"3901370187\">מא, ג</a>.\n\n<b>טו</b> ) <b>שהחכ' . . שיראה לעלות אל הכתר</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' שיח: בע\"ח. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830008\" data-slug=\"or-hatorah-hb\" data-id=\"8158830008\">אוה\"ת בשלח ע' תב</a>: צ\"ע בע\"ח שער מטי ולא מטי ושער הכללים כו'. ראה ע\"ח שער המלכים שי\"א, פ\"ה. זהר הרקיע פ' נשא קכב, ב. שער מאמרי רשב\"י שם.\n\n<b>טז</b> ) <b>בפחדי</b>: כ\"ה בגוכתי\"ק.\n\n<b>יז</b> ) <b>בא\"ב כמדומני . . הציצית</b>: פכ\"ג (צז, א). הובא גם בסה\"מ תרל\"ו ח\"ב ס\"ע עדר."]]],[2001910325,"נפרד כו', משא\"כ בחי' מח' היא מתאחדת ממש עם הנפש, וכמ\"כ יובן ההפרש שבין ים ליבשה שיבשה הוא בחי' עלמא דאתגלי' שהיא מבחי' אותיות הדבור, משא\"כ עלמין סתימין הוא מבחי' מח' כו', אך הנה בשעת קי\"ס הי' בחי' הפך ים ליבשה<sup data-n=\"3158\">250</sup> שמעלמא דאתכסי' נעשה בחי' עלמא דאתגליא, והיינו לפי שהי' הגילוי מלמעלה גם מבחי' עלמא דאתכסי' דהיינו מבחי' סדכ\"ס בחי' אין, וזהו בחי' אדון הנפלאות שלמעלה גם מבחי' עלמין סתימין, לזה נעשה מעלמא דאתכסי' בחי' עלמא דאתגלי', ומאחר שהי' הגילוי מלמעלה מסדר השתלשלות ע\"כ ראתה שפחה מה שלא ראה יחזקאל, וזה שנאמר בקי\"ס זה אלי, והיינו כי כל הנביאים נתנבאו בכה ומשה נתנבא בזה<sup data-n=\"3159\">251</sup>, אך בקי\"ס זכו הכל לבחי' זה שאמרו זה אלי שהוא למעלה משאר הנביאים.\n<b>וזהו</b> שנא' וירא ישראל את היד הגדולה, והיינו כי יש בנשמות ב' בחי' בחי' יעקב ובחי' ישראל<sup data-n=\"3160\">252</sup> וכמ\"ש כי חק לישראל הוא<sup data-n=\"3161\">253</sup> משפט לאלקי יעקב, שישראל<sup data-n=\"3162\">254</sup> הוא בחי' נשמות גבוהות כי שרית עם אלקים<sup data-n=\"3163\">255</sup> בחי' ישר אל שהוא בחי' תורה דהיינו נשמות שהם בעלי תורה, והנה בבחי' ישראל נא' וירא ישראל את היד הגדולה שהי' אצלם בבחי' ראי' והתגלות ממש בחי' יד הגדולה, וזהו ע\"י אשר עשה הוי' במצרים היינו שזכו לזה ע\"י מצרים שהוא בחי' מצרים וגבולים<sup data-n=\"3164\">256</sup>, ואשר עשה הוי' במצרים היינו שע\"י אתכפי' ואתהפכא את בחי' המצרים וגבולים עי\"ז זכו לבחי' וירא, כי כד אתכפי'<sup data-n=\"3165\">257</sup> כו' אסתלק יקרא דקוב\"ה בכולהו עלמין, ואח\"כ נא' וייראו העם את הוי' דהיינו הוא נשמות הנמוכות שנק' עם מל' עוממות<sup data-n=\"3166\">258</sup> שהוא בחי' אין מלך בלא עם<sup data-n=\"3167\">259</sup>, הנה העם הם נפרדים מהמלך שאינם מקבלים רק מבחי' מל' כמו שנעשה מקור לעולמות בי\"ע שהוא רק בחי' אותיות הדבור שנראים נפרדים כו' ואין בהם רק בחי' יראו מה' כל הארץ, אך בקי\"ס זכו לבחי' ויראו את הוי' שבחי' יראו את הוי' היינו שהיראה נמשך מבחי' האותיות כמו שהם כלולים עדיין במח' שהיא בחי' ים, והיינו לפי שהי' בחי' הפך ים ליבשה שים נעשה יבשה לכן הי' גם אצלם הגילוי מבחי' ים בחי' יראו את הוי' שזכו לבחי' יראה שנמשך מעלמא דאתכסי' שהוא בחי' ים כו'.",[["3158","250","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["3159","251","<b>כל הנביאים . . ומשה נתנבא בזה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540144\" data-slug=\"torat-chaim\" data-id=\"2300540144\">תו\"ח בשלח ח\"א קמד, ב</a> הערה 29. אוה\"ת מטות ע' א'תצד. וראה גם לעיל מאמר ד\"ה קדש ישראל לה' פ\"א."],["3160","252","<b>בנשמות . . יעקב . . ישראל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370167\" data-slug=\"torah-or\" data-id=\"3901370167\">תו\"א מקץ לו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370343\" data-slug=\"torah-or\" data-id=\"3901370343\">משפטים עז, ב</a>."],["3161","253","<b>כי חק לישראל הוא</b>: תהלים פא, ה."],["3162","254","<b>שישראל . . ישר אל</b>: ראה עבודת הקודש חלק התכלית פכ\"ז. פרדס שער עה\"כ שכ\"ג, פ\"י מערכת ישראל. כלי יקר וישלח לב, כט. סידור שחרית סה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540081\" data-slug=\"torat-chaim\" data-id=\"2300540081\">תו\"ח בשלח ח\"א רמו, ב</a>. וש\"נ."],["3163","255","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["3164","256","<b>מצרים . . מצרים וגבולים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370287\" data-slug=\"torah-or\" data-id=\"3901370287\">תו\"א בשלח סד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">סע\"ג. יתרו סז, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370318\" data-slug=\"torah-or\" data-id=\"3901370318\">עא, ג</a>."],["3165","257","<b>כד אתכפי'</b>: ראה זהר תרומה קכח, ב. יתרו סז, ב. מאמרי אדה\"א שמות ח\"א ע' ה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770331\" data-slug=\"or-hatorah-hb\" data-id=\"8316770331\">אוה\"ת שלח כרך ו ע' א'תשעב</a>. וש\"נ. שה\"ש כרך ב ע' תרצט."],["3166","258","<b>עם מל' עוממות</b>: ראה גם שער היחוד והאמונה פ\"ז. לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום הערה 19."],["3167","259","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. ראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."]]],[2001910326,"<b>ויאמינו</b> בה', היינו מה שהי' לבחי' הנשמות שנק' ישראל בבחי' ראי' כמ\"ש וירא ישראל את היד הגדולה, זה לא הי' אצלם רק בבחי' אמונה אבל לא בבחי' ראי' ממש* כמו לנשמות שנק' ישראל כו'.\n<b>ומעתה</b> י\"ל<sup data-n=\"3168\">260</sup> המד\"ר שא' וירא ישראל את היד הגדולה לפי שאמר פרעה מי ה' לכך לקה ביד הגדולה חמשים מכות כנגד מי, שהרי היד הגדולה היא בחי' חסד ואיך מבחי' החסד יומשך בחי' דין וגבורה, וכן צ\"ל מ\"ש ימינך ה' נאדרי בכח ימינך ה' תרעץ אויב<sup data-n=\"3169\">261</sup>, איך מבחי' ימין נמשך שיהי' תרעץ אויב. אך הענין הוא דהנה ההפרש שבין ימין לשמאל, היינו שעיקר הכח הוא בימין ולכן הפעולה שנעשית בימין היא נעשית בטוב, משא\"כ בשמאל אף שנעשית הפעולה מ\"מ אינה טובה כ\"כ כמו בימין, וזהו שפי' רש\"י לחד פירושא על מארז\"ל שבת דס\"ג ע\"א<sup data-n=\"3170\">262</sup> למיימינים בה<sup data-n=\"3171\">263</sup> סמא דחיי למשמאילים בה כו', שמיימינים היינו כשלומדים את התורה בעיון ופלפול אז נק' מיימינים היינו שאז היא כמו המלאכה שנעשה בימין שהפעולה היא נעשית כתיקונה, למשמאילים בה היינו כשלומד את התורה שלא בעיון אז נק' בחי' משמאילים, שזהו כמו שנעשה הפעולה בשמאל שאין הפעולה טובה כו'.\n<b>ועפ\"ז</b> יובן<sup data-n=\"3172\">264</sup> מ\"ש (בישעי' ג') נצב לריב ה'<sup data-n=\"3173\">265</sup> וכתי' (יואל ד') כי אשב שם לשפוט<sup data-n=\"3174\">266</sup> כמו שתירץ במד\"ר וישלח פ' פ\"ב<sup data-n=\"3175\">267</sup> ע\"ש, והיינו שזהו ההפרש\n\n*)צ\"ל<sup data-n=\"8534\">יח</sup> הלא ראתה שפחה, שהשפחה היא מן הפחותי' כמ\"ש עד בכור השפחה<sup data-n=\"8535\">יט</sup>, וא\"כ איך שייך שהנשמות שהיו למטה מבחי' ישראל האמינו ולא ראו, וצ\"ל דבחי' את הוי' שגם העם השיגו זה שהיא בחי' פנימיות המל' כלת משה<sup data-n=\"8536\">כ</sup> זהו למעלה מבחי' השגת הנביאים שנתנבאו בכה כדמותנו<sup data-n=\"8537\">כא</sup>, ואפשר שבחי' פנימי' המל' מאחר שזהו המל' כמו שהיא באצי' נק' זה, מ\"מ בחי' ראי' שראו נשמות הנק' ישראל שזהו מבחי' יד הגדולה (בחי' בינה) זה הי' אצל העם בבחי' אמונה לבד.",[["3168","260","<b>ומעתה י\"ל</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950458\" data-slug=\"or-hatorah-hb\" data-id=\"8315950458\">אוה\"ת בשלח ע' תנח</a> ואילך. ע' תע ואילך."],["3169","261","<b>ימינך ה' . . תרעץ אויב</b>: בשלח טו, ו. ראה גם אוה\"ת שם ע' תקמא ואילך. ע' תקמד ואילך."],["3170","262","<b>שפי' רש\"י . . דס\"ג ע\"א</b>: ראה שם ד\"ה למיימינין וד\"ה למשמאילין."],["3171","263","<b>על מארז\"ל . . למיימינים בה</b>: ראה שבת שם פח, ב."],["3172","264","<b>ועפ\"ז יובן</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010199\" data-slug=\"or-hatorah-hb\" data-id=\"8159010199\">אוה\"ת חנוכה כרך ז תתתנו סע\"ב</a> ואילך. ספר החקירה להצ\"צ ע' קלז (אוה\"ת בראשית כרך ב תנו, ב)."],["3173","265","<b>(בישעי' ג') נצב לריב ה'</b>: פסוק יג."],["3174","266","<b>(יואל ד') כי אשב שם לשפוט</b>: פסוק יב [ושם: כי שם אשב — וכ\"ה בס' החקירה שם. באוה\"ת חנוכה שם. בשלח שבהערה 260 תיבת שם ליתא. בסה\"מ תרכ\"ז כאן ע' רנח כבפנים]."],["3175","267","<b>במד\"ר וישלח פ' פ\"ב</b>: סימן ח. הובא גם בכ\"מ ומהם בהמצויין בהערה שלפנ\"ז. אוה\"ת נצבים ע' א'קצט. האזינו ע' א'תרנו.\n\n<b>יח</b> ) <b>צ\"ל</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים.\n\n<b>יט</b> ) <b>עד בכור השפחה</b>: בא יא, ה.\n\n<b>כ</b> ) <b>פנימיות המל' כלת משה</b>: ראה זהר הרקיע ר\"פ בראשית. שער מאמרי רשב\"י ר\"פ בראשית. ס' הדרת מלך סקנ\"ו (פו, ה). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381286\" data-slug=\"likkutei-torah\" data-id=\"4001381286\">לקו\"ת שה\"ש לט, סע\"ג</a> ואילך.\n\n<b>כא</b> ) <b>כדמותנו</b>: בראשית א, כו."]]],[2001910327,"ע\"ד שבין ימין לשמאל שכשדן את ישראל הוא דן אותם בשמאל מקצר כו' שהוא דרך עראי שאין הדין חזק כ\"כ כמו הדין שנמשך בימין, וזהו מקצר בדין ומוותר בדין לפי שנמשך הדין רק משמאל בחי' שמאל דוחה לבד והיינו לפי ששרש נש\"י הוא מבחי' ימין לכך א\"א להיות הדין נמשך מבחי' ימין כיון ששרשן נמשך מבחי' ימין והדין שנמשך להם הוא רק מבחי' שמאל דוחה, והנה כיון שהדין נמשך מבחי' שמאל דוחה נעשה אח\"כ תומ\"י בחי' ימין מקרבת, וזהו שבכ\"מ שנאמר פורעניות של ישראל נאמר תיכף אח\"כ בחי' ישועה ונחמה כמו בהושע שנאמר בו אתם לא עמי<sup data-n=\"3176\">268</sup> כו' נאמר תיכף והי' מספר בנ\"י כחול הים אשר לא יספר<sup data-n=\"3177\">269</sup> כו' ובמקום אשר יאמר להם לא עמי אתם יאמר להם בני אל חי<sup data-n=\"3178\">270</sup>, והיינו לפי שהדין שלהם נמשך רק מבחי' שמאל דוחה ואח\"כ נעשה בחי' ימין מקרבת, וזהו כשהוא דן את ישראל בעמידה כמו עד\"מ בחי' שמאל, אך כשהוא דן את העובדים לכוכבי' ומזלות הוא דן אותם בישיבה דהיינו בבחי' ימין לפי שהם מנגדים לבחי' ימין.\n<b>דהנה</b> פרעה אמר מי הוי' אשר אשמע בקולו שלא ידע מש' הוי' אבל משם אלקי' ידע<sup data-n=\"3179\">271</sup> כי יוסף הודיע לו אלקי' יענה את שלום פרעה<sup data-n=\"3180\">272</sup> אך משם הוי' לא רצה לידע<sup data-n=\"3181\">273</sup> והיינו לפי שמשם אינו יכול לקבל שום יניקה, אבל מש' אלקים יכלו גם הם לקבל דהיינו ממ\"ח צירופים אחרונים<sup data-n=\"3182\">274</sup> דש' אלקים כו', אבל מש' הוי' אינו יכול לקבל. וזהו שאמר פרעה אם בן הוא<sup data-n=\"3183\">275</sup> והמתן אותו ואם בת היא וחיה, והיינו כי בן הוא בחי' חסד זכר חסדו<sup data-n=\"3184\">276</sup>, וכל בניך למודי הוי'<sup data-n=\"3185\">277</sup> שבן הוא מקבל מש' הוי' כו', והנה מש' הוי' אינו יכול לקבל וכמ\"ש אם תגביהי כנשר<sup data-n=\"3186\">278</sup> משם אורידך נאום הוי'<sup data-n=\"3187\">279</sup>, לזה אמר אם בן הוא והמתן אותו וכן כל הבן הילוד היאורה תשליכוהו וכל הבת תחיון<sup data-n=\"3188\">280</sup> לפי שבת הוא בחי' גבורות<sup data-n=\"3189\">281</sup> גם הם יוכלו לקבל, אך באמת טעה בזה לפי שעיקר הגבורות הוא כדי לאכללא שמאלא בימינא וכיון שנכלל שמאל בימין",[["3176","268","<b>בהושע . . אתם לא עמי</b>: א, ט."],["3177","269","<b>בהושע . . והי' מספר . . לא יספר</b>: ב, א [בדילוג]."],["3178","270","<b>ובמקום אשר . . בני אל חי</b>: המשך הכתוב והי' מספר [ושם: והי' במקום]."],["3179","271","<b>פרעה . . משם אלקי' ידע</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">תו\"א מקץ מג, רע\"א</a>. סידור שער החנוכה ערא, סע\"ב."],["3180","272","<b>אלקי' . . שלום פרעה</b>: מקץ מא, טז."],["3181","273","<b>משם הוי' לא רצה לידע</b>: ראה גם לעיל מאמר ד\"ה זכור את יום השבת פ\"ה. ד\"ה ראה קראתי בשם פ\"ג."],["3182","274","<b>ממ\"ח צירופים אחרונים</b>: ראה פע\"ח שחה\"מ שכ\"א, פ\"ה. שער הכוונות ענין הפסח דרוש א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370486\" data-slug=\"torah-or\" data-id=\"3901370486\">תו\"א יתרו קט, ד</a>. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'סא. סה\"מ תר\"ם ח\"א ע' שנה. וש\"נ."],["3183","275","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540367\" data-slug=\"torat-chaim\" data-id=\"2300540367\">אם בן הוא</b>: שמות א</a>, טז. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540671\" data-slug=\"torat-chaim\" data-id=\"2300540671\">תו\"ח שמות ח\"א כו, א</a> ואילך. לד, סע\"ב ואילך. אוה\"ת שמות כרך ז ע' ב'תקט ואילך. כרך ח ע' ב'תתמו."],["3184","276","<b>זכר חסדו</b>: תהלים צח, ג. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310048\" data-slug=\"tanya\" data-id=\"3401310048\">תניא פמ\"ג (סב, א</a>). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540367\" data-slug=\"torat-chaim\" data-id=\"2300540367\">תו\"ח שמות ח\"א כו, א</a> ובהערה 93."],["3185","277","<b>וכל בניך למודי הוי'</b>: ישעי' נד, יג. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת פ' ראה כט, א</a>."],["3186","278","<b>אם תגביהי כנשר</b>: עובדי' א, ד [ושם: תגביה — ראה בהערה הבאה]."],["3187","279","<b>אם תגביהי . . נאום הוי'</b>: ראה גם לעיל מאמר ד\"ה להבין וכו' בענין הציץ על יד הערה 130 ואילך ובהנסמן שם."],["3188","280","<b>כל הבן . . הבת תחיון</b>: שמות א, כב."],["3189","281","<b>שבת . . גבורות</b>: ראה זהר בראשית מח, ב. אחרי סה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540695\" data-slug=\"torat-chaim\" data-id=\"2300540695\">תו\"ח שמות ח\"א לד, ד</a>. וש\"נ."]]],[2001910328,"אינו יכול לקבל עוד יניקה אפי' מבחי' גבורות כיון שנכלל שמאל בימין כו'. והנה לפי שפרעה הי' מנגד לבחי' הוי' ואמר מי הוי' שהוא בחי' ימין לזה נמשך הדין שלו דוקא מבחי' ימין ולכך הדין הוא קשה יותר מבחי' ימין, וגם אם הי' הדין נמשך מבחי' שמאל אז נעשה ימין מקרבת, אבל אם הדין נמשך מימין אז אין לו מי שיקרב. וזהו כשהוא דן העובדים לכוכבים ומזלות דן אותם בישיבה מאריך בדין ומפשפש בדין שהדין הוא חזק וקשה מאד, וזהו ימינך ה' תרעץ אויב.\n<b>וזהו</b> וירא ישראל את היד הגדולה אשר עשה ה' במצרים שע\"י שאמר מי הוי' לקה ביד הגדולה חמשים מכות לפי שיד הגדולה הוא בבחי' בינה<sup data-n=\"3190\">282</sup> ופרעה חטא במי דהיינו בבינה<sup data-n=\"3191\">283</sup> לכך לקה ביד הגדולה שהוא בחי' בינה, משא\"כ בישראל הוא להיפך שכל הישועות ונחמות<sup data-n=\"3192\">284</sup> נמשך מבחי' מי וכמ\"ש מי יתן מציון ישועת ישראל<sup data-n=\"3193\">285</sup> כנ\"ל.",[["3190","282","<b>שיד הגדולה . . בינה</b>: ראה זהר רע\"מ תצא רעז, א. ת\"ז תנ\"ה פט, רע\"א."],["3191","283","<b>במי דהיינו בבינה</b>: זהר משפטים קיז, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550228\" data-slug=\"torat-chaim\" data-id=\"2300550228\">תו\"ח פקודי ח\"ב תמג, ד</a> ובהערה 78."],["3192","284","<b>שכל הישועות ונחמות</b>: ראה ויק\"ר פכ\"ד, ד. לעיל מאמר ד\"ה ומעתה צ\"ל למה הוקבעו המועדים על זמן התבואה על יד הערה 66 ואילך."],["3193","285","<b>מי יתן מציון ישועת ישראל</b>: תהלים יד, ז."]]],[2001910329,"<h3>הים ראה וינוס</h3>\n<b></b><b>בס\"ד ל\"נ ונכתב לא על הסדר</b>\n<b>הים</b> ראה וינוס<sup data-n=\"3194\">1</sup>, ואיתא ברבות פ' בשלח פך\"א דקל\"ט א'<sup data-n=\"3196\">3</sup>, כשהלך משה לקרוע<sup data-n=\"3197\">4</sup> את הים לא קיבל עליו להקרע, א\"ל מפניך איני נקרע כו' שנבראתי<sup data-n=\"3198\">5</sup> בג' כו' הלך וא\"ל<sup data-n=\"3199\">6</sup> להקב\"ה אין הים כו' מה עשה הקב\"ה נתן ימינו על ימינו של משה שנא'",[["3194","1","<b>הים ראה וינוס</b>: מאמר זה מיוסד על <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950467\" data-slug=\"or-hatorah-hb\" data-id=\"8315950467\">אוה\"ת בשלח ע' תסז</a>-תסח ס\"ו — ראה גם לקמן בהערות.\nלפיסקא והענין השווה אוה\"ת שם ע' תמא.\nבהכותרת כאן נרשם: ל\"נ לא נאמר. לקמן על יד הערה 24 כותב: ”כמ\"ש בד\"ה וירא ישראל דתקס\"ב תקס\"ד\" ראה לעיל מאמר ד\"ה וירא ישראל את היד הגדולה הערה 1.\nהמאמר נרשם בגוכתי\"ק."],["3196","3","<b>ברבות . . פך\"א דקל\"ט א'</b>: במהדורת אמשטרדם ת\"א — ולפנינו סימן ו'.\nולכאורה צ\"ל: קלח, סע\"ד ואילך. באוה\"ת כאן מציין א) : ”פכ\"ה\". וצ\"ל כבפנים. ב) ”קלט\"א\" — אלא שבאוה\"ת העתיק מהמדרש מתחיל מהתיבות דלקמן ”מה עשה הקב\"ה\" — ועד\"ז באוה\"ת תצוה ס\"ע א'תקפ."],["3197","4","<b>כשהלך משה לקרוע</b>: שם: וכיון שהלך לקרוע."],["3198","5","<b>א\"ל מפניך איני . . שנבראתי</b>: שם: א\"ל הים מפניך אני [ראה גם לקמן ובהערה 77] . . שאני נבראתי."],["3199","6","<b>וא\"ל</b>: שם: ואמר."]]],[2001910330,"מוליך לימין משה וגו' (ישעי' ס\"ג)<sup data-n=\"3200\">7</sup> מיד ראה הקב\"ה<sup data-n=\"3201\">8</sup> וברח שנא' (תילי' קי\"ד) הים ראה<sup data-n=\"3202\">9</sup> וינוס<sup data-n=\"3195\">2</sup> מה ראה אלא שראה הקב\"ה<sup data-n=\"3203\">10</sup> שנתן יד ימינו, וצ\"ל שזהו יד הגדולה דא\"א ודעת\"י, והיינו ע\"י לך הגדולה<sup data-n=\"3204\">11</sup> דז\"א שבטל לבחי' כי לא אדם<sup data-n=\"3205\">12</sup> לאו מכל אילון מדות<sup data-n=\"3206\">13</sup> נתגלה יד הגדולה דא\"א גם למטה עד שגם הים שלמטה ראה ולא יכול לעכב אלא ברח מיד, א\"ל משה כו' מפני יראתו כו'<sup data-n=\"3207\">14</sup>.\n<b>והענין</b><sup data-n=\"3208\">15</sup> הוא דהנה בסדרי השתלשלות ים ויבשה הוא בחי' עלמא דאתכסיא ועלמא<sup data-n=\"3210\">17</sup> דאתגלי'<sup data-n=\"3209\">16</sup>, ים הוא בחי' עלמא דאתכסיא ויבשה הוא בחי' עלמא דאתגלי' שכל מה שיש ביבשה<sup data-n=\"3211\">18</sup> יש בים, רק שביבשה הן בבחי' גילוי, ובים הם בבחי' העלם, וכמ\"כ כל סדרי השתלשלות העולמות הן בבחי' העלם וגילוי ים ויבשה,\n\nלך<sup data-n=\"8538\">א</sup> ה' הגדולה תלוי ראש<sup data-n=\"8539\">ב</sup>, לך הגדולה זה קרי\"ס<sup data-n=\"8540\">ג</sup>, ב\"פ בגדולה ברה\"ע<sup data-n=\"8541\">ד</sup>, והב' איך שהגדולה אינו תופס מקום ומקום גדולתו<sup data-n=\"8542\">ה</sup> כו', וזה נתגלה ע\"י קי\"ס היפך הטבע, וע' ב' פירושים בד\"ה ושננתם הגדול<sup data-n=\"8543\">ו</sup>.\nומ\"ש<sup data-n=\"8544\">ז</sup> במ\"א בענין בריאה יש מאין, שאינו שייך שגשם העולם הי' תחילה<sup data-n=\"8545\">ח</sup> ע\"ד עו\"ע<sup data-n=\"8546\">ט</sup>, לית פירכא שזהו שגשם העולם כמו שהוא לא הי' אבל ברוחניות כו' ארץ כו' משלג<sup data-n=\"8547\">י</sup> כו' שהכוונה יחידות עשירות מאות<sup data-n=\"8548\">יא</sup> כמ\"ש במ\"א זה הי' קודם ג\"כ.\nלעיין<sup data-n=\"8549\">יב</sup> בלק\"ת מענין לידה<sup data-n=\"8550\">יג</sup> שהוא לא ע\"י נה\"י.",[["3200","7","<b>מוליך לימין משה וגו' (ישעי' ס\"ג)</b>: פסוק יב — וכן צ\"ל באוה\"ת תצוה דלהלן הערה 72."],["3201","8","<b>הקב\"ה</b>: וכ\"ה בשמו\"ר מהדורא הנ\"ל ובאוה\"ת כאן. בדפוסים הנפוצים: להקב\"ה."],["3202","9","<b>(תילי' קי\"ד) הים ראה וינוס</b>: פסוק ג."],["3195","2","<b>הים ראה וינוס</b>: נסמן לקמן הערה 9."],["3203","10","<b>הקב\"ה</b>: כ\"ה בשמו\"ר מהדורא הנ\"ל. בדפוסים הנפוצים: להקב\"ה."],["3204","11","<b>לך הגדולה</b>: דברי הימים-א כט, יא [בדילוג השם]."],["3205","12","<b>כי לא אדם</b>: שמו\"א טו, כט."],["3206","13","<b>לאו מכל אילון </b> [בבוך תרמ\"א 2086 — כת\"י מעתיק: אלין]<b> מדות</b>: ראה ת\"ז בהקדמה יז, ב."],["3207","14","<b>א\"ל משה . . כו'</b>: שמו\"ר שם."],["3208","15","<b>והענין</b>: בצד הימיני של הגליון בהפסק קו קצר מלמעלמ\"ט נרשם אצל פיסקא זו: ”ס\"ה\". כנראה הכוונה שלפיסקא זו השווה (לשון) <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950441\" data-slug=\"or-hatorah-hb\" data-id=\"8315950441\">אוה\"ת בשלח ע' תמא</a> סעיף ה'. וראה גם לקמן הערה 26."],["3210","17","<b>עלמא דאתכסיא ועלמא דאתגלי'</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, רע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."],["3209","16","<b>ים ויבשה . . דאתכסיא . . דאתגלי'</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה ובהערה 104."],["3211","18","<b>שכל מה שיש ביבשה</b>: נסמן לקמן הערה 66.\n\n<b>א</b> ) <b>לך</b>: נרשם בראשיתו של העמוד בצד הימני ללא ציון מקומו בפנים.\n\n<b>ב</b> ) <b>לך ה' הגדולה תלוי ראש</b>: ראה במד\"ר פ\"א, ט שאו את ראש . . נתתי לכם תלוי ראש . . שכשם שיש לי תלוי ראש . . לך ה' הגדולה [וגו' לכל לראש — תנחומא במדבר ס\"ח] כך לכם עשיתי . . תלוי ראש לכך נאמר שאו את ראש.\nהובא גם בכ\"מ ומהם: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי ע' א'שסו</a>. ואתחנן ע' רנה [ושם נדפס: פי\"א. וצ\"ל: פ\"א]. דבהי\"א כרך א ע' תשטז. (יהל אור) תהלים ע' תרנח. סה\"מ תרכ\"ז ע' רא וע' שעב.\n\n<b>ג</b> ) <b>הגדולה זה קרי\"ס</b>: ראה ברכות נח, סע\"א. לקמן בסיום המאמר בשולי היריעה.\n\n<b>ד</b> ) <b>בגדולה ברה\"ע</b>: ראה אוה\"ת ואתחנן שם: דנ\"ה. וצ\"ל: נח, א. הערה שלפנ\"ז. לעיל מאמר ד\"ה וירא ישראל את היד הגדולה על יד הערה 33 ואילך.\n\n<b>ה</b> ) <b>ומקום גדולתו</b>: ראה לעיל מאמר ד\"ה זכור את יום השבת הערה 130.\n\n<b>ו</b> ) <b>ב' פירושים בד\"ה ושננתם הגדול</b>: אוה\"ת ואתחנן שם ע' רנד ואילך.\n\n<b>ז</b> ) <b>ומ\"ש</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים.\n\n<b>ח</b> ) <b>שגשם העולם הי' תחילה</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א (נוסח א') ע' רצב ואילך [אוה\"ת ואתחנן ע' רכח]. שם (נו\"ש) ע' רצד ואילך [אוה\"ת ואתחנן ע' קפז. ס' החקירה להצ\"צ ע' 112]. שער האמונה נ, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540582\" data-slug=\"torat-chaim\" data-id=\"2300540582\">תו\"ח בשלח ח\"א קלח, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540357\" data-slug=\"torat-chaim\" data-id=\"2300540357\">קמו, א</a>.\n\n<b>ט</b> ) <b>עו\"ע</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>: הנזכר בספרים. שה\"ש א, ב: כמ\"ש בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו.\n\n<b>י</b> ) <b>ארץ . . משלג</b>: ראה פרקי דר\"א פ\"ג. המשך מים רבים תרל\"ו פקנ\"ה (וש\"נ בפנים).\n\n<b>יא</b> ) <b>משלג . . יחידות עשירות מאות</b>: ראה גם סה\"מ תרכ\"ח ע' ב. תרכ\"ט ע' קס. המשך מים רבים שם פקנ\"ז. סה\"מ תר\"ם ח\"א ע' תכא. וש\"נ.\n\n<b>יב</b> ) <b>לעיין</b>: נרשם מלמעלמ\"ט בצד השמאלי של העמוד ללא ציון מקומו בפנים.\n\n<b>יג</b> ) <b>בלק\"ת מענין לידה</b>: בשלח ב, ד."]]],[2001910331,"שקודם שנתגלו כל העולמות מאין ליש היו כלולי' תחלה בהעלם בבחי' כשעלה ברצונו הפשוט<sup data-n=\"3212\">19</sup> שע\"י מחשבה זו נתהוו<sup data-n=\"3213\">20</sup> כו', והנה ג\"ע העליון והתחתון נק' עלמין דאתגליין וכן מלאכים ונשמות, בקול דברי אלקים חיים<sup data-n=\"3214\">21</sup> כו' נודע בשערים בעלה<sup data-n=\"3215\">22</sup> כו' בחי' דבור נק' זה השער לה'<sup data-n=\"3216\">23</sup> כמ\"ש בד\"ה וירא ישראל דתקס\"ב תקס\"ד<sup data-n=\"3217\">24</sup>, והוא בחי' ממכ\"ע, אבל בחי' ים הוא ההעלם כו' רק שהוא ההעלם השייך להגילוי, ועד\"ז נא' והים עליהם מלמעלה<sup data-n=\"3218\">25</sup>.\n<b>והנה</b><sup data-n=\"3219\">26</sup> ענין קרי\"ס הפך ים ליבשה<sup data-n=\"3220\">27</sup> היינו שלא כסדר ההשתלשלות, שע\"פ סדר ההשתלשלות אין ההעלם נעשה גילוי ממש רק אפס קצהו נמשך מהעלם אל הגילוי, אבל כשהפך ים ליבשה נעשה ההעלם עצמו בחי' גילוי והיינו ע\"י ההמשכה מלמעלה מבחי' ההעלם מבחי' עצמיות<sup data-n=\"3221\">28</sup> אוא\"ס שלמעלה מסובב וממלא, דקמי' ההעלם והגילוי שוין כחשוכה כאורה<sup data-n=\"3222\">29</sup>, וזהו הים ראה וינוס, מה עשה הקב\"ה",[["3212","19","<b>כשעלה ברצונו הפשוט</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["3213","20","<b>שע\"י מחשבה זו נתהוו</b>: ראה גם לעיל מאמר ד\"ה והי' אור הלבנה ובהערה 85."],["3214","21","<b>בקול דברי אלקים חיים</b>: ברכת יוצר."],["3215","22","<b>נודע בשערים בעלה</b>: משלי לא, כג."],["3216","23","<b>זה השער לה'</b>: תהלים קיח, כ."],["3217","24","<b>כמ\"ש בד\"ה וירא ישראל דתקס\"ב תקס\"ד</b>: אוה\"ת שלח כאן ע' תמא.\nבנידן התאריך”דתקס\"ב תקס\"ד\" — ראה לעיל מאמר ד\"ה וירא ישראל את היד הגדולה הערה 1."],["3218","25","<b>והים עליהם מלמעלה</b>: מלכים-א ז, כה."],["3219","26","<b>והנה</b>: בצד הימיני של הגליון נרשם אצל פיסקא זו: ”ס\"ו\". כנראה הכוונה שלפיסקא זו השווה (לשון) <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950467\" data-slug=\"or-hatorah-hb\" data-id=\"8315950467\">אוה\"ת בשלח ע' תסז</a> סעיף ו'. ראה גם לעיל הערה 15."],["3220","27","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["3221","28","<b>עצמיות</b>: באוה\"ת כאן: עצמות."],["3222","29","<b>כחשוכה כאורה</b>: תהלים קלט, יב [ושם: כחשיכה — וכ\"ה באוה\"ת כאן]. ראה לעיל מאמר ד\"ה להבין וכו' בענין הציץ הערה 129."]]],[2001910332,"נתן ימינו על ימינו של משה שנא' מוליך לימין משה, מיד ראה הקב\"ה וברח שנא' הים ראה וינוס כו', והענין י\"ל ע\"פ מ\"ש אף ידי יסדה ארץ וימינו<sup data-n=\"3223\">30</sup> טפחה שמים, וארז\"ל נטה ימינו וברא שמים<sup data-n=\"3224\">31</sup>, נטה שמאלו וברא ארץ, כי ארץ ושמים הם ממכ\"ע<sup data-n=\"3226\">33</sup> וסוכ\"ע<sup data-n=\"3225\">32</sup> משא\"כ בחי' ים הוא רק הארה מבחי' סוכ\"ע כו' דהיינו ההעלם של הגילוי כנ\"ל, וזהו הנה טפחות נתת ימי וחלדי כאין נגדך (תילי' ל\"ט וא\"ו), (ופי' רש\"י מדודים הם ימי האדם כדבר הנמדד בטפחיים כן ימי האדם קצובים), כי ב' ידות ימין ושמאל הם ב' טפחות<sup data-n=\"3227\">34</sup>, שבכל יד ה' אצבעות חמש כנגד חמש<sup data-n=\"3228\">35</sup>, והם ימי של בחי' מל' ובאמת גם סוכ\"ע אין ערוך לעצמותו ית', (והיינו שדוד אמר זה כנגד מדתו שי\"ל שבנין המל'<sup data-n=\"3229\">36</sup> הוא מבחי' המל' של כל הע\"ס<sup data-n=\"3230\">37</sup>, ואמר זה בשביל כלליות נש\"י בחי' כנס\"י שמדודים הם בטפחיים כמו שפי' רש\"י שגם בחי' סוכ\"ע מדוד הוא\n\nוחלדי<sup data-n=\"8551\">יד</sup> וזקנתינו כאין נגדך חלד ל' חלודה רש\"י<sup data-n=\"8552\">טו</sup> ות\"י<sup data-n=\"8553\">טז</sup> קלילין סדרתא יומי וגושמא<sup data-n=\"8554\">יז</sup> כלמא לקבלך, ברם כולהון צדיקיא קימין לחיי עלמא.\nנרשם בשולי היריעה:\nוכשנבנה בחי' המל' בע\"ס הם ימי וחלדי ים ויבשה, פנימיות המל' וחיצוניות המל'<sup data-n=\"8555\">יח</sup> כמ\"ש כל הנחלים הולכים אל הים<sup data-n=\"8556\">יט</sup>, ים מקבל מבחי' ימי היינו מבחי' יומין דז\"א ומעלים ומגלה הארה בבחי' ארץ שזהו בחי' חלדי כמ\"ש הת\"יטז על וחלדי וגושמי היינו בחי' יבשה שזהו המקור להוות היש דבי\"ע.",[["3223","30","<b>אף ידי . . וימינו</b>: ישעי' מח, יג [ושם ובאוה\"ת כאן: וימיני]."],["3224","31","<b>נטה ימינו וברא שמים</b>: ראה פדר\"א פי\"ח. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a> בפנים. לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 81."],["3226","33","<b>ממכ\"ע וסוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["3225","32","<b>ארץ ושמים הם ממכ\"ע וסוכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380394\" data-slug=\"likkutei-torah\" data-id=\"4001380394\">לקו\"ת נשא כא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380957\" data-slug=\"likkutei-torah\" data-id=\"4001380957\">שם ר\"ה נט, ג</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' קפו."],["3227","34","<b>ב' ידות . . ב' טפחות</b>: לקו\"ת להאריז\"ל לתהלים שם — הובא ב (יהל אור) אוה\"ת תהלים ע' קמז."],["3228","35","<b>חמש כננגד חמש</b>: ס\"י פ\"א, מ\"ג."],["3229","36","<b>שדוד . . המל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["3230","37","<b>שבנין המל' . . כל הע\"ס</b>: ראה ע\"ח שער מיעוט הירח של\"ו, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תשצה. שעה\"י קמא, ב ובהערה 41. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550485\" data-slug=\"torat-chaim\" data-id=\"2300550485\">תו\"ח יתרו ח\"ב רסח, ג</a>. סה\"מ תרל\"ח ע' ח ובהערה 71.\n\n<b>יד</b> ) <b>וחלדי</b>: נרשם בריש העמוד בהיפך הדף ללא ציון מקומו בפנים.\n\n<b>טו</b> ) <b>חלד ל' חלודה רש\"י</b>: לתהלים כאן. ראה גם רש\"י שם יז, יד. מט, ב.\n\n<b>טז</b> ) <b>ות\"י</b>: לתהלים כאן. וכ\"ה (ת\"י על תהלים) גם באוה\"ת תולדות ע' 300. (יהל אור) תהלים ע' רלו. ועוד. סה\"מ תרל\"ח ע' רטו. ראה מגילה ג, א. שו\"ת זכר יהוסף — לר' יוסף זכרי' שאוועל — סקכ\"א.\n\n<b>יז</b> ) <b>וגושמא</b>: בשולי היריעה שלאח\"ז: וגושמי — וכ\"ה בת\"י.\n\n<b>יח</b> ) <b>ים ויבשה . . וחיצוניות המל'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380133\" data-slug=\"likkutei-torah\" data-id=\"4001380133\">לקו\"ת צו יד, ב</a>. סה\"מ ליקוט ח\"א ע' ק.\n\n<b>יט</b> ) <b>כל הנחלים הולכים אל הים</b>: קהלת א, ז. ראה זהר בהעלותך קנ, ב."]]],[2001910333,"וכמ\"ש בד\"ה קמפלגי כו' אם בהרת קדמה, שלא נדפס<sup data-n=\"3231\">38</sup>, שגם בחי' החיות דבחי' סוכ\"ע שקדוש ומובדל ואינו כמו הנשמה שמחי' את הגוף שמתלבש בגוף להחיותו לכן מתפעלת ממקרי הגוף<sup data-n=\"3232\">39</sup> אבל בחי' סוכ\"ע הוא קדוש ומובדל, ועכ\"ז הנה בחי' סוכ\"ע זו שייך לעולם רק שהתהוות העולם אינו פועל בו שום שינוי ח\"ו ולכן אני ה' לא שניתי<sup data-n=\"3233\">40</sup> ואתה הוא קודם שנברה\"ע<sup data-n=\"3234\">41</sup>, ואתה הוא לאחר שנברה\"ע בלי שום שינוי כלל, והמשל בזה הוא כמו השמים שמקיפים את הארץ שהם כמו בחי' סוכ\"ע ולכן השמים הם גבוהים במדריגה לגבי בחי' ארץ כמ\"ש שמים לרום (משלי )<sup data-n=\"3235\">42</sup> וכתי' כי גבוה שמים מארץ (ישעי' נ )<sup data-n=\"3236\">43</sup> ועכ\"ז השמים משפיעים לארץ כמ\"ש ממגד תבואות שמש<sup data-n=\"3237\">44</sup> שלכן ריחוק השמים מן הארץ קצובין<sup data-n=\"3238\">45</sup> מהקב\"ה שיהיו מרוחקים כך כפי שגזר, ואם היו מרוחקים יותר לא הי' הארץ יכולה לקבל מהם, ועד\"ז יובן בחי' סוכ\"ע שאם<sup data-n=\"3239\">46</sup> היותו סובב ומקיף עכ\"ז הוא מחי', וכמ\"ש במ\"א שאין הפי' סובב ומקיף מלמעלה<sup data-n=\"3240\">47</sup> כ\"א שאת השמים ואת הארץ אני מלא<sup data-n=\"3241\">48</sup> אלא שזהו בהעלם, ולכן נק' בחי' סוכ\"ע ששייך לעולם כו', וז\"ע קדוש וא\"ו שהוא המשכה מבחי' קד\"ש<sup data-n=\"3242\">49</sup> מלה בגרמי'<sup data-n=\"3243\">50</sup> ח\"ס שהוא\"ו הוא בחי' קו והמשכה בחי' שערות כו', וע\"ש בד\"ה בהרת הנ\"ל, שזהו בחי' הארת הכתר שמאיר בז\"א, ושם שהוא\"ו הוא בחי' הקו וחוט, והיינו שנמשך אחר מה שפי' מ\"ש בזהר בענין הכל תלוי במזל<sup data-n=\"3244\">51</sup> אפי' ס\"ת בהיכל ענין יקירא קדישא<sup data-n=\"3245\">52</sup> שזהו בחי' הקו וחוט (בד\"ה יגלח א\"ד בתער<sup data-n=\"3246\">53</sup>) שהזהר אינו מדבר יותר כ\"א באצי' וכתר דאצי', והוא מאיר בכל האצי' ע\"י התלבשותו בחכמה כמ\"ש",[["3231","38","<b>בד\"ה קמפלגי . . שלא נדפס</b>: ראה גם מאמר ד\"ה זה שנדפס לעיל בתחילתו ובהנסמן שם."],["3232","39","<b>הנשמה . . מתפעלת ממקרי הגוף</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב (ס, ב</a>). שער היחוד והאמונה פ\"ז (פג, ב). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370061\" data-slug=\"torah-or\" data-id=\"3901370061\">תו\"א וירא יג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a>. ואתחנן ד, ב. לעיל שם. וש\"נ."],["3233","40","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a> ואילך. סה\"מ תר\"ם ח\"א ע' שסט ואילך. וש\"נ."],["3234","41","<b>ואתה הוא קודם שנברה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["3235","42","<b>שמים לרום (משלי )</b>: כה, ג."],["3236","43","<b>כי גבוה שמים מארץ (ישעי' נ )</b>: נה, ט [ושם: גבהו]."],["3237","44","<b>ממגד תבואות שמש</b>: ברכה לג, יד [ושם: וממגד] ובפרש\"י שם. ראה גם לעיל שם ובהערה 16."],["3238","45","<b>ריחוק השמים מן הארץ קצובין</b>: ראה חגיגה יג, א. לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 68."],["3239","46","<b>שאם</b>: כ\"ה בכ\"מ — ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 33. סה\"מ תרל\"ח ע' ה. וש\"נ."],["3240","47","<b>שאין הפי' . . מלמעלה</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה קא מיפלגי במתיבתא דרקיע ובהערה 17."],["3241","48","<b>שאת השמים . . אני מלא</b>: ירמי' כג, כד."],["3242","49","<b>קדוש וא\"ו . . מבחי' קד\"ש</b>: ראה זהר אמור צג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380920\" data-slug=\"likkutei-torah\" data-id=\"4001380920\">נצבים נ, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">יו\"כ סט, ב</a> ואילך. שה\"ש כא, ב ואילך. לו, ד. אוה\"ת תזריע כרך ד ע' א'נג."],["3243","50","<b>קד\"ש מלה בגרמי'</b>: זהר אמור צד, ב."],["3244","51","<b>הכל תלוי במזל</b>: ראה זהר אד\"ר נשא קלד, א. דברים נחמדים ממהר\"ם שיף בתחלתן [נדפסו בסוף מס' חולין]. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קכז ובהנסמן במ\"מ לשם."],["3245","52","<b>יקירא קדישא</b>: בזהר שם: האי חוטא יקירא קדישא."],["3246","53","<b>בד\"ה יגלח א\"ד בתער</b>: ראה מאמרי אדה\"ז נביאים ע' מח ואילך. אוה\"ת ישעי' כרך ב ע' תשסט ואילך."]]],[2001910334,"בע\"ח<sup data-n=\"3247\">54</sup>, ובאגה\"ק סי' ך' ד\"ה איהו וחיוהי<sup data-n=\"3248\">55</sup>, וצ\"ל שמאיר בת\"ת דז\"א ע\"י בחי' החכמה כמ\"ש בלק\"ת בד\"ה קמפלגי אם בהרת רפ\"ד בהג\"ה, שבאצי' מאיר אוא\"ס בחכמה לבד כמ\"ש בע\"ח והחכמה נק' ג\"כ שמים<sup data-n=\"3249\">56</sup> כנודע מענין שם מים<sup data-n=\"3250\">57</sup>, ע' בת\"א בד\"ה כי עמך מקור חיים<sup data-n=\"3251\">58</sup> בענין השקיפה ממעון קדשך מן השמים, ובד\"ה השמים כסאי<sup data-n=\"3252\">59</sup>, ובכ\"ד, ועכ\"ז נק' סוכ\"ע ששייך לעולם שלגבי אוא\"ס גם החכ' דאצי' כעשי' גשמי'<sup data-n=\"3253\">60</sup> נחשב כמ\"ש כולם בחכ' עשית<sup data-n=\"3254\">61</sup> (ולפ\"ז יתפרש כפשוטו מה שלא שניתי כלל לפי שגם בחי' סוכ\"ע אינו תופס מקום כלל וכמ\"ש כי נשגב שמו לבדו<sup data-n=\"3255\">62</sup> שגם בחי' נשגב הוא ג\"כ רק שם והארה כו' ורק הודו הוא על ארץ ושמים שגם על בחי' שמים סוכ\"ע הוא ג\"כ רק הודו בחי' זיו לבד, אכן זהו לגבי אוא\"ס שלמעלה מבחי' סוכ\"ע, אבל באמת גם בבחי' סוכ\"ע עצמו ג\"כ לא שניתי שאין הבריאה פועל ח\"ו שום שינוי מאחר שאינו מתלבש כו' וזהו הנה טפחות נתת ימי<sup data-n=\"3256\">63</sup> שגם מה שמאיר במל' מבחי' יומין היינו בחי' ז\"א ואפשר גם חו\"ב שנק' יום יום כמ\"ש במ\"א בענין שעשועי' יום יום<sup data-n=\"3257\">64</sup>, ועכ\"פ בחי' מוחין דז\"א זהו בכלל יומין יחשב, הוא טפחות שהוא מדוד כנ\"ל ממשל השמים שהגבהתם ורוממותם מן הארץ מדוד ת\"ק שנה<sup data-n=\"3258\">65</sup> כו'), וזהו שבאמת גם סוכ\"ע אין ערוך לעצמותו ית', ואעפ\"כ וחלדי בחי' יבשה פי' שכל מה שביבשה יש בים חוץ מן החולדה<sup data-n=\"3259\">66</sup> (שהיא ביבשה לבד וזהו וחלדי) כאין נגדך כי בחי' ממכ\"ע הוא רק הארה בעלמא (בחי' אין המהוה היש דבי\"ע, שזהו שהבריאה נק' יש מאין בחי' הארה לבד), ואין ערוך לבחי' סובב ימין של הקב\"ה בחי' וימינו תחבקני<sup data-n=\"3260\">67</sup> בחי'\n\nלאור<sup data-n=\"8557\">כ</sup> יום<sup data-n=\"8558\">כא</sup> שגם אור בכלל יום, הולך ואור עד נכון היום<sup data-n=\"8559\">כב</sup>.",[["3247","54","<b>התלבשותו בחכמה כמ\"ש בע\"ח</b>: ראה לעיל מאמר ד\"ה שלש רגלים תחוג לי ובהערה 120."],["3248","55","<b>ובאגה\"ק . . איהו וחיוהי</b>: קל, ב."],["3249","56","<b>והחכמה נק' ג\"כ שמים</b>: ראה גם אוה\"ת לך כרך ד ע' 1450 ואילך. סה\"מ תר\"ם ח\"ב ע' תריז. וש\"נ."],["3250","57","<b>שמים . . שם מים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח."],["3251","58","<b>בת\"א בד\"ה כי עמך מקור חיים</b>: מקץ לה, א."],["3252","59","<b>בת\"א . . ובד\"ה השמים כסאי</b>: בראשית א, ג."],["3253","60","<b>החכ' דאצי' כעשי' גשמי'</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה ובהערה 67."],["3254","61","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["3255","62","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג. ראה גם סה\"מ תר\"ם ח\"א ע' קעה ובהנסמן שם."],["3256","63","<b>הנה טפחות נתת ימי</b>: תהלים לט, ו."],["3257","64","<b>חו\"ב . . שעשועי' יום יום</b>: משלי ח, ל. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381212\" data-slug=\"likkutei-torah\" data-id=\"4001381212\">לקו\"ת שה\"ש כ, רע\"ד</a>."],["3258","65","<b>השמים . . הארץ . . ת\"ק שנה</b>: ראה חגיגה יג, א. ראה גם לעיל מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 23 ואילך."],["3259","66","<b>שכל מה שביבשה . . החולדה</b>: חולין קכז, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541020\" data-slug=\"torat-chaim\" data-id=\"2300541020\">תו\"ח שמות ח\"א יח, ג</a> הערה 770."],["3260","67","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג.\n\n<b>כ</b> ) <b>לאור</b>: נרשם בריש העמוד בהיפך הדף ללא ציון מקומו בפנים.\n\n<b>כא</b> ) <b>לאור יום</b>: בראשית א, ה.\n\n<b>כב</b> ) <b>הולך ואור עד נכון היום</b>: משלי ד, יח."]]],[2001910335,"מקיף, וכמו המחבק דבר בזרועו וידו שמקיפו מכל צד, וזהו מתחת זרועות עולם<sup data-n=\"3261\">68</sup> כו', ולכן כדי להיות קרי\"ס הוא ע\"י התגלות ימינו של הקב\"ה אשר וימינו טפחה שמים בחי' סוכ\"ע ממש וזהו ענין ושמן ימינו יקרא<sup data-n=\"3262\">69</sup> שמן בחי' חכ'<sup data-n=\"3263\">70</sup> שנק' שמים ימינו יקרא מלבוש חסד דא\"א כמ\"ש בלק\"ת בהעלותך הראשון פ\"ה<sup data-n=\"3264\">71</sup>, שע\"י גילוי זה נהפך ההעלם דים שהוא בחי' ההעלם שבסדר השתלשלות לבחי' גילוי ממש, וזהו מה עשה* הקב\"ה נתן ימינו על ימינו של משה, כי ימינו של משה זהו חסד דאצילות, וכמו אהרן כה\"ג הוא ימין משה<sup data-n=\"3265\">72</sup>, אבל מה שנתן הקב\"ה ימינו על ימינו של משה זהו התגלות בחי' חסד דלגאו<sup data-n=\"3266\">73</sup> חסד דע\"ק שנמשך בחסד דז\"א ועי\"ז בוקע ים כו' (הוא בחי' ההעלם השייך לגילוי), וזהו הים ראה שראה התגלות בחי' סדכ\"ס<sup data-n=\"3267\">74</sup>, פי' סתימין הם או\"א מקור בחי' עלמא דאתכסיא, אבל בחי' כתר נק' סתימו דכל סתימין שגם מבחי' הסתימין הוא סתום ונעלם לכן ע\"י שהים ראה גילוי בחי' זו אזי וינוס (וזהו שא\"ל משה מפני מה אתה בורח, א\"ל הים כו' מפני יראתו של הקב\"ה והיינו כנודע שיראה מקרוב<sup data-n=\"3268\">75</sup> לכן כאשר נתן ימינו בחי' חסד דע\"ק על ימינו של משה חסד דז\"א שזהו בחי' מקור בחי' ימי דמל' ברח הים מפני היראה, וכענין וירא העם וינועו<sup data-n=\"3269\">76</sup> שבמ\"ת, שלכן עמדו מרחוק כמ\"כ הים ברח, וזהו שמתחלה לא קיבל הים לקרוע שא\"ל מפניך אינו<sup data-n=\"3270\">77</sup> נקרע והיינו מפני ידו של משה שהוא בחי' חסד דז\"א לא קיבל לקרוע שזהו מבחי' היומין דז\"א שמאיר בים דמל' שנק' ימי כו', ומצא טענה\n\n*)ל'<sup data-n=\"8560\">כג</sup> מה עשה בכדי שיומשך בעשיה שיקרע הים דעשייה, ופי' הקב\"ה קדוש וברוך סוכ\"עכד וממכ\"ע<sup data-n=\"8561\">כד</sup> שיתגלה העלם דים הארת הסובב להיות יבשה ממכ\"ע בחי' חולדה ממ*",[["3261","68","<b>מתחת זרועות עולם</b>: ברכה לג, כז [ושם: ומתחת — ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תתד].\nראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380256\" data-slug=\"likkutei-torah\" data-id=\"4001380256\">לקו\"ת בהר מב, רע\"א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381204\" data-slug=\"likkutei-torah\" data-id=\"4001381204\">שה\"ש יח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381292\" data-slug=\"likkutei-torah\" data-id=\"4001381292\">מא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381221\" data-slug=\"likkutei-torah\" data-id=\"4001381221\">שע\"ת כג, א</a> ובהערה 9. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540130\" data-slug=\"torat-chaim\" data-id=\"2300540130\">תו\"ח וארא ח\"א נה, ד</a>. וש\"נ."],["3262","69","<b>ושמן ימינו יקרא</b>: משלי כז, טז."],["3263","70","<b>שמן בחי' חכ'</b>: ראה זהר יתרו פז, ב־ תרומה קמז, ב ובהגהת הרח\"ו שם. מאורי אור מערכת שמן אות מח וביאיר נתיב שם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370184\" data-slug=\"torah-or\" data-id=\"3901370184\">תו\"א מקץ מ, ד</a>. מאמרי אדה\"א קונטרסים ע' תקמה. וש\"נ. סה\"מ תרל\"ח ע' כג. וש\"נ. תר\"ם ח\"א ע' מט. וש\"נ."],["3264","71","<b>בלק\"ת בהעלותך הראשון פ\"ה</b>: ל, ד."],["3265","72","<b>אהרן . . ימין משה</b>: ראה אוה\"ת תצוה ע' א'תקפ ואילך ושם מציין לזהר תצוה קפא, א. וילך רפג, ב — עה\"פ מוליך (לעיל על יד הערה 7). וראה גם ואתחנן רס, ב."],["3266","73","<b>חסד דלגאו</b>: ראה זהר אד\"ר נשא קלג, ב."],["3267","74","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["3268","75","<b>יראה מקרוב</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380267\" data-slug=\"likkutei-torah\" data-id=\"4001380267\">לקו\"ת בהר מד, ד</a>. מאמרי אדה\"א בראשית ע' רמב־ קונטרסים ע' רפב־ <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540625\" data-slug=\"torat-chaim\" data-id=\"2300540625\">תו\"ח בא ח\"א קב, ד</a>־ <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540069\" data-slug=\"torat-chaim\" data-id=\"2300540069\">בשלח קמט, ד</a> ובהנסמן בהנ\"ל."],["3269","76","<b>וירא העם וינועו</b>: יתרו כ, טו."],["3270","77","<b>אינו</b>: ראה גם לעיל ובהערה 5.\n\n<b>כג</b> ) <b>ל'</b>: נרשם בריש העמוד בהיפך הדף ללא ציון מקומו בפנים. ואולי שייך לכאן.\n\n<b>כד</b> ) <b>הקב\"ה . . סוכ\"ע וממכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. לעיל מאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיע בתחילתו."]]],[2001910336,"שביומין דז\"א המאירים בבחי' מל' יש לו קדימה על משה, שהים נברא בשלישי, ומשה נברא בששי<sup data-n=\"3271\">78</sup>, אבל כשראה ימינו של הקב\"ה חסד דע\"י מיד ברח מפני היראה, וי\"ל שזהו בחי' יראת הרוממות קוצו של יו\"ד ולכן נעשו המים נצבו כמו נד<sup data-n=\"3272\">79</sup> בלתי תנועה היפך טבעם שזהו כענין אשתומם כשעה חדא<sup data-n=\"3273\">80</sup> שהוא בחי' ביטול פעולת השכל להשפיע כו' לבחי' השגה כ\"א להעלות כלי שכלו להיות מקבל בחי' כלי ריקן לגבי שלמעלה הימנו), ועי\"ז נעשה ההעלם גילוי, ולכן זכו לנבואה (שהנבואה היא בחי' גילוי ההעלם כמ\"ש במד\"ר תצוה פל\"ח<sup data-n=\"3274\">81</sup> אין עין אלא נבואה שהעין הוא כלי הראי' להיות בחי' ראתה שפחה על הים<sup data-n=\"3275\">82</sup>, וכמו שמואל שאמר על עצמו אנכי הרואה<sup data-n=\"3276\">83</sup> שקורין לנביא רואה כמ\"ש (ש\"א ט') כי לנביא היום יקרא לפנים הרואה<sup data-n=\"3277\">84</sup> והיינו מפני כי הנביא מגלה מה שנעלם מעין כל אדם כמו בענין האתונות שנאבדו לקיש אבי שאול<sup data-n=\"3278\">85</sup>, וכן בכל דבר הנעלם כו', ולכן בקרי\"ס שההעלם נעשה גילוי זכו כולם לנבואה, ונבואתם הי' גבוה<sup data-n=\"3279\">86</sup> יותר משארי הנביאים שנתנבאו בכה<sup data-n=\"3280\">87</sup> ולכן) אמרו זה אלי<sup data-n=\"3281\">88</sup>, ע\"ד מ\"ש לע\"ל ואמר ביום ההוא<sup data-n=\"3282\">89</sup> הנה אלקינו זה (שמבחי' הוא שהוא נעלם יהי' בחי' זה בחי' גילוי), וכן בקרי\"ס כתי' ויושע כו' ביום ההוא<sup data-n=\"3283\">90</sup> כו' זה אלי, וזהו דכתי' בקרי\"ס וירא ישראל את היד הגדולה<sup data-n=\"3284\">91</sup> היינו בחי' ימינו של הקב\"ה שהיא הנק' יד הגדולה, ע\"ד ולגדולתו אין חקר<sup data-n=\"3285\">92</sup> (שלגדולתו העצמית אין חקר שזהו בחי' יד הגדולה שלמעלה מבחי' חסד דרועא ימינא<sup data-n=\"3286\">93</sup>, בחי' חסד דז\"א), ובחי' יד הגדולה זו ראו ממש ע\"י קרי\"ס שהי' התגלות בחי' סוכ\"ע ממש, בחי' יד הגדולה, והוא ע\"י שנתן הקב\"ה ימינו יד הגדולה סוכ\"ע על ימינו של משה חסד דאצי' כו'.\n\nדריש<sup data-n=\"8562\">כה</sup> רב שילא<sup data-n=\"8563\">כו</sup> לך ה' הגדולה זו מע\"ב וכה\"א עושה גדולות עד אין חקר (איוב<sup data-n=\"8564\">כז</sup> ובמתניתא תני לך הגדולה זו קרי\"סג, ולכאו' ה\"ז דרשות חלוקות שלר' שילא הגדולה זהו בריאת העולם שהים מעלים ורוקע הארץ על המים<sup data-n=\"8565\">כח</sup>, ולדרש דמתניתא הגדולה זהו מה שהפך ים ליבשה, וצ\"ל שלא פליגא שר\"ש מדבר בחסד דז\"א כי אמרתי עולם חסד יבנה<sup data-n=\"8566\">כט</sup> לכן הגדולה (כמו שמקובלי' הראשונים<sup data-n=\"8567\">ל</sup> קראו חסד בשם גדולה) זו מע\"ב, והמתניתא מפרש גדולה כמו יד הגדולה דא\"א ועת\"י לכן הגדולה זה קרי\"סג דבעתיקא תליא<sup data-n=\"8568\">לא</sup>.",[["3271","78","<b>שהים נברא בשלישי . . בששי</b>: ראה שמו\"ר שבהערה 3."],["3272","79","<b>נצבו כמו נד</b>: בשלח טו, ח."],["3273","80","<b>אשתומם כשעה חדא</b>: דניאל ד, טז. שבת מז, א. ראה סידור שער נפ\"א צב, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550343\" data-slug=\"torat-chaim\" data-id=\"2300550343\">תו\"ח פקודי ח\"ב תנ, ד</a>. וש\"נ."],["3274","81","<b>במד\"ר תצוה פל\"ח</b>: סימן ד. מובא גם לעיל מאמר ד\"ה להבין וכו' בענין הציץ על יד הערה 43."],["3275","82","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540775\" data-slug=\"torat-chaim\" data-id=\"2300540775\">תו\"ח בשלח ח\"א קצד, ב</a> ואילך. לעיל מאמר ד\"ה אז ישיר בתחילתו."],["3276","83","<b>אנכי הרואה</b>: שמו\"א ט, יט."],["3277","84","<b>(ש\"א ט') כי לנביא . . הרואה</b>: פסוק ט."],["3278","85","<b>האתונות . . אבי שאול</b>: שם פסוק ג."],["3279","86","<b>ונבואתם הי' גבוה</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה ובהערה *13."],["3280","87","<b>הנביאים שנתנבאו בכה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540144\" data-slug=\"torat-chaim\" data-id=\"2300540144\">תו\"ח בשלח ח\"א קמד, ב</a> הערה 29. אוה\"ת מטות ע' א'תצד. וראה גם לעיל מאמר ד\"ה קדש ישראל לה' פ\"א."],["3281","88","<b>זה אלי</b>: בשלח טו, ב."],["3282","89","<b>ואמר ביום ההוא</b>: ישעי' כה , ט."],["3283","90","<b>ויושע כו' ביום ההוא</b>: בשלח יד, ל."],["3284","91","<b>וירא ישראל את היד הגדולה</b>: שם יד, לא."],["3285","92","<b>ולגדולתו אין חקר</b>: תהלים קמה, ג."],["3286","93","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה יז, א.\n\n<b>כה</b> ) <b>דריש</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים.\n\n<b>כו</b> ) <b>דריש רב שילא</b>: ראה ברכות נח, א.\n\n<b>כז</b> ) <b>עושה גדולות . . (איוב</b>: לכאורה צ\"ל: (איוב ט, י).\n\n<b>כח</b> ) <b>ורוקע הארץ על המים</b>: ע\"פ תהלים קלו, ו. ברכות השחר.\n\n<b>כט</b> ) <b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג.\n\n<b>ל</b> ) <b>שמקובלי' הראשונים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380785\" data-slug=\"likkutei-torah\" data-id=\"4001380785\">לקו\"ת עקב יז, ד</a>. מאמרי אדה\"א נ\"ך ע' תקלד. וש\"נ. תו\"ח ויצא קעה, ד ובהנסמן לשם. סה\"מ תרכ\"ז ע' קצח. ע' רב. ע' תנ. תר\"ם ח\"ב ע' תרמז ואילך. וש\"נ.\n\n<b>לא</b> ) <b>דבעתיקא תליא</b>: ראה זהר בשלח מח, א. נב, ב."]]],[2001910337,"<h3>וידבר כו' קדושים תהיו</h3>\n<b>בס\"ד פ' קדושים</b>\n<b>וידבר</b> כו' אל משה לאמר<sup data-n=\"3288\">2</sup>, דבר אל כל עדת בנ\"י ואמרת אליהם קדושים תהיו<sup data-n=\"3287\">1</sup> כי קדוש אני ה' אלקיכם<sup data-n=\"3289\">3</sup>, וצ\"ל ענין הנתינות<sup data-n=\"3290\">4</sup> טעם שנותן באמרו קדושים תהיו לפי שקדוש אני, איך יתחייב שיהי' יציר כפיו דומה לקונו, כמ\"ש האוה\"ח<sup data-n=\"3291\">5</sup> בפי' החומש, והגם שארז\"ל במד\"ר פ' קדושים פך\"ה<sup data-n=\"3292\">6</sup> ע\"פ כי תבואו אל הארץ ונטעתם<sup data-n=\"3293\">7</sup> ר\"י בר' סימן<sup data-n=\"3294\">8</sup> פתח אחרי כו' תלכו<sup data-n=\"3295\">9</sup> וכי אפשר לב\"ו להלוך אחר הקב\"ה אותו דכתי'<sup data-n=\"3296\">10</sup> בים דרכך<sup data-n=\"3297\">11</sup> כו' אלא מתחלת ברייתו של עולם כו' אף אתם כו', וכן מ\"ע מן",[["3288","2","<b>וידבר כו' אל משה לאמר</b>: קדושים יט, א."],["3287","1","<b>וידבר כו' קדושים תהיו</b>: אולי מאמר זה והבא אחריו ד\"ה [נקדישך] וביאור הענין נכתבו בהמשך אחד [ראה ציון האותיות שבהמאמרים אלא שאות ג' נכפל]. למאמר זה רפ\"ב ראה אוה\"ת קדושים כרך ד ע' א'נח. ולמאמר הבא ראה אוה\"ת שם ע' א'נט ובהנסמן בריש המאמר שם.\nהכותרת המופיעה בריש המאמר נעתקה מבוך 2086.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לקמן בחלק הנחותיו.\nהמאמר נזכר בסה\"מ תרנ\"ג ע' רנח.\nהמאמר נרשם בגוכתי\"ק ואח\"כ הועתק בכת\"י מעתיק."],["3289","3","<b>דבר . . קדושים . . ה' אלקיכם</b>: קדושים שם, ב."],["3290","4","<b>הנתינות</b>: אוצ\"ל: הנתינת."],["3291","5","<b>כמ\"ש האוה\"ח</b>: כאן ד\"ה כי קדוש."],["3292","6","<b>במד\"ר פ' קדושים פך\"ה</b>: סימן ג.\nמובא גם בכ\"מ ומהם: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380102\" data-slug=\"likkutei-torah\" data-id=\"4001380102\">לקו\"ת ויקרא ז, א</a>. אוה\"ת (יהל אור) תהלים ע' רעא. סה\"מ תרל\"ו ח\"ב ס\"ע שטז ואילך. ע' שמב."],["3293","7","<b>כי תבואו אל הארץ ונטעתם</b>: קדושים יט, כג [ושם: וכי — אבל כ\"ה גם בסה\"מ תרל\"ו שם ע' שיז]."],["3294","8","<b>סימן</b>: בכת\"י המעתיק: סימון."],["3295","9","<b>אחרי כו' תלכו</b>: פ' ראה יג, ה."],["3296","10","<b>דכתי'</b>: בויק\"ר שם: שכתוב בו."],["3297","11","<b>בים דרכך</b>: תהלים עז, כ."]]],[2001910338,"התורה ללכת בדרכיו<sup data-n=\"3298\">12</sup> מה הוא חנון כו', מה הוא רחום אף אתה הי' רחום כמארז\"ל בספרי<sup data-n=\"3299\">13</sup> וברמב\"ם<sup data-n=\"3300\">14</sup> הובא בש\"ע רבינו ז\"ל סי' קנ\"ו סעי' ג'<sup data-n=\"3301\">15</sup> שציונו להתדמות לבוראינו כבי', הלא גם הם עצמם אמרו וכי אפשר להלוך כו', ועוד שענין ההילוך אחריו וכן ההילוך בדרכיו מה הוא רחום, אינו דומה למעלת בחי' הקדושה, שמעלת הקדושה יש לו יתרון על בחי' ההילוך בדרכיו וכ\"ש על ענין בחי' ההילוך אחרי ה' כנודע, וא\"כ אינו מובן נתינת הטעם שפני<sup data-n=\"3302\">16</sup> שהוא ית' קדוש לכן תהיו ג\"כ קדושים, וגם צ\"ל שלכאו' בחי' קדושים תהיו כמו שפירשו המפרשים<sup data-n=\"3303\">17</sup> והוא מהמד\"ר במקומו<sup data-n=\"3304\">18</sup> לקדש ולגדור עצמינו כו' אינו בערך כלל לבחי' כי קדוש אני, שהוא ית' הוא קדוש ומובדל לגמרי, וכדכתי' אני ה' לא שניתי<sup data-n=\"3305\">19</sup> כלל, ואתה הוא קודם שנבה\"ע<sup data-n=\"3306\">20</sup> ואתה הוא לאחר שנברה\"ע, בלי שום שינוי כלל שזהו מפני שהוא קדוש ומובדל כו', ומ\"ע ההתדמות מה שקדושי' תהיו שארז\"ל שתהיו גדורים מן העריות<sup data-n=\"3307\">21</sup>\n\nפתחי<sup data-n=\"8569\">א</sup> לי כחודה של מחט<sup data-n=\"8570\">ב</sup> ואני אפתח כו' לכן ע\"י הרחקה משס\"ה ל\"ת<sup data-n=\"8571\">ג</sup> וקדש עצמך במותר<sup data-n=\"8572\">ד</sup> עי\"ז אפתח כו' אולם מם אמה<sup data-n=\"8573\">ה</sup> ב' כפין<sup data-n=\"8574\">ו</sup> כתר דאו\"י וכתר דאו\"ח, עיקר בחי' קדוש מצד הארת הכתר, ע' ונקדשתי<sup data-n=\"8575\">ז</sup>, ובהרת בלק\"ת<sup data-n=\"8576\">ח</sup> וע' תער השכירה<sup data-n=\"8577\">ט</sup> קדש מו\"ס חכ' שבכתר, וקדוש וא\"ו המשכה מחכ' שבכתר ומפני שת\"ת עולה עד הכתר<sup data-n=\"8578\">י</sup> נק' קדוש<sup data-n=\"8579\">יא</sup>.",[["3298","12","<b>מ\"ע מן התורה ללכת בדרכיו</b>: ראה בנוסף לשו\"ע המצויין כאן בפנים <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131286\" data-slug=\"likkutei-sichot\" data-id=\"1300131286\">לקו\"ש</a> בין המצרים כרך יג ע' 280 הערה 3."],["3299","13","<b>בספרי</b>: עקב יא, כב."],["3300","14","<b>וברמב\"ם</b>: הל' דיעות פ\"א, ה\"ו."],["3301","15","<b>בש\"ע רבינו ז\"ל סי' קנ\"ו סעי' ג'</b>: יש לציין שסימן זה וכן הקודמו נדפסו לראשונה במהדורת זיטאמיר שנת תרט\"ז."],["3302","16","<b>שפני</b>: בכת\"י המעתיק: שמפני."],["3303","17","<b>שפירשו המפרשים</b>: ראה רש\"י עה\"פ."],["3304","18","<b>מהמד\"ר במקומו</b>: ראה ויק\"ר פכ\"ד, ו."],["3305","19","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a> ואילך. סה\"מ תר\"ם ח\"א ע' שסט ואילך. וש\"נ."],["3306","20","<b>ואתה הוא קודם שנבה\"ע</b>: ראה נוסח תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["3307","21","<b>שתהיו גדורים מן העריות</b>: ראה לעיל הערה 17.\n\n<b>א</b> ) <b>פתחי</b>: נרשם בשולי היריעה בג' טורים שביניהם שני קוים ללא ציון מקומו בפנים.\n\n<b>ב</b> ) <b>פתחי לי כחודה של מחט</b>: ראה ס' חרדים בהקדמה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011205\" data-slug=\"likkutei-sichot\" data-id=\"1300011205\">לקו\"ש ויקהל ח\"א ע' 191</a> הערה 17. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370424\" data-slug=\"torah-or\" data-id=\"3901370424\">תו\"א מג\"א צד, ג</a>. סה\"מ תרל\"ח ע' תסד. וש\"נ.\n\n<b>ג</b> ) <b>משס\"ה ל\"ת</b>: מכות כג, סע\"ב.\n\n<b>ד</b> ) <b>וקדש עצמך במותר</b>: ספרי פ' ראה יד, כא. יבמות כ, א. ראה תניא ספכ\"ז וב”מ\"מ הגהות והע\"ק\" לשם. ספ\"ל.\n\n<b>ה</b> ) <b>אולם מם אמה</b>: מדות פ\"ג, מ\"ז.\n\n<b>ו</b> ) <b>מם . . ב' כפין</b>: ראה גם [באו\"א] <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381271\" data-slug=\"likkutei-torah\" data-id=\"4001381271\">לקו\"ת שה\"ש לה, ג</a>.\n\n<b>ז</b> ) <b>קדוש . . הכתר ע' ונקדשתי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380215\" data-slug=\"likkutei-torah\" data-id=\"4001380215\">לקו\"ת אמור לב, ב</a> ואילך.\n\n<b>ח</b> ) <b>ובהרת בלק\"ת</b>: תזריע כב, ג.\n\n<b>ט</b> ) <b>וע' תער השכירה</b>: ראה מאמרי אדה\"ז נביאים ע' מה. ע' מט ואילך. אוה\"ת ישעי' כרך ב' ע' תשעב.\n\n<b>י</b> ) <b>שת\"ת עולה עד הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב). מאמרי אדה\"ז הקצרים ע' תקעט.\n\n<b>יא</b> ) <b>שת\"ת . . נק' קדוש</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>."]]],[2001910339,"וכדומה כו'. ובס' פנים יפות<sup data-n=\"3308\">22</sup> פי' על ענין קדושים כו' כי קדוש אני ע\"ד מה<sup data-n=\"3309\">23</sup> יפו<sup data-n=\"3310\">24</sup> ירושתינו מהאבות הקדושים, וכמ\"ש במד\"ר שכל האבות נק' בשם ישראל<sup data-n=\"3311\">25</sup> וזהו בני ישראל ע\"ש פירושו, והיינו כי אברהם נק' ישראל כמ\"ש ומושב בנ\"י<sup data-n=\"3312\">26</sup> כו', שחשבון הזה מתחיל מימי אברהם<sup data-n=\"3313\">27</sup> שנמצא נק' אברהם בשם ישראל, וכתי' ואלה שמות בנ\"י<sup data-n=\"3314\">28</sup> כו' יעקב, שכולל יעקב ג\"כ בכלל בני ישראל נמצא שיצחק נק' ישראל, ויעקב עצמו א\"ל הקב\"ה<sup data-n=\"3315\">29</sup> לא יעקב יאמר עוד שמך כ\"א ישראל<sup data-n=\"3316\">30</sup> יהי' שמך<sup data-n=\"3317\">31</sup>, שנמצא נקראו כל האבות בש' ישראל, וענין שם ישראל נא' בפ' וישלח הטעם לפי כי שרית עם אלקים כו' ותוכל<sup data-n=\"3318\">32</sup>, פי' שרית היינו שמשתרר על ש' אלקים המסתיר שלא יהי' מסתיר עוד ויהי' גילוי ש' הוי' כדפי' בלק\"ת בד\"ה לא הביט און ביעקב פ\"ה ד\"ה ולכן לא ראה עמל בישראל דע\"ב סע\"א<sup data-n=\"3319\">33</sup>, שנמצא ש' ישראל זהו ע\"ד כמו ש' הוי' שמושל ושולט על בחי' ש' אלקים, וכמו בענין הבריאה שבש' אלקים נא' ברא<sup data-n=\"3320\">34</sup>, ובש' הוי' ציוה ונבראו<sup data-n=\"3321\">35</sup> שע\"י ציוי ש' הוי' נברא ע\"י בחי' ש' אלקים, כמ\"ש במ\"א בענין הוא אמר ויהי דקאי על ש' אלקים והוא ציוה ויעמוד<sup data-n=\"3322\">36</sup> קאי על ש' הוי' שמושל ומצוה כו', וענין בחי' אמירת קדוש שהשרפים אומרים נא' על ש' הוי' כמ\"ש (בישעי' וא\"ו ג') קק\"ק ה' צבאות וכן כאן אומר כי קדוש אני הוי' אלקיכם, והאבות נק' בשם ישראל ע\"ש כי שרית עם אלקים ל' שררה כו' ה\"ז כדמיון ש' הוי' כבי'<sup data-n=\"3323\">37</sup>, והגם דכתי' ושמי הוי' לא נודעתי להם<sup data-n=\"3324\">38</sup>, נת' ע\"ז בכ\"ד שלא נודעתי בבחי' יעוד<sup data-n=\"3325\">39</sup> כו' א\"נ ש' הוי' דלעילא<sup data-n=\"3326\">40</sup>, אבל עכ\"ז הגיעו בעבודתם גם בבחי' ש' הוי' ג\"כ, וכמ\"ש כמ\"פ ש' הוי' אצל האבות<sup data-n=\"3327\">41</sup> כו', גם הנה ארז\"ל על האבות שהטעימן מעין עוה\"ב<sup data-n=\"3328\">42</sup>, וארז\"ל",[["3308","22","<b>ובס' פנים יפות</b>: מובא גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 18. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080108\" data-slug=\"or-hatorah-hb\" data-id=\"8160080108\">אוה\"ת ויקרא כרך א' ע' קח</a>."],["3309","23","<b>מה יפה ירושתינו</b>: נוסח תפלת השחר. תדא\"ר ספכ\"א."],["3310","24","<b>יפו</b>: לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 19 יפה."],["3311","25","<b>שכל האבות נק' בשם ישראל</b>: ב\"ר פס\"ג, ג. ראה גם ילקוט שמעוני ר\"פ תולדות רמז קי."],["3312","26","<b>ומושב בנ\"י</b>: בא יב, מ."],["3313","27","<b>שחשבון . . מימי אברהם</b>: ראה מכילתא ולק\"ט בא שם. רש\"י מגילה ט, א־ בא ובב\"ר שם."],["3314","28","<b>ואלה שמות בנ\"י</b>: שמות א, א. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 23. ילקוט שמעוני מהדורת ירושלים תשל\"ג ר\"פ תולדות שם ע' 511 הערה 91."],["3315","29","<b>א\"ל הקב\"ה</b>: בב\"ר ובילקוט שמעוני שם ליתא."],["3316","30","<b>לא יעקב . . כ\"א ישראל</b>: וישלח לב, כט [כ\"ה בב\"ר שם — כן אמר לו המלאך. ראה הערה שלפנ\"ז]."],["3317","31","<b>כ\"א ישראל יהי' שמך</b>: שם לה, י [כן אמר לו הקב\"ה — ראה לעיל ובהערה 29]."],["3318","32","<b>בפ' וישלח . . כי שרית . . ותוכל</b>: לב, כט."],["3319","33","<b>בלק\"ת . . דע\"ב סע\"א</b>: בלק."],["3320","34","<b>שבש' אלקים נא' ברא</b>: בראשית א, א."],["3321","35","<b>ובש' הוי' ציוה ונבראו</b>: תהלים קמח, ה."],["3322","36","<b>הוא אמר . . ש' אלקים . . ציוה ויעמוד</b>: תהלים לג, ט. ראה גם לעיל מאמר ד\"ה וירא ישראל את היד הגדולה פ\"א."],["3323","37","<b>כבי'</b>: ראה לעיל מאמר ד\"ה זכור את יום השבת הערה 41."],["3324","38","<b>ושמי הוי' לא נודעתי להם</b>: וארא ו, ג. ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 24."],["3325","39","<b>שלא נודעתי בבחי' יעוד</b>: ראה גם לעיל מאמר ד\"ה זכור את יום השבת ובהערה 94."],["3326","40","<b>ש' הוי' דלעילא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470127\" data-slug=\"or-hatorah-hb\" data-id=\"8316470127\">אוה\"ת וארא ע' קכז</a>. כרך ז ע' ב'תקנ ואילך. ע' ב'תקנט. ע' ב'תקסד ואילך. פלח הרמון וארא ע' נב. אמור ע' דש."],["3327","41","<b>וכמ\"ש כמ\"פ ש' הוי' אצל האבות</b>: ראה גם סה\"מ תרל\"ח ע' ב. לעיל הערה 38."],["3328","42","<b>האבות שהטעימן מעין עוה\"ב</b>: ב\"ב טז, סע\"ב ואילך."]]],[2001910340,"עתידים צדיקים שיקראו ע\"ש של הקב\"ה ופירש\"י<sup data-n=\"3329\">43</sup> שיהי' שמם הוי', א\"כ האבות שהטעימן מעין עוה\"ב לכן גם עכשיו הי' עבודתם שנק' ישראל ע\"ש כי שרית עם אלקים, והיינו ש' הוי' כו', וא\"כ עפ\"ז יובן קצת איך ששייך שעדת בני ישראל שהם בני האבות שנק' ישראל כשיקדישו א\"ע מן הדברים שציונו בוראינו אשר עי\"ז קדושים תהיו ג\"כ, וזהו שמתחיל וידבר ה' כו' ואח\"כ פ\"ב דבר אל כל עדת, שפי' דבר הוא מל' הנהגה<sup data-n=\"3330\">44</sup> והמשכה כמו ידבר עמים<sup data-n=\"3331\">45</sup>, שהוי' הנהיג והמשיך לכל עדת בנ\"י שנק' בני ישראל שהם בני האבות שנק' ישראל כנ\"ל שתהיו קדושים לפי שאני הוי' קדוש הוא ואתם בני האבות שנק' ישראל שענינו הוא ג\"כ כמו ש' הוי' כבי', לכן כאשר תקיימו לגדור א\"ע מכל הציויים הנאמרים בפרשה תהיו ג\"כ קדושים כו'.\nב) <b>וביאור</b> הענין יובן בהקדם ענין דכתיב (ישעי' ד' ג') והי' הנשאר בציון<sup data-n=\"3332\">46</sup> כו' קדוש יאמר לו, וארז\"ל פ\"ה דב\"ב דע\"ה ב' א\"ר אלעזר עתידין צדיקים שאומרי' לפניהם קדוש<sup data-n=\"3333\">47</sup> כדרך שאומרים לפני הקב\"ה שנא' והי' הנשאר כו' קדוש\n\n<i>נרשם בשולי היריעה:</i>\nתירוץ על מ\"ש רז\"ל יכול כמוני, קדושתי למעלה<sup data-n=\"8580\">יב</sup>, י\"ל ע\"פ מארז\"ל ע\"פ אל אלקי ישראל<sup data-n=\"8581\">יג</sup>, אתה אלקה בעליונים<sup data-n=\"8582\">יד</sup> בד\"ה ויכל<sup data-n=\"8583\">טו</sup>, עולמי מי בראך<sup data-n=\"8584\">טז</sup> בד\"ה הבאים<sup data-n=\"8585\">יז</sup>, וכמו שהשיב פ\"א אחד מחכמי הזמן על השאלה אם הוא ית' כל יכול, למה לא ברא כמותו<sup data-n=\"8586\">יח</sup>, שכבר ברא כמותו יעקב אלקה בתחתונים<sup data-n=\"8587\">יט</sup>, ומ\"מ אדם רק אדמה<sup data-n=\"8588\">כ</sup> לכן יכול כמוני, שהרי הוא רק כמראה אדם<sup data-n=\"8589\">כא</sup> ולא אדם.",[["3329","43","<b>עתידים צדיקים . . ופירש\"י</b>: כ\"ה בכ\"מ — ראה ב\"ב עה, ב וברשב\"ם שם. לקמן בשולי הגליון לפ\"ב ד\"ה וגם י\"ל. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 40. לעיל מאמר ד\"ה מגילה נקראת על יד הערה לז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080106\" data-slug=\"or-hatorah-hb\" data-id=\"8160080106\">אוה\"ת ויקרא כרך א ע' קו</a>. סה\"מ תרל\"ג ע' נב ואילך. תרל\"ח ע' כו. וש\"נ. ראה גם לקמן הערה 48."],["3330","44","<b>דבר הוא מל' הנהגה</b>: ראה מפרשים לתהלים מז, ד. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה זאת תהי' תורת המצורע ובהערות 62-63."],["3331","45","<b>ידבר עמים</b>: תהלים מז, ד."],["3332","46","<b>והי' הנשאר בציון</b>: להבא בסמוך השווה אוה\"ת קדושים כרך ד ע' א'נח."],["3333","47","<b>עתידין צדיקים . . קדוש</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו\"א מג\"א צז, רע\"א</a>. אמ\"ב שער הק\"ש עח, ב. סה\"מ תרכ\"ו ס\"ע פו ואילך.\n\n<b>יב</b> ) <b>יכול כמוני קדושתי למעלה</b>: ויק\"ר פכ\"ד, ט.\n\n<b>יג</b> ) <b>אל אלקי ישראל</b>: וישלח לג, כ.\n\n<b>יד</b> ) <b>אתה אלקה בעליונים</b>: ב\"ר פע\"ט, ח.\n\n<b>טו</b> ) <b>בד\"ה ויכל</b>: תרכ\"א — לא נדפס לע\"ע.\n\n<b>טז</b> ) <b>עולמי מי בראך</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' פ\"א. וש\"נ.\n\n<b>יז</b> ) <b>בד\"ה הבאים</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370347\" data-slug=\"torah-or\" data-id=\"3901370347\">תו\"א שמות נג, ג</a>.\n\n<b>יח</b> ) <b>וכמו שהשיב . . למה לא ברא כמותו</b>: כ\"ק אדמו\"ר הצמח צדק — ראה גם סה\"מ תרמ\"ט ע' עדר.\n\n<b>יט</b> ) <b>יעקב אלקה בתחתונים</b>: ראה ב\"ר שם. לקו\"ת להאריז\"ל ס' שופטים בתחילתו.\n\n<b>כ</b> ) <b>אדם . . אדמה</b>: ישעי' יד, יד. ראה עבוה\"ק ח\"א חלק היחוד פי\"ז. של\"ה תולדות אדם ג, א. מאמרי אדה\"א דברים ח\"א ע' קכב. וש\"נ. בראשית ע' קסב. וש\"נ.\n\n<b>כא</b> ) <b>כמראה אדם</b>: יחזקאל א, כו."]]],[2001910341,"כו' ופי'<sup data-n=\"3335\">49</sup> רש\"י<sup data-n=\"3334\">48</sup> מלאכים יאמרו, וע' בספר כלי פז<sup data-n=\"3336\">50</sup> בישעי' במקומו שהביא בשם הרמ\"ק שהקשה איך יתכן זה שיאמרו קדוש לפני הצדיקים כדרך שאומרים לפני הקב\"ה שהוא דבר שאין השכל הולמו, ותירץ שע\"י שהנשמות יתעלו ויוכללו במדת צדיק וצדק שהם יסוד ומל', א\"כ הקדוש שיאמרו המלאכים לפני הקב\"ה זהו ג\"כ אומרים לפניהם כיון שנכללו בעצם הספירות, וזהו דוחק גדול<sup data-n=\"3337\">*51</sup>, ובחנם נדחק דהא כתיב כעת יאמר ליעקב ולישראל מה פעל אל (בפ' בלק ך\"ג ך\"ג) ופירש\"י שמחיצתן לפנים ממלאכי השרת והם ישאלו מהם<sup data-n=\"3338\">51</sup> מה פעל אל, והוא מהמד\"ר שם פ' בלק דרע\"ט ג'<sup data-n=\"3339\">52</sup>, ופי' שיאמרו לפניהם קדוש (סד\"ה וקבל היהודים דקס\"ב א'<sup data-n=\"3340\">53</sup>) כי הנה קדוש הוא בחי'<sup data-n=\"3341\">54</sup> המשכת קדש העליון שהוא\"ו שבקדוש מורה<sup data-n=\"3342\">55</sup> על המשכה, ולע\"ל תהיינה כל ההמשכות מלמטה למעלה שעיקר הגילוי יהי' למטה, ומלאכי מעלה יקבלו הארה ממטה כו', והיינו כמ\"ש (יואל ב' ט\"ז) והללתם<sup data-n=\"3343\">56</sup> את ש' כו' אשר עשה עמכם להפליא (צו ד\"ה ואכלתם ד\"ז ע\"ג<sup data-n=\"3344\">57</sup>) כי לע\"ל<sup data-n=\"3345\">58</sup> אחר כל הבירורים והעליות שיתעלו כל הדברים התחתונים ע\"י הנשמות דעתה, והנשמות דעכשיו יתעלו<sup data-n=\"3346\">59</sup> ע\"י הנשמות שיתגלו לעתיד אז יהי' א\"ח עט\"ב<sup data-n=\"3347\">60</sup> בבחי' אור חוזר ממטה למעלה כתר מל' שיהי' מל' בבחי' כתר נעוץ סופן בתחילתן<sup data-n=\"3348\">61</sup> ויהי'<sup data-n=\"3349\">62</sup> כל ההשפעות ע\"י בחי' מל', וכמ\"ש והי' ביום ההוא יצאו מים חיים מירושלם חצים אל הים הקדמוני<sup data-n=\"3350\">63</sup> כו',",[["3335","49","<b>ופי' רש\"י</b>: ראה רשב\"ם שם ד\"ה לומר לפניהם."],["3334","48","<b>ופי' רש\"י</b>: כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450598\" data-slug=\"or-hatorah-hb\" data-id=\"8316450598\">אוה\"ת</a> קדושים שם. עקב ע' תקצח. פ' ראה ס\"ע תשצ. סה\"מ תרל\"ט ח\"ב ע' תה. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 48. ראה גם לעיל הערה 43."],["3336","50","<b>בספר כלי פז</b>: לר' שמואל לאנייאדו. ראה גם סה\"מ תרל\"ח ע' עג הערה 236.\nמובא גם בכ\"מ ומהם: אוה\"ת קדושים שם. ישעי' כרך ב' ע' תשסב. סה\"מ תרכ\"ו ס\"ע פא. תרכ\"ט ע' קעח. תרל\"ט ח\"ב ס\"ע תה ואילך [ושם: ובספר כלי פז על ישעי' הביא שהרמ\"ק בספר הפרד\"ס שלו . . ותירץ הרמ\"ק בס' הפרד\"ס]. [ועד\"ז שם] ע' תקפא. סה\"מ תר\"ן ע' שנב [כנ\"ל]. תרפ\"ג ס\"ע רכא."],["3337","*51","<b>וזהו דוחק גדול</b>: ראה גם לקמן בסיום המאמר. סה\"מ תרל\"ט ח\"ב ע' תשי."],["3338","51","<b>מהם</b>: כ\"ה גם באוה\"ת קדושים שם. ברש\"י: להם."],["3339","52","<b>מהמד\"ר שם פ' בלק דרע\"ט ג'</b>: במהדורת אמשטרדם ת\"א. בדפוסים הנפוצים פ\"כ, כ."],["3340","53","<b>סד\"ה וקבל היהורים דקס\"ב א'</b>: בתו\"א מג\"א מהדורת קאפוסט תקצ\"ז. ובמהדורת קה\"ת שם צז, רע\"א. הכוונה שהבא בסמוך הוא לשון התו\"א.\nציון זה נרשם בפנים המאמר ועה\"ג כאן באה הוראה להמעתיק: ”משבשח\"ע אצ\"ל\" מה שבין שני חצאי עיגול אין צריך להעתיק.\nאמנם המעתיק העתיקו בפנים המאמר. וכן לקמן על יד הערה 57. וכן לקמן על יד הערה 67. וכן לקמן ובהערה 94. וכן לקמן על יד הערה 124. ולכאורה צ\"ל שהי' אח\"כ עוד הוראות ע\"ד הנ\"ל שלא הגיע לידינו — ועפ\"ז נשארו הציונים בפנים."],["3341","54","<b>בחי'</b>: בתו\"א: ענין."],["3342","55","<b>שהוא\"ו שבקדוש מורה</b>: שם: בוא\"ו המורה."],["3343","56","<b>(יואל ב' ט\"ז) והללתם</b>: לפנינו פסוק כו."],["3344","57","<b>צו ד\"ה ואכלתם ד\"ז ע\"ג</b>: בלקו\"ת. הכוונה שהבא בסמוך הוא לשון הלקו\"ת.\nציון זה נרשם בפנים המאמר ועה\"ג כאן באה הוראה להמעתיק: ”משבשח\"ע אצ\"ל\" מה שבין שני חצאי עיגול אין צריך להעתיק. ראה לעיל הערה 53."],["3345","58","<b>לע\"ל</b>: בלקו\"ת: לעתיד."],["3346","59","<b>דעכשיו יתעלו</b>: שם: דעתה."],["3347","60","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["3348","61","<b>נעוץ סופן בתחלתן</b>: ראה ס\"י פ\"א, מ\"ז."],["3349","62","<b>בתחלתן ויהי'</b>: בלקו\"ת שם: כו' ויהיו."],["3350","63","<b>והי' ביום ההוא . . הקדמוני</b>: זכרי' יד, ח. צויין לקמן רפ\"ג בפנים."]]],[2001910342,"ועמ\"ש בלק\"ת בשה\"ש סד\"ה קול דודי<sup data-n=\"3352\">65</sup> בענין האבות והאמהות<sup data-n=\"3351\">64</sup>, ויהי' אז בבחי' פלא, וזהו אשר עשה עמכם להפליא היינו שסוף מעשה יהיו בחי' תחלה בחי'<sup data-n=\"3353\">66</sup> פלא כתר מל' כו', וא\"כ מובן ענין עתידים צדיקים שיאמרו המלאכים לפניהם קדוש כדרך שאומרים עכשיו לפני הקב\"ה שהרי ההמשכה יהי' ממטלמ\"ע וכדכתי' יצאו מ\"ח מירושלם, והענין הוא דהנה עכשיו בחי' המל' מקבל מז\"א (ואכלתם הנ\"ל וסוף ביאור כעככ\"ח דמ\"ח ע\"ב<sup data-n=\"3354\">67</sup>)<sup data-n=\"3355\">68</sup> שעכשיו צלותא בחשאי<sup data-n=\"3356\">69</sup>, מפני שעכשיו אין קול נשמע לבחי' כלה, ועמ\"ש במ\"א בענין קול באשה ערוה<sup data-n=\"3357\">70</sup> כו', ובד\"ה מהרה ישמע<sup data-n=\"3358\">71</sup> וא\"ו דגחון, בענין קול כלה כו', והיינו מפני שעתה הדבור בטל לגבי בחי' המחשבה עד\"מ, וכמ\"כ אשה טפילה לבעלה<sup data-n=\"3359\">72</sup>, ולכן מ\"ע שהזמן גרמא נשים פטורות<sup data-n=\"3360\">73</sup> מפני שהם משועבדי' לבעלה<sup data-n=\"3361\">74</sup> תחת הזמן כמ\"ש במ\"א, אבל לע\"ל כשיתגלה בחי' מו\"ס (שעכשיו היא לא אתפתחא כמ\"ש באד\"ר נשא דקך\"ח ב' ובבה\"ז שם<sup data-n=\"3362\">75</sup>) שהוא בחי' טוב טעם ודעת<sup data-n=\"3363\">76</sup> אז יהי' להכלה קול גדול ולא יסף<sup data-n=\"3364\">77</sup>, ויהי' שמו\"ע בקול רם כמ\"ש בת\"א ס\"פ ויגש<sup data-n=\"3365\">78</sup>, והיינו כי המל' יהי' עיקר אחע\"ב וכנודע שבע\"ס דאו\"ח המל' הוא כתר<sup data-n=\"3366\">79</sup> ויסוד המשפיע עכשיו למל' יהי' בחי' חכמה.",[["3352","65","<b>בלק\"ת בשה\"ש סד\"ה קול דודי</b>: טו, ג."],["3351","64","<b>ועמ\"ש בלק\"ת בשה\"ש . . דודי . . והאמהות</b>: בלקו\"ת שם: (ועמ\"ש . . דודי כו' . . והאמהות)."],["3353","66","<b>יהיו בחי' תחלה בחי'</b>: בלקו\"ת שם: יהיה תחלה בבחי'."],["3354","67","<b>(ואכלתם . . ע\"ב)</b>: הכוונה שהבא בסמוך הוא ע\"פ הלקו\"ת (שה\"ש).\nציון זה נרשם בפנים המאמר ועה\"ג כאן באה הוראה להמעתיק: ”משבשח\"ע אצ\"ל\" מה שבין שני חצאי עיגול אין צריך להעתיק. ראה לעיל הערה 53."],["3355","68","<b>כעככ\"ח דמ\"ח ע\"ב</b>: בלקו\"ת שה\"ש."],["3356","69","<b>צלותא בחשאי</b>: זהר ח\"ש קלב, א. ויגש רי, א. תרומה קלח, ב. ועוד. ראה מאמרי אדה\"א בראשית ע' צט. וש\"נ. לעיל מאמר ד\"ה וידעת היום על יד הערה 110 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301670254\" data-slug=\"likkutei-sichot\" data-id=\"1301670254\">לקו\"ש ויגש כרך לה ע' 192</a> ואילך."],["3357","70","<b>קול באשה ערוה</b>: ברכות כד, א. שו\"ע אדה\"ז הל' ק\"ש סע\"ה, ס\"ו. ראה גם סה\"מ תרל\"ד ע' יז ואילך [נדפס גם בדרושי חתונה שלו ע' פב ואילך]."],["3358","71","<b>ובד\"ה מהרה ישמע</b>: ראה סה\"מ תרל\"ב ח\"ב ע' שנט ואילך [נדפס גם בדרושי חתונה שלו ע' פא ואילך]. ע' תקנ ואילך. תרל\"ד ע' כג ואילך [נדפס שם ע' פח ואילך]."],["3359","72","<b>אשה טפילה לבעלה</b>: כלי יקר נח יא, לא."],["3360","73","<b>מ\"ע שהזמן גרמא נשים פטורות</b>: קדושין כט, א במשנה. ראה גם סה\"מ שבהערה הבאה. וש\"נ."],["3361","74","<b>משועבדי' לבעלה</b>: ראה אבודרהם סדר תפלות של חול (ירושלים תשכ\"ג ע' כה ד\"ה כל. ובהערת המו\"ל שם תה, א). ראה גם סה\"מ תרל\"ח ע' קנח. וש\"נ."],["3362","75","<b>ובבה\"ז שם</b>: נשא פח, א ואילך."],["3363","76","<b>טוב טעם ודעת</b>: לשון הכתוב תהלים קיט, סו."],["3364","77","<b>קול גדול ולא יסף</b>: לשון הכתוב ואתחנן ה, יט."],["3365","78","<b>שמו\"ע . . בת\"א ס\"פ ויגש</b>: מה, ב. ראה גם פיסקא הבאה. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 76. לקמן (בחלק ההנחות) הנחה ד\"ה שוש תשיש הא' על יד הערה 53. הב' על יד הערה 47. לקו\"ת כאן. מאמרי אדה\"א דרושי חתונה ח\"א ע' קסד. לקו\"ש ויגש שם ס\"ע 196 ואילך."],["3366","79","<b>שבע\"ס דאו\"ח המל' הוא כתר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381210\" data-slug=\"likkutei-torah\" data-id=\"4001381210\">לקו\"ת שה\"ש כ, ב</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550715\" data-slug=\"torat-chaim\" data-id=\"2300550715\">תו\"ח תצוה ח\"ב שעה, ב</a>. וש\"נ."]]],[2001910343,"<b>ושרש</b> הענין דכל מעשה המצות הוא בחי' בירורים<sup data-n=\"3367\">80</sup> לברר בעשי' בחי' הטוב דנוגה, אשר בחכ' דוקא אתברירו<sup data-n=\"3368\">81</sup>, וכ\"ז שלא נתברר בשלימות היינו גמר כל הבירורים, מו\"ס שהוא בחי' פנימיות החכ' שבכתר לא איתפתחא בנתיבות עד שיגמרו גמר כל הבירורים דנוגה דעשי' אז יתגלה בחי' פנימיות הכתר והגילוי יהי' למטה במל', וזהו אחע\"ב שבה דוקא יתגלה אור טעם ודעת הגנוז ונעלם שלמעלה גם מבחי' ל\"ב נת\"ח<sup data-n=\"3369\">82</sup> דבחי' ח\"ע דאצי' לפי שמה שבחכ' אתברירו שרשו מן מו\"ס הנעלם ששם עיקר הבירור, ובכלל זהו מה שמ\"ה מברר ב\"ן<sup data-n=\"3371\">84</sup> ולאחר הבירור עולה ב\"ן<sup data-n=\"3370\">83</sup> דמל'<sup data-n=\"3373\">86</sup> בס\"ג<sup data-n=\"3372\">85</sup> שלמעלה מבחי' מ\"ה<sup data-n=\"3374\">87</sup> (פי' ענין העלי' היינו שיתגלה בחי' ס\"ג דתהו<sup data-n=\"3375\">88</sup> בש' ב\"ן דמל' ולכן יהי' הגילוי למטה דוקא), ואז יהי' במל' גילוי בחי' מו\"ס דלא אתפתחא עכשיו, ויהי' גילוי בחי' טעמי תורה ישקני מנשיקות פיהו<sup data-n=\"3376\">89</sup>, ואז יהי' המל' בבחי' קול גדול ולא יסף שמונה עשרה בקול רם כו', וזהו שיצא מ\"ח הוא בחי' חכ\"ע מירושלם דוקא כו', ולפמשי\"ת לקמן עליית ש' ב\"ן הוא בכתר דתהו<sup data-n=\"3377\">90</sup> ולכן יצאו מ\"ח מירושלם מעהמ\"צ כתר מל' חצים אל הים הקדמוני הוא בחי' חכ' שבכתר<sup data-n=\"3378\">*91</sup>, היינו בחי' מו\"ס כו', וכ\"כ באמרי בינה סוף שער הק\"ש<sup data-n=\"3379\">91</sup>, ולאשר כי להאבות הטעימן הקב\"ה מעין עוה\"ב<sup data-n=\"3380\">92</sup> כו' כנ\"ל לכן הי' אברהם טפל לשרה",[["3367","80","<b>דכל מעשה המצות . . בירורים</b>: ראה ע\"ח שער הצלם שכ\"ו, פ\"א. שער קליפת נוגה שמ\"ט פ\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380461\" data-slug=\"likkutei-torah\" data-id=\"4001380461\">לקו\"ת שלח לז, ב</a> ואילך. מאמרי אדה\"ז על ענינים ע' רכה ואילך. ע' רנג ואילך. ע' רסו. מאמרי אדה\"א דברים ח\"ד ס\"ע א'תסו ואילך ובהנסמן בהנ\"ל."],["3368","81","<b>בחכ' . . אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר היכלות פקודי רנד, סע\"ב. ע\"ח שער דרושי נקודות ש\"ח, פ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550161\" data-slug=\"torat-chaim\" data-id=\"2300550161\">תו\"ח תשא ח\"ב שפד, ד</a> ואילך."],["3369","82","<b>ל\"ב נת\"ח</b>: ס\"י פ\"א, מ\"א. ראה גם הנסמן במאמרי אדה\"א בראשית ע' ג. ונמנו בפרטיות בהקדמת הראב\"ד לס\"י י, סע\"א ואילך — ירושלים תשכ\"ב. פרדס שער הנתיבות שי\"ב, פ\"ב ואילך.\nנרשם לעיל וכן הוא בס\"י הנדפס: ”הקדמת הראב\"ד\" — אבל בפרדס שם מייחסו: ”ר' יוסף הארוך בפי' ס\"י שחבר\". ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקפט בהערה. שם הגדולים מערכת ספרים — קבלה קו\"א."],["3371","84","<b>שמ\"ה מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["3370","83","<b>שמ\"ה . . ב\"ן . . בס\"ג</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 61 ואילך."],["3373","86","<b>ב\"ן דמל'</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג. שעה\"י קמה, א הערה 14."],["3372","85","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380280\" data-slug=\"likkutei-torah\" data-id=\"4001380280\">עולה ב</a>\"ן . . בס\"ג</b>: ראה לקו\"ת בחוקותי מז, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540240\" data-slug=\"torat-chaim\" data-id=\"2300540240\">תו\"ח וארא ח\"א ע, ג</a>. וש\"נ."],["3374","87","<b>בס\"ג שלמעלה מבחי' מ\"ה</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. שער אנ\"ך שי\"ט, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"א ע' ה הערה ד\"ה: שם."],["3375","88","<b>ס\"ג דתהו</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> ובהערה 2."],["3376","89","<b>טעמי תורה ישקני מנשיקות פיהו</b>: שה\"ש א, ב וברש\"י שם. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר משה ובהערה 70."],["3377","90","<b>ולפמשי\"ת לקמן עליית ש' ב\"ן הוא בכתר דתהו</b>: ראה גם מאמרי אדה\"ז תקס\"ז ע' שיז."],["3378","*91","<b>הים הקדמוני . . חכ' שבכתר</b>: ראה אוה\"ת ואתחנן ע' רמח וע' רעו. לקמן (בחלק ההנחות) הנחה ד\"ה שוש תשיש הא' על יד הערה 62. הב' על יד הערה 43."],["3379","91","<b>באמרי בינה סוף שער הק\"ש</b>: פב, ג."],["3380","92","<b>להאבות הטעימן . . עוה\"ב</b>: ב\"ב טז, סע\"ב ואילך. ראה גם תו\"ח ח\"ש קכא, א ובהערה 10. שה\"א נד, ב ובהערה 33. לקמן (בחלק ההנחות) הנחה ד\"ה שוש תשיש הא' על יד הערה 30 ואילך. הב' על יד הערה 49 ואילך."]]],[2001910344,"בנביאות<sup data-n=\"3381\">93</sup> (ד\"ה קול דודי פ\"ד דט\"ו ע\"ג)<sup data-n=\"3382\">94</sup> וכמ\"ש כל אשר תאמר אליך שרה שמע בקולה<sup data-n=\"3383\">95</sup> שהי' אברהם צריך לקבל ממנה, וכן ברבקה נא' טבת מראה מאד<sup data-n=\"3384\">96</sup> פי' מאד בלי גבול<sup data-n=\"3385\">97</sup>, ותרד העיינה ותמלא כדה<sup data-n=\"3386\">98</sup>, שבחי' כדה הוא כד ספרין<sup data-n=\"3388\">100</sup> דאורייתא<sup data-n=\"3387\">99</sup> בחי' חכ' עילאה הוא ירידה נגדה כמ\"ש בלק\"ת ד\"ה קול דודי פ\"ד<sup data-n=\"3389\">101</sup>, וכן כל האמהות, והיינו הגם כי בודאי היו בבחי' נוק' שקיבלו מהאבות שהיו בבחי' דכר ונוק' משפיע ומקבל מ\"מ הי' אברהם טפל לשרה ע\"ד ומעין שיהי' לע\"ל שיהי' נקבה תסובב גבר<sup data-n=\"3390\">102</sup>, ואחעט\"ב כו', עד\"ז גם עכשיו קיבלו האבות מהאמהות. ושרש הענין כי אברהם ושרה, יצחק ורבקה, יעקב ורחל<sup data-n=\"3393\">105</sup> הם מ\"ה<sup data-n=\"3391\">103</sup> וב\"ן<sup data-n=\"3392\">104</sup>, שבכל עולם האבות הם מ\"ה והאמהות הם ב\"ן<sup data-n=\"3394\">106</sup> כמ\"ש בביאור דקול דודי לשון אאזמ\"ו ז\"ל<sup data-n=\"3395\">107</sup>, ומצד בחי' התיקון מ\"ה מברר ב\"ן ולכן היו האבות משפיעים והאמהות מקבלי',\n\nוי\"ל<sup data-n=\"8590\">כב</sup> שז\"ע ואת הנפש אשר עשו בחרן<sup data-n=\"8591\">כג</sup> שבבחי' זו קיבל אברהם משרה מבחי' האור חוזר שנעשו ע\"י הבירורי' שעשו בחרן עשו לשון רבים<sup data-n=\"8592\">כד</sup>, ששרה קיבלה מאברם ע\"ד משפיע ומקבל שבתיקון ואברם קיבל משרה מבחי' הבירורים דתהו ע\"ד בחי' האו\"ח שיהי' לע\"ל, וכן יצחק ורבקה כמ\"ש ויביאה כו' האוהלה שרה אמו<sup data-n=\"8593\">כה</sup> שהי' ג\"כ ע\"ד בחי' אברהם ושרה כו', וכן יעקב עשה את כל הכבוד<sup data-n=\"8594\">כו</sup> ע\"י בחי' לאה ורחל בבית לבן כמ\"ש במ\"א.\nוגם י\"ל שענין הטעימן מעין עוה\"ב ע\"ד שנת\"ל, כי עתידים צדיקים שיקראו על שמו של הקב\"ה כנ\"ל שפי' רש\"י שיהי' שמם הוי', ולהאבות שהטעימן מעין עוה\"ב היינו מה שכולם נק' ישראל שז\"ע כי שרית כנ\"ל ולכן כל עדת בנ\"י יוכלו לקבל מבחי' ש' הוי' שקדוש ומובדל מגדר עולמות להיות בבחי' וכל בניך למודי הוי'<sup data-n=\"8595\">כז</sup> שארז\"ל א\"ת בניך אלא בוניך<sup data-n=\"8596\">כח</sup> שפי' בוניך זהו ע\"י התומ\"צ כמ\"ש בלק\"ת בד\"ה וכל בניך<sup data-n=\"8597\">כט</sup>, וזהו והי' הנשאר בציון כו' בירושלים וכמשית\"ל בס\"ד ענין ציון וירושלם, קדוש יאמר לו ע\"י שמקבל בחי' מ\"ח שיוצא מירושלם כמשי\"ת<sup data-n=\"8598\">ל</sup>.\nקדושים<sup data-n=\"8599\">לא</sup> תהיו כמו שפי' רש\"י<sup data-n=\"8600\">לב</sup> היו פרושים מן העריות ומן העבירה, ונודע כי מצות ל\"ת תלוים בי\"ה<sup data-n=\"8601\">לג</sup> של ש' הוי' כמ\"ש בת\"ז שמי עם י\"ה שס\"ה<sup data-n=\"8602\">לד</sup>, וז\"ע המשכת בחי' קדוש כמ\"ש בלק\"ת ד\"ה כי ההרים ימושו פ\"ב ד\"מ ע\"ג<sup data-n=\"8603\">לה</sup> שג\"פ קדוש הוא המשכה מבחי' י\"ה.",[["3381","93","<b>אברהם טפל לשרה בנביאות</b>: תנחומא ושמו\"ר ר\"פ שמות. ראה גם בסמוך הערות 94-95. סה\"מ תר\"ם ח\"א ע' קפא הערה 917."],["3382","94","<b>(ד\"ה קול דודי פ\"ד דט\"ו ע\"ג)</b>: לקו\"ת שה\"ש. הבא בסמוך בפנים הוא ע\"פ לשון לקו\"ת שם.\nציון זה נרשם בפנים המאמר ועה\"ג כאן באה הוראה להמעתיק: ”משבח\"ע אצ\"ל\" מה שבחצאי עיגול אין צריך להעתיק. וע\"פ הוראה זו מובן מה שבסמוך על יד הערה 101 מציין עוה\"פ ללקו\"ת זה. ולכאורה הי' משנה אחרונה בזה — ראה לעיל הערה 53."],["3383","95","<b>כל אשר תאמר. . בקולה</b>: וירא כא, יב. מדרש אגדה ורש\"י שם."],["3384","96","<b>טבת מראה מאד</b>: ח\"ש כד, טז."],["3385","97","<b>מאד בלי גבול</b>: ראה אגה\"ק סי\"ז. סה\"מ תר\"ם ח\"א ע' תכט. וש\"נ."],["3386","98","<b>ותרד העיינה ותמלא כדה</b>: ח\"ש שם."],["3388","100","<b>כד ספרין דאורייתא</b>: ראה שמו\"ר פכ\"ד, ה. שהש\"ר פ\"ד, יא. תנחומא תשא טז. ילקוט שמעוני תשא לא, יח (רמז שצא). זהר אד\"ז האזינו רצג, ב. ת\"ז בהקדמה ותכ\"א שם. תקונא שתיתאה קמה, א."],["3387","99","<b>כדה הוא כד ספרין דאורייתא</b>: ראה ת\"ז בהקדמה יד, א. תכ\"א מו, ב. מז, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370084\" data-slug=\"torah-or\" data-id=\"3901370084\">תו\"א תולדות יז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381110\" data-slug=\"likkutei-torah\" data-id=\"4001381110\">לקו\"ת כאן טו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540697\" data-slug=\"torat-chaim\" data-id=\"2300540697\">ברכה צה, ד</a>. מאמרי אדה\"א דברים ח\"א ע' רכו. וש\"נ. תו\"ח וארא ח\"א פ, א. וש\"נ. לעיל מאמר ד\"ה להבין וכו' זאת תהי' תורת המצורע על יד הערה 128. מאמר ד\"ה להבין וכו' בענין הציץ על יד הערה 177. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 81. (בחלק הנחות) הנחה ד\"ה שוש תשיש הא' על יד הערה 39."],["3389","101","<b>בלק\"ת ד\"ה קול דודי פ\"ד</b>: שה\"ש טו, ג."],["3390","102","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["3393","105","<b>יעקב ורחל . . מ\"ה וב\"ן</b>: ראה גם (בנוסף להערה 107) תו\"ח לך שם. ויצא קעד, א."],["3391","103","<b>אברהם ושרה . . הם מ\"ה וב\"ן</b>: ראה גם (בנוסף להערה 107) מקדש מלך לזהר וירא קג, א (ס\"ע עז). מאמרי אדה\"ז תקע\"א ע' קע. מאמרי אדה\"א דברים ח\"ב ע' תרצז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670403\" data-slug=\"torat-chaim\" data-id=\"2300670403\">תו\"ח לך פו, ד</a> ובהערה 16 [ושם: בשם הזהר ובשם הלקו\"ת]. שה\"א נד, ב ובהערה 32."],["3392","104","<b>יצחק ורבקה . . מ\"ה וב\"ן</b>: ראה גם (בנוסף להערה 107) תו\"ח לך שם ובהערה 13 [ושם: בשם הלקו\"ת]. לקמן (בחלק ההנחות) הנחה ד\"ה שוש תשיש הא' על יד הערה 34. הב' על יד הערה 52. שני המאורות לרי\"א מהאמעל ע' 140."],["3394","106","<b>והאמהות הם ב\"ן</b>: ראה גם (בנוסף להנ\"ל) תו\"ח ח\"ש קלז, ד ובהערה 10."],["3395","107","<b>בביאור דקול דודי . . ז\"ל</b>: מאמרי אדה\"ז תקס\"ט ע' סז.\n\n<b>כב</b> ) <b>וי\"ל</b>: פיסקא זו ולשלאחרי' נרשמו בפנים, ועה\"ג שם (בהפסק קו מלמעלמ\"ט) באה הוראה להמעתיק: ”מן וי\"ל עד כמשי\"ת בשיטה בחי' להעתיק למטה\".\n\n<b>כג</b> ) <b>ואת הנפש אשר עשו בחרן</b>: לך יב, ה.\n\n<b>כד</b> ) <b>עשו ל' רבים</b>: ראה ב\"ר פל\"ט, יד הובא ברש\"י לך שם.\n\n<b>כה</b> ) <b>ויביאה . . שרה אמו</b>: ח\"ש כד, סז.\n\n<b>כו</b> ) <b>עשה את כל הכבוד</b>: ויצא לא, א.\n\n<b>כז</b> ) <b>וכל בניך למודי הוי'</b>: ישעי' נד, יג.\n\n<b>כח</b> ) <b>א\"ת בניך אלא בוניך</b>: ברכות סד, א.\n\n<b>כט</b> ) <b>בלק\"ת בד\"ה וכל בניך</b>: פ' ראה כט, ג ואילך.\n\n<b>ל</b> ) <b>וכמשית\"ל . . כמשי\"ת</b>: ראה לקמן פ\"ג.\n\n<b>לא</b> ) <b>קדושים</b>: נרשם בצד הימני של העמוד מלמעלמ\"ט ללא ציון מקומו בפנים.\n\n<b>לב</b> ) <b>קדושים תהיו . . שפי' רש\"י</b>: קדושים יט, ב.\n\n<b>לג</b> ) <b>מצות ל\"ת תלוים בי\"ה</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 45.\n\n<b>לד</b> ) <b>שמי עם י\"ה שס\"ה</b>: ראה שמות ג, טו. ת\"ז בהקדמה ד, סע\"ב. ה, א. סה\"מ תר\"ם ח\"א ע' תז. וש\"נ.\n\n<b>לה</b> ) <b>בלק\"ת . . ד\"מ ע\"ג</b>: תצא."]]],[2001910345,"ומצד שהטעימן מעין עוה\"ב שיתעלה ב\"ן להיות משפיע כתר דאו\"ח לכן הי' אברהם טפל לשרה וכן כולם, ולכן היו האמהות עקרות<sup data-n=\"3396\">108</sup> כי בשרשן הם בבחי' דכר ומשפיע כו' וכן יהי' לע\"ל בגמר הבירורים כו'.\nג) <b>והענין</b> הוא דהנה יעקב בנדרו א' ושבתי בשלום כו' והי' הוי' לי לאלקי'<sup data-n=\"3397\">109</sup>, וארז\"ל במד\"ר במקומו פ\"ע נטל הקב\"ה<sup data-n=\"3398\">110</sup> שיחתן של אבות ועשאן",[["3396","108","<b>האמהות עקרות</b>: ראה ב\"ר פמ\"ה, ד. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381195\" data-slug=\"likkutei-torah\" data-id=\"4001381195\">לקו\"ת שה\"ש טז, ג</a>."],["3397","109","<b>ושבתי בשלום . . לי לאלקי'</b>: ויצא כח, כא."],["3398","110","<b>במד\"ר . . פ\"ע נטל הקב\"ה</b>: ראה שם סימן ו.\nמובא גם ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380657\" data-slug=\"likkutei-torah\" data-id=\"4001380657\">לקו\"ת מטות פג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380839\" data-slug=\"likkutei-torah\" data-id=\"4001380839\">פ' ראה ל, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380961\" data-slug=\"likkutei-torah\" data-id=\"4001380961\">ר\"ה ס, ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480046\" data-slug=\"or-hatorah-hb\" data-id=\"8316480046\">אוה\"ת ויצא כרך ה ע' תתנד</a>. ישעי' כרך ב ע' תשסב [ושם: ע\"פ והי' ה' לי לאלקים — ראה גם בסה\"מ תר\"ם דבסמוך ע' תקנ הערה 4]. סה\"מ תרכ\"ו ע' פא. תר\"ם ח\"א ע' תקנ־ ע' תתקד־ ע' תתקיח."]]],[2001910346,"מפתח לגאולתן של בנים, שכל<sup data-n=\"3399\">111</sup> הטובות<sup data-n=\"3400\">112</sup> וכל הנחמות<sup data-n=\"3401\">113</sup> הוא בלשון והי'<sup data-n=\"3402\">114</sup>, והי' ביום ההוא יצאו מ\"ח מירושלים (זכרי' י\"ד ח'), והי' ביום ההוא יוסיף ה' שנית ידו<sup data-n=\"3403\">115</sup> (ישעי' י\"א י\"א), והי' ביום ההוא יטפו ההרים עסיס (יואל ד' י\"ח), והי' ביום ההוא יתקע בשופר גדול (ישעי' ך\"ז י\"ג), וזהו שארז\"ל במד\"ר בכ\"ד<sup data-n=\"3405\">117</sup> שאין והי' אלא לשון שמחה, ע' בפ' לך דמ\"ב<sup data-n=\"3406\">118</sup> ור\"פ שמיני<sup data-n=\"3407\">119</sup> ובהתחלת<sup data-n=\"3408\">120</sup> אסתר<sup data-n=\"3404\">116</sup>, ובפ' נשא ע\"פ ויהי המקריב דרנ\"ב ע\"ב<sup data-n=\"3410\">122</sup>, וברות ע\"פ ויהי בימי סוף ההקדמה<sup data-n=\"3411\">123</sup> דמ\"א<sup data-n=\"3409\">121</sup> מביא ג\"כ פסוק והי' הנשאר בציון, (והי' הנשאר בישעי' פ\"ה דפ\"ז ע\"ב)<sup data-n=\"3412\">124</sup>, א\"כ למדנו מזה דבחי' והי' הנשאר בציון נמשך מבחי' והי' הוי' לי לאלקים, ומבואר הפי' בת\"א ר\"פ ויצא סד\"ה ושבתי בשלום<sup data-n=\"3413\">125</sup> כי הנה שמש ומגן ה' אלקים<sup data-n=\"3414\">126</sup> שהמגן הוא נרתק כו' ומסתיר על אור השמש, כמ\"כ ש' אלקים נרתק לש' הוי' מכסה ומסתיר להיות נבראים בע\"ג, אך לע\"ל שיאיר אוא\"ס ב\"ה שלמעלה מבחי' ש' הוי', אזי ש' הוי' יהי' בבחי' אלקים, והיינו שיתגלה בחי' עצמיות אוא\"ס ע\"י ש' הוי' כדרך שעכשיו ההמשכה מש' הוי' ע\"י ש' אלקים, וזהו ושבתי בשלום אל בית אבי היינו אחר הבירורי' שעשה בבית לבן שעם לבן גרתי ותרי\"ג מצות<sup data-n=\"3416\">128</sup> שמרתי<sup data-n=\"3415\">127</sup>,",[["3399","111","<b>בנים שכל</b>: בב\"ר שם: בנים . . כל."],["3400","112","<b>הטובות</b>: וכ\"ה גם בסה\"מ תר\"ם ח\"א ע' תקנ. בב\"ר שם: טובות."],["3401","113","<b>וכל הנחמות</b>: בב\"ר שם: וברכות ונחמות. וכ\"ה גם בלקו\"ת מטות שם."],["3402","114","<b>הוא בלשון והי'</b>: בב\"ר שם: שאני נותן לבניך איני נותן אלא בלשון הזה שנאמר. וכ\"ה גם בלקו\"ת מטות שם."],["3403","115","<b>ידו</b>: ב\"ר שם: ידו לקנות את שאר עמו."],["3405","117","<b>בכ\"ד</b>: שם: בכמה דוכתי."],["3406","118","<b>בפ' לך דמ\"ב</b>: במהדורת אמשטרדם ת\"א הוא דמ\"ו, ב . בלקו\"ת שם: בסדר לך לך פמ\"ב — ראה שם סימן ג."],["3407","119","<b>ור\"פ שמיני</b>: פי\"א, ז."],["3408","120","<b>ובהתחלת אסתר</b>: בלקו\"ת שם: ובתחלת רות [המובא בסמוך בפנים — ראה בסמוך הערה 123] ובתחלת אסתר — פתיחתא סימן יא."],["3404","116","<b>וזהו שארז\"ל . . אסתר</b>: השווה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380839\" data-slug=\"likkutei-torah\" data-id=\"4001380839\">לקו\"ת פ' ראה ל, ד</a>."],["3410","122","<b>ובפ' נשא . . דרנ\"ב ע\"ב</b>: במהדורת אמשטרדם ת\"א. בדפוסים הנפוצים פי\"ג, ה."],["3411","123","<b>וברות ע\"פ . . ההקדמה דמ\"א</b>: פתיחתא סימן ז [הטעם שנרשם ציון זה כאן (ראה לעיל הערה 120) לכאורה הוא מפני שבשניהם הובא הכתוב והי' הנשאר]."],["3409","121","<b>ובפ' נשא . . דמ\"א</b>: השווה אוה\"ת ישעי' כרך ב ע' תשסב."],["3412","124","<b>(והי' . . ע\"ב)</b>: לע\"ע לא נתברר לאיזה מאמר הכוונה. ואולי הכוונה לבוך 1133 סו, ב — נדפס באוה\"ת ישעי' כרך ב ע' תשסב פ\"ה. ולכאורה הכוונה בהציון שלהנרשם לעיל או להבא להלן עיין שם.\nציון זה נרשם בפנים המאמר ועה\"ג כאן באה הוראה להמעתיק: ”משבשח\"ע אצ\"ל\" מה שבין שני חצאי עיגול אין צריך להעתיק. ראה גם לעיל הערה 53."],["3413","125","<b>בת\"א . . ושבתי בשלום</b>: כא, ד. הבא לקמן בפנים הוא ע\"פ לשון התו\"א."],["3414","126","<b>שמש ומגן ה' אלקים</b>: תהלים פד, יב."],["3416","128","<b>ותרי\"ג מצות</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה קדש ישראל לה' הערה 131."],["3415","127","<b>שעם לבן גרתי . . שמרתי</b>: וישלח לב, ה וברש\"י שם."]]],[2001910347,"וכל הבירורי' שבירר שם שז\"ע שהטעימן מעין עוה\"ב כנ\"ל וז\"ע ושבתי כו' בית אבי כמו שלעתיד יאמר ליצחק דוקא כי אתה אבינו<sup data-n=\"3417\">129</sup> אז והי' הוי' לי כו', ולכן בחזירתו כשנאבק עם המלאך נק' ישראל ע\"ש כי שרית שז\"ע בחי' גילוי ש' הוי' וכנ\"ל, וע' בלק\"ת בפ' שלח בד\"ה אני ה' אלקי' דפ' ציצית דרוש השני פ\"ד דמ\"ט ע\"ב שמ\"ש ב\"פ לא יעקב יאמר כו' כ\"א ישראל שזהו נגד ב' שמות הוי' כו'. ועפ\"ז יובן מה שבדברי המלאך נא' הטעם כי שרית כו', ובדברי הקב\"ה לא נא' כי שרית, והיינו מפני כי דברי המלאך זהו גילוי ש' הוי' דמ\"ת שזהו ע\"י כי שרית עם אלקי' בכדי שיהי' גילוי ש' הוי' וכנ\"ל, אך מה שאמר הקב\"ה כ\"א ישראל יהי' שמך זהו בחי' ש' הוי' דלעילא שיתגלה לע\"ל שזהו משנ\"ת לעיל שיהי' הגילוי מלמעלה מש' הוי' ע\"י בחי' ש' הוי' שהוא כאלקים דעכשיו יחשב, אמנם באמת זהו ש' הוי' לכן אינו שייך לשון כי שרית שזהו על ש' אלקים ולא על ש' הוי' כו' כ\"א כתי' ויקרא שמו ישראל<sup data-n=\"3418\">130</sup> שי\"ל שזהו כמ\"ש גבי ב' שמות הוי' ויקרא ה' ה'<sup data-n=\"3419\">131</sup>, וכנ\"ל<sup data-n=\"3420\">132</sup> ששם ישראל ענינו כמו ש' הוי' כבי' כו'. ונטל הקב\"ה שיחתן של אבות ועשאן מפתח כו' שכל הטובות והנחמות הם בלשון והיה והי' ביום ההוא יצאו מ\"ח מירושלם, והי' הנשאר בציון פי' ציון הוא בחי' תורה כמ\"ש כי מציון תצא תורה<sup data-n=\"3421\">133</sup>, וירושלם הוא בחי' מעשה המצות שעז\"נ והי' ביום ההוא יצאו מ\"ח מירושלם כמ\"ש בד\"ה ושננתם קרוב לסופו פי\"א דתצ\"ח ע\"ב<sup data-n=\"3422\">134</sup>, שעי\"ז יאמרו המלאכים לפניהם קדוש, והענין הוא דהנה תיבת והי' הוא צירוף אותיות ש' הוי'<sup data-n=\"3423\">135</sup>, רק שאותיות ו\"ה הם קודמים לאותיות י\"ה (ואותיות וה הי' מורה אצלם על שמחה כמ\"ש במד\"ר באיכה<sup data-n=\"3424\">136</sup> ע\"פ היו צריה<sup data-n=\"3425\">137</sup> לא אמרית וי אלא וה אמרית, והיינו שז\"ע השמחה שיתגלה לעתיד מה שישמח הוי' במעשיו<sup data-n=\"3426\">138</sup> ע\"י בחי' הבירורים שנתבררו בעשייה דוקא כמ\"ש בלק\"ת בד\"ה הוי' לי בעוזרי<sup data-n=\"3427\">139</sup>), והיינו כנ\"ל בפי' והי' הוי' לי לאלקי', שלעתיד יהי' הגילוי מלמעלה מש' הוי' רק שיהי' הגילוי ע\"י בחי' ש' הוי' כמו שעכשיו הוא הגילוי מש' הוי' ע\"י ש' אלקים, וע\"ז מורה שבתיבת והיה שקאי לע\"ל אותיות וה קודמים לאותיות יה, והיינו כי הגם שי\"ה דש' הוי' הוא בחי' או\"א שהם המולידים בחי' ו\"ה",[["3417","129","<b>ליצחק . . כי אתה אבינו</b>: שבת פט, ב. ישעי' סג, טז."],["3418","130","<b>ויקרא שמו ישראל</b>: וישלח לה, י [ושם את שמו — ראה גם בחיי שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381216\" data-slug=\"likkutei-torah\" data-id=\"4001381216\">לקו\"ת שה\"ש כא, רע\"ד</a>. מאמרי אדה\"א נ\"ך ע' רנו]."],["3419","131","<b>ויקרא ה' ה'</b>: תשא לד, ו. ראה גם לעיל מאמר ד\"ה מגילה נקראת ובהערה 232."],["3420","132","<b>וכנ\"ל</b>: פ\"א."],["3421","133","<b>כי מציון תצא תורה</b>: ישעי' ב, ג. מיכה ד, ב. ראה גם לקמן מאמר ד\"ה והנותר בירושלם על יד הערה 6."],["3422","134","<b>בד\"ה ושננתם . . ע\"ב</b>: לע\"ע לא נתברר לאיזה בוך כוונתו. ראה גם לקמן מאמר ד\"ה והנותר בירושלם בתחילתו. מאמרי אדה\"ז תקס\"ז ע' שי. אוה\"ת ואתחנן (ע' רמח) ע' רעו."],["3423","135","<b>והי' הוא צירוף . . הוי'</b>: ראה ת\"ז בהקדמה ט, ב. שערי אורה [לרי\"ג] שער ה (סה, ב). פרדס שער פרטי השמות שכ\"א, פי\"ד-פט\"ו. ע\"ח שער השמות שמ\"ד, פ\"ז מ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380839\" data-slug=\"likkutei-torah\" data-id=\"4001380839\">לקו\"ת פ' ראה ל, ד</a>. סה\"מ תרל\"ט ח\"א ע' ח בשם המהרש\"ל."],["3424","136","<b>במד\"ר באיכה</b>: פ\"א, לא [ושם: אמרתי . . [במהדורת אמשטרדם ת\"א ווי] . . אמרי — ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380839\" data-slug=\"likkutei-torah\" data-id=\"4001380839\">לקו\"ת שם ל, סע\"ד</a> כבפנים. המשך תער\"ב ח\"א ס\"ע קכט: אמרית . . אמרי]."],["3425","137","<b>היו צריה</b>: איכה א, ה."],["3426","138","<b>שישמח הוי' במעשיו</b>: תהלים קד, לא."],["3427","139","<b>בלק\"ת . . בעוזרי</b>: שמע\"צ פט, א ואילך."]]],[2001910348,"בן ובת<sup data-n=\"3428\">140</sup>, עכ\"ז הנה בחי' ו\"ה יש להם שרש יותר גבוה מבחי' י\"ה, והיינו כמ\"ש באד\"ז או\"א ממו\"ס נפקא<sup data-n=\"3429\">141</sup> וז\"א בעתיקא אחיד ותליא<sup data-n=\"3430\">142</sup> ופי' בת\"א פ' יתרו בד\"ה להבין ביאור האבות<sup data-n=\"3432\">144</sup> הן הן המרכבה דקך\"א ע\"ג<sup data-n=\"3431\">143</sup> שהשכל נולד<sup data-n=\"3433\">145</sup> מן המשכיל שלמעלה מן השכל ששם לא נודע גילוי השכל וטעמו של דבר כלל, אבל מ\"מ הוא נק' משכיל מקור השכל, אבל ז\"א בעתיקא אחיד ותליא שהמדות נלקחו ממקום עליון יותר, כי הגם שהמדות נולדו ונתגלו מן השכל ולפי שכלו כך תהיינה מדותיו ובינה נק' אם הבנים<sup data-n=\"3435\">147</sup>, והחכמה אב<sup data-n=\"3434\">146</sup>, מ\"מ אין זה אלא שהם גורמים להולדת והתהוות המדות שיצאו מהעלם<sup data-n=\"3436\">148</sup> אל הגילוי, אבל עיקר המדות בשרשן נלקחו ממקום עליון יותר כו' ולאחר שמתבררי' ע\"י החכמה אזי<sup data-n=\"3437\">149</sup> יפה כח הבן מכח האב<sup data-n=\"3438\">150</sup> עכ\"ל ע\"ש. נמצא שז\"א שרשו מעתיקא שלמעלה מחו\"ב שממוחא סתימאה נפקי היינו מה שאו\"א במזלא אתכלילן<sup data-n=\"3439\">151</sup> שאבא מקבל ממזל ונוצר, ואימא מקבל ממזל ונקה<sup data-n=\"3440\">152</sup>, וז\"ע ממו\"ס נפקי ע\"י המזלות הנ\"ל, ולכן האבות הם בחי' חג\"ת<sup data-n=\"3441\">153</sup> הם המרכבה<sup data-n=\"3442\">154</sup> להגבי' בחי' כמראה אדם<sup data-n=\"3443\">155</sup>, והיינו גם בחי' או\"א לפי ששרשן גבוה יותר, וכמ\"ש במ\"א בענין בעבר הנהר ישבו אבותיכם<sup data-n=\"3444\">156</sup> שהנהר הוא בחי' נהר שיוצא מעדן<sup data-n=\"3445\">157</sup> שיובל שמו<sup data-n=\"3446\">158</sup> וחיים שמו<sup data-n=\"3447\">159</sup> שזהו בחי' חו\"ב<sup data-n=\"3448\">160</sup> ושרש האבות הם בעבר הנהר, טורי חשוכא<sup data-n=\"3449\">161</sup> מדות שבכתר, ומפני ששרשן גבוה יותר לכן ביכולתם להגביה חו\"ב כו' וכמ\"ש מזה בביאור שבפ' יתרו הנ\"ל, וז\"ע הוא\"ו שקודם לי\"ה,",[["3428","140","<b>שי\"ה . . או\"א . . ו\"ה בן ובת</b>: ראה ת\"ז תנ\"ו פט, ב."],["3429","141","<b>או\"א ממו\"ס נפקא</b>: ראה זהר אד\"ז האזינו רצב, א."],["3430","142","<b>וז\"א בעתיקא אחיד ותליא</b>: ראה זהר שם. סה\"מ תר\"ם ח\"א ע' קנב. וש\"נ."],["3432","144","<b>האבות</b>: שם: ענין האבות."],["3431","143","<b>בת\"א פ' יתרו . . דקך\"א ע\"ג</b>: מהדורת קאפוסט תקצ\"ז. ובמהדורת קה\"ת שם עג, א."],["3433","145","<b>שהשכל נולד</b>: שם: הנה השכל הוא נולד."],["3435","147","<b>ובינה נק' אם הבנים</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י הערה 82."],["3434","146","<b>ובינה נק' אם . . והחכמה אב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a>."],["3436","148","<b>מהעלם</b>: בתו\"א שם: מההעלם."],["3437","149","<b>ולאחר . . אזי</b>: ראה תו\"א שם."],["3438","150","<b>יפה כח הבן מכח האב</b>: ראה שבועות מח, סע\"א. סה\"מ תר\"ם ח\"ב ע' תרג. וש\"נ."],["3439","151","<b>שאו\"א במזלא אתכלילן</b>: ראה זהר אד\"ז האזינו רפט, ב. רצב, א."],["3440","152","<b>שאבא . . ונוצר . . ונקה</b>: ראה זהר אד\"ז האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקעד־ מאמרי אדה\"א קונטרסים ע' תקנז."],["3441","153","<b>האבות . . חג\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540325\" data-slug=\"torat-chaim\" data-id=\"2300540325\">תו\"ח וארא ח\"א סא, ד</a>. וש\"נ."],["3442","154","<b>האבות . . הם המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670263\" data-slug=\"torat-chaim\" data-id=\"2300670263\">תו\"ח נח מט, ד</a> ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["3443","155","<b>כמראה אדם</b>: יחזקאל א, כו."],["3444","156","<b>בעבר הנהר ישבו אבותיכם</b>: יהושע כד, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380278\" data-slug=\"likkutei-torah\" data-id=\"4001380278\">לקו\"ת בחוקותי מז, א</a>."],["3445","157","<b>נהר שיוצא מעדן</b>: בראשית ב, י."],["3446","158","<b>שיובל שמו</b>: ראה זהר יתרו פג, א. אחרי נח, א. וראה גם בכורות נה, ב. ויק\"ר ספכ\"ב."],["3447","159","<b>וחיים שמו</b>: ראה זהר אחרי שם. אוה\"ת ירמי' כרך א ע' שמה. סה\"מ תרל\"ח ע' תכג. וש\"נ."],["3448","160","<b>שיובל . . וחיים . . חו\"ב</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה שלש רגלים תחוג לי ובהערה 45."],["3449","161","<b>טורי חשוכא</b>: ראה זהר פינחס רמט, ב. ראה גם לקו\"ת בחוקותי שם. סה\"מ תרל\"ח ע' קצז. וש\"נ."]]],[2001910349,"וכמ\"כ יובן בענין בחי' ה' אחרונה שקדום ג\"כ לבחי' י\"ה דש' הוי' דהנה כתיב (שה\"ש ג' י\"א) בעטרה שעטרה לו אמו, שאין אמו עצמה היא העטרה רק שהיא מעטר לו העטרה, והעטרה בעצמה היא מבחי' הגבוה יותר מבחי' אמו, פי' אמו הוא בינה, והעטרה שאמו מעטרת לו היינו בחי' מל' דכתי' אשת חיל עטרת בעלה<sup data-n=\"3450\">162</sup> שבחי' המל' תהי' לע\"ל בחי' העטרה עצמה, וזהו רני ושמחי בת<sup data-n=\"3451\">163</sup> דוקא, ופי' חיל כי חיל עולה מספרו מ\"ח והיינו מ\"ח אתוון דיחודא דבשכמל\"ו<sup data-n=\"3452\">164</sup> שחרית וערבית, וע' בד\"ה ונקדשתי פ\"ג בלק\"ת פ' אמור<sup data-n=\"3453\">165</sup> שג' תיבות שם כבוד מל' הם כנגד ג' עולמות בי\"ע, שמבחי' בירורים אלו תהי' לע\"ל בחי' העטרה עצמה, ונמצא כי לע\"ל יהי' יתרון לבחי' ו\"ה על בחי' י\"ה, ולכן בוהיה שמורה על בחי' שמחה שישמח ה' במעשיו שהוא בחי' הבירורי' דעשי' דוקא כמ\"ש בד\"ה ה' לי בעוזרי וכנ\"ל, נא' ו\"ה קודם י\"ה, ולכן עתידים צדיקים היינו לפי' הרמ\"ק<sup data-n=\"3454\">166</sup> שנכללים בצדיק וצדק שיאמרו לפניהם קדוש לפי שבחי' ו\"ה יש להם קדימה לע\"ל על בחי' י\"ה, אמנם לפירושו דחוק לשון הגמ'<sup data-n=\"3455\">167</sup> שהלשון כדרך שאומרים לפני הקב\"ה אינו מתיישב, שהרי זהו עצמו האמירה לפני הקב\"ה רק שנשמת הצדיקים נכללים בצדיק וצדק שז\"ע לאשתאבא בגופא דמלכא<sup data-n=\"3456\">168</sup>. אך באמת יש לישב לשון הגמרא בטוב, והיינו כי עכשיו ענין אמירת ג\"פ קדוש<sup data-n=\"3457\">169</sup> פי' בלק\"ת פ' תצא בד\"ה כי ההרים ימושו פ\"ב דף מם ע\"ג שז\"ע ההמשכה מבחי' י\"ה בו\"ה, אמנם לע\"ל בגמר הבירורים הנשאר בציון תורה זהו בחי' וא\"ו דש' הוי'<sup data-n=\"3458\">170</sup> כמ\"ש הקל קול יעקב קלא בתראה מלא וא\"ו, שהוא בחי' תורה<sup data-n=\"3459\">171</sup> וע' בד\"ה וכל בניך בלק\"ת פ' ראה<sup data-n=\"3460\">172</sup>, והנותר בירושלם שהוא\n\nג\"פ<sup data-n=\"8604\">לו</sup> קדוש ז\"ע ההמשכה בחג\"ת, וזהו מ\"ש בביאור כי ההרים המשכה בג' קוין חח\"ן, בג\"ה כו'.",[["3450","162","<b>מל' . . אשת חיל עטרת בעלה</b>: משלי יב, ד. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370198\" data-slug=\"torah-or\" data-id=\"3901370198\">תו\"א ויגש מג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380155\" data-slug=\"likkutei-torah\" data-id=\"4001380155\">לקו\"ת שמיני יט, ב</a>. ש\"א כ, ב והערה 33."],["3451","163","<b>רני ושמחי בת</b>: זכרי' ב, יד."],["3452","164","<b>חיל . . מ\"ח . . דבשכמל\"ו</b>: ראה ע\"ח שער לידת המוחין שכ\"א, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380830\" data-slug=\"likkutei-torah\" data-id=\"4001380830\">לקו\"ת פ' ראה כח, ג</a> [ראה גם מאמרי אדה\"א דברים ח\"ב ע' תמו. וש\"נ]. סה\"מ תרכ\"ו ע' פא. פר\"ת ע' רמז."],["3453","165","<b>בד\"ה ונקדשתי פ\"ג בלק\"ת פ' אמור</b>: לא, סע\"ג ואילך."],["3454","166","<b>לפי' הרמ\"ק</b>: ראה לעיל רפ\"ב."],["3455","167","<b>דחוק לשון הגמרא</b>: ב\"ב עה, ב. ראה לעיל שם."],["3456","168","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם סה\"מ תר\"ם ח\"א ע' צז. וש\"נ."],["3457","169","<b>אמירת ג\"פ קדוש</b>: ישעי' ו, ג."],["3458","170","<b>תורה . . וא\"ו דש' הוי'</b>: ראה גם זהר רע\"מ תצא רעח, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע קס ואילך. ש\"א נא, ב ובהערה 33. סה\"מ תר\"ם ח\"א ע' קמב ובהערה לשם. לעיל מאמר ד\"ה ועבדתם את ה\"א על יד הערה *116."],["3459","171","<b>הקל קול יעקב . . תורה</b>: תולדות כז, כב. ראה ב\"ר פס\"ה, כ. זהר בראשית נ, ב. לעיל שם ובהערה 115."],["3460","172","<b>בד\"ה וכל בניך בלק\"ת פ' ראה</b>: כט, ג.\n\n<b>לו</b> ) <b>ג\"פ</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים."]]],[2001910350,"בחי' מצות כמ\"ש בד\"ה ושננתם, יהי' בבחי' והיה שאותיות ו\"ה קודמים לי\"ה שבשרשם גם עכשיו הם קודמים אלא מפני שעדיין לא נגמר הבירור לכן בחכ' דוקא אתברירו וכמ\"ש בד\"ה האבות הן הן המרכבה בת\"א פ' יתרו הנ\"ל ובכ\"ד, אבל בגמר הבירורים תהי' ההמשכה גם ממטה למעלה, ואז המל' תהי' בבחי' כתר דאור חוזר ויסוד בחי' חכמה כמ\"ש בביאור עככ\"ח בלק\"ת שה\"ש בסופו, א\"כ יאמרו המלאכים לפני הצדיקים שהם בחי' צדיק וצדק יסוד ומל' קדוש כדרך שאומרים לפני הקב\"ה עכשיו, והיינו שעכשיו ההמשכה היא רק מלמעלה למטה, וז\"ע ג\"פ קדוש להמשיך מחב\"ד לזו\"נ כמ\"ש בביאור כי ההרים ימושו דמ\"א ע\"ב<sup data-n=\"3461\">173</sup> שהם חח\"ן מימין כו' ג' קוין, אבל לע\"ל שיהי' קול כלה שיהי' ההמשכה גם ממטה למעלה לכן יאמרו גם לפני הצדיקים כדרך שאומרים עכשיו לפני הקב\"ה לבד כו' פי' מלמעלמ\"ט לבד כו', כי לע\"ל יהי' גם מלמטה למעלה כו'.\n\nוי\"ל<sup data-n=\"8605\">לז</sup> מה שהטעימן להאבות מעין עוה\"ב, שלעוה\"ב יהי' ממטה למעלה, ז\"ע מה שעכשיו הן המרכבה להעלות חו\"ב א\"כ חו\"ב מקבלים מהם שהם חג\"ת שזהו ג\"כ ממטה למעלה.\nוי\"ל<sup data-n=\"8606\">לח</sup> התירוץ שלע\"ל יאמרו קדוש לפני הצדיקים בשני אופנים הא' מצד שלע\"ל יתגלה ו\"ה כמו שהן בשרשן שהם גבוהים יותר מי\"ה ולכן שייך לומר לפניהם קדוש כדרך שאומרים לפני הקב\"ה חו\"ב שהרי וא\"ו בעתיקא תלי' וה' אחרונה היא עטרה עצמה כתר, וזהו מצד בחי' או\"י, הפן הב' מצד בחי' או\"ח שבבחי' או\"ח המל' כתר ויסוד חכ' לכן יאמרו המלאכי' לפניהם קדוש כדרך שאומרים עכשיו לפני הקב\"ה בחי' או\"י מלמעלמ\"ט כן יאמרו לע\"ל מצד בחי' האו\"ח שלע\"ל יהי' ההמשכה גם מלמטלמ\"ע כמ\"ש בביאור דעל כ\"כ חופה בסופו.",[["3461","173","<b>כי ההרים ימושו דמ\"א ע\"ב</b>: לקו\"ת תצא.\n\n<b>לז</b> ) <b>י\"ל</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים.\n\n<b>לח</b> ) <b>וי\"ל</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים."]]],[2001910351,"<h3>[נקדישך] וביאור הענין</h3>\n<b>ל\"נ והוא מאמר בפ\"ע</b>\nג) <b>וביאור</b><sup data-n=\"3462\">1</sup> הענין* הנה ארז\"ל במד\"ר כאן בפ' קדושי' ס\"פ ך\"ד<sup data-n=\"3463\">2</sup> בענין ג\"פ קדוש, ר' אבין אמר, משל<sup data-n=\"3464\">3</sup> לבני מדינה שעשו ג' עטרות למלך, מה עשה המלך נתן בראשו אחת, ושתים בראשם של בניו, כך בכי\"ו ויום העליונים מכתירין להקב\"ה ג' קדושות נותן<sup data-n=\"3465\">4</sup> בראשו אחת ושתים בראשם<sup data-n=\"3466\">5</sup> ש\"י הה\"ד דבר<sup data-n=\"3467\">6</sup> אל כל<sup data-n=\"3468\">7</sup> בנ\"י קדושי' תהיו וגו'<sup data-n=\"3469\">8</sup> ופי' המ\"כ<sup data-n=\"3470\">9</sup> דכתי'<sup data-n=\"3471\">10</sup> כי קדוש אני הרי שלא ייחד לעצמו אלא קדושה אחת<sup data-n=\"3472\">11</sup>, ולישראל נתן ב' קדושות, קדושים תהיו, והתקדישתם\n\n*)עד<sup data-n=\"8607\">א</sup> כ\"נ<sup data-n=\"8608\">ב</sup>, ומכאן ואילך יש להתחיל מפ\"ד נקדישך<sup data-n=\"8609\">ג</sup> הלא לא נערוך אליו קדושתו<sup data-n=\"8610\">ד</sup> וכתי' אין קדוש כהוי'<sup data-n=\"8611\">ה</sup> ויובן בהקדם המד\"ר דג' עטרות (פ\"ג ולסיים בפ\"ד).\nלרוקע<sup data-n=\"8612\">ו</sup> הארץ י\"ל כנס\"י על המים מלאכים נוני ימא<sup data-n=\"8613\">ז</sup>.",[["3462","1","<b></b> [נקדישך]<b> וביאור הענין</b>: להתחלת המאמר השווה אוה\"ת קדושים כרך ד ע' א'נט. לפסקאות ולהבין־ יצרתיו <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">לקו\"ת אחרי כה, סע\"ד</a> ואילך. לפ\"ד <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380518\" data-slug=\"likkutei-torah\" data-id=\"4001380518\">לקו\"ת שלח נא, ג</a> ואילך. לעיל מאמר ד\"ה וידבר כו' קדושים תהיו הערה 1.\nבהכותרת כאן נרשם: ל\"נ לא נאמר. ובשוה\"ג נרשם הוראה להמעתיק איך לסדר המאמר.\nבמפתח בוך זה 1130 לא נרשם מאמר זה. אמנם בא זכרו במפתח לבוך תרמ\"א 2086 (כת\"י מעתיק)."],["3463","2","<b>במד\"ר . . ס\"פ ך\"ד</b>: סימן ח.\nמובא גם בכ\"מ ובשינויים וכו' ומהם: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380226\" data-slug=\"likkutei-torah\" data-id=\"4001380226\">לקו\"ת אמור לה, א</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תקפב. סהמ\"צ להצ\"צ קנג, ב. הגהת הצ\"צ למאמרי אדה\"ז תקס\"ב ח\"א ע' קעו. אוה\"ת משפטים ס\"ע א'קע ואילך. קדושים כאן כנ\"ל. ביאוה\"ז תזריע להצ\"צ כרך ב ע' תתנה. סה\"מ תרכ\"ט ע' קעח. וש\"נ. המשך מים רבים תרל\"ו ס\"פ קכד. סה\"מ תרל\"ח ס\"ע מא. תרל\"ט ח\"ב ע' תד. תר\"ן ע' שנא. המשך תער\"ב בתחילתו. תש\"ח ע' 201. (לקמן מאמר ד\"ה ונקדשתי על יד הערה ו. ד\"ה כתר יתנו לך פ\"א. (ובחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 11).\nובלשון ”למלך שעשה\" — מאמרי אדה\"א הנחות תקע\"ז ע' עה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550493\" data-slug=\"torat-chaim\" data-id=\"2300550493\">תו\"ח תצוה ח\"ב שנ, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550293\" data-slug=\"torat-chaim\" data-id=\"2300550293\">פקודי תנו, ב</a>. סה\"מ תרכ\"ו ס\"ע פ. פלח הרמון אמור ע' רכ."],["3464","3","<b>אמר משל</b>: כ\"ה גם באוה\"ת כאן. בויק\"ר שם: אמר אוחרי משל, ופי' במתנות כהונה שם: משל אחר."],["3465","4","<b>קדושות נותן</b>: כ\"ה גם באוה\"ת כאן. בויק\"ר שם: קדושות מה הקב\"ה עושה נותן."],["3466","5","<b>בראשם</b>: בויק\"ר ואוה\"ת: בראשן."],["3467","6","<b>דבר . . קדושים תהיו</b>: קדושים יט, ב [בדילוג]."],["3468","7","<b>כל</b>: נרשם בין השיטין. בויק\"ר ואוה\"ת: כל עדת."],["3469","8","<b>וגו'</b>: וכ\"ה גם באוה\"ת. בויק\"ר: והתקדשתם והייתם קדושים — נסמן בסמוך הערה 12."],["3470","9","<b>ופי' המ\"כ</b>: ד\"ה והייתם קדושים וגו'."],["3471","10","<b>דכתי'</b>: וכ\"ה גם באוה\"ת. במ\"כ ליתא."],["3472","11","<b>אחת</b>: ע\"כ פי' המ\"כ.\n\n<b>א</b> ) <b>עד</b>: נרשם בצד הימיני של העמוד בד' שורות מלמעלמ\"ט בהפסק קו קצר בינו לציון הפרק ג. ללא ציון מקומו בפנים. והוא הוראות להמעתיק איך לסדר המאמר [אמנם לא הגיע לידינו המאמר כשהוא מסודר. ואולי לא נעתק בכת\"י המעתיק].\n\n<b>ב</b> ) <b>כ\"נ</b>: כאן נאמר.\n\n<b>ג</b> ) <b>נקדישך</b>: נוסח הקדושה.\n\n<b>ד</b> ) <b>לא נערוך אליו קדושתו</b>: פיוט יגדל. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח סב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380647\" data-slug=\"likkutei-torah\" data-id=\"4001380647\">לקו\"ת (מטות פא, ב</a>) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540220\" data-slug=\"torat-chaim\" data-id=\"2300540220\">יו\"כ ע, א</a>. תו\"ח בשלח ח\"א קסג, א. וש\"נ.\n\n<b>ה</b> ) <b>אין קדוש כהוי'</b>: שמו\"א ב, ב.\n\n<b>ו</b> ) <b>לרוקע</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300003\" data-slug=\"or-hatorah-hb\" data-id=\"8316300003\">אוה\"ת</a> ויקרא כאן נרשם זה בפנים כאן בין שני חצאי לבנה.\n\n<b>ז</b> ) <b>מלאכים נוני ימא</b>: ראה זהר בשלח מח, ב ובמק\"מ שם. ביאורי הזהר בשלח מא, סע\"ג. מב, ג. ולהצ\"צ כרך א ע' רח. ע' ריב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380110\" data-slug=\"likkutei-torah\" data-id=\"4001380110\">לקו\"ת צו ח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380150\" data-slug=\"likkutei-torah\" data-id=\"4001380150\">שמיני יח, א</a>."]]],[2001910352,"והייתם קדושים<sup data-n=\"3473\">12</sup>. והנה ענין ג' קדושות שהעליונים מכתירים הכוונה על ג\"פ קדוש שהמלאכים אומרים<sup data-n=\"3474\">13</sup>, ולכאורה מהו שייך ענין אמירת וקריאת קדוש שהשרפים אומרים<sup data-n=\"3475\">14</sup> שיתנו מהכתרים שנעשים ע\"י קריאתם ב' לישראל. אך הענין הוא דאיתא בגמ' (חולין דצ\"א סע\"ב) שאין המלאכים אומרים קדוש<sup data-n=\"3476\">15</sup> עד שיאמרו ישראל למטה תחלה כמ\"ש<sup data-n=\"3477\">16</sup> ברן יחד כל כוכבי בקר<sup data-n=\"3478\">17</sup>, והיינו ק\"ש<sup data-n=\"3479\">18</sup> שאנו מיחדים שמו בכי\"ת, והדר וירעו כל בני אלקים שאח\"כ אומרים המלאכים השירה שלהם, וא\"כ תלוי אמירת שירת המלאכים בישראל. גם אפ\"ל* ג' קדושות היינו קדושה דיוצר, וקדושה דשמו\"ע, וקדושה דבי סדרא<sup data-n=\"3481\">19</sup>, שזהו מה שישראל אומרים בכי\"ו<sup data-n=\"3480\">*19</sup>. ועכ\"ז אמרו במד\"ר הלשון שהעליונים מכתירים כי מה שמאותיות התפלה נעשים כתרים לקונו למעלה זהו ע\"י המלאכים שמעלים ומזככים התפלה כמ\"ש מזה בת\"א בד\"ה נר חנוכה כו' מזוזה מימין ובהביאור<sup data-n=\"3482\">20</sup>, לכן נק' שהעליונים מכתירין כו'.",[["3473","12","<b>והתקדישתם והייתם קדושים</b>: קדושים כ, ז."],["3474","13","<b>ג\"פ קדוש שהמלאכים אומרים</b>: נסמן בהערה הבאה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380226\" data-slug=\"likkutei-torah\" data-id=\"4001380226\">לקו\"ת אמור לה, א</a>."],["3475","14","<b>קדוש שהשרפים אומרים</b>: ישעי' ו, ב-ג. ראה חולין צא, ב ואילך ובתוד\"ה ברוך (שם צב, רע\"א)."],["3476","15","<b>שאין המלאכים אומרים קדוש</b>: שם: ואין מלאכי השרת אומרים שירה למעלה. ראה זהר בלק קצ, ב.\nמובא גם בכ\"מ ומהם: או\"ת תהלים סה, ד ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370370\" data-slug=\"torah-or\" data-id=\"3901370370\">תו\"א תשא פג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381276\" data-slug=\"likkutei-torah\" data-id=\"4001381276\">לקו\"ת שה\"ש לז, א</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' רנב (נו\"ש). מאמרי אדה\"א בראשית ע' קכז. שמות ח\"ב ע' תקפט ואילך. ע' תקנז. ויקרא ח\"ב ע' תקסה. ר\"ה ע' א'מט. וש\"נ. נ\"ך ע' רעט. ע' שמב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680085\" data-slug=\"torat-chaim\" data-id=\"2300680085\">תו\"ח ויחי רלו, ד</a> הערה 82. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550300\" data-slug=\"torat-chaim\" data-id=\"2300550300\">תו\"ח משפטים ח\"ב רפג, ג</a>. אוה\"ת ויקהל ע' ב'קי. איוב כרך א ע' תרפד. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370335\" data-slug=\"torah-or\" data-id=\"3901370335\">תו\"א משפטים עה, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381277\" data-slug=\"likkutei-torah\" data-id=\"4001381277\">לקו\"ת שה\"ש לז, ב</a> ואילך."],["3477","16","<b>תחלה כמ\"ש</b>: שם: שנאמר."],["3478","17","<b>ברן יחד כל כוכבי בקר</b>: איוב לח, ז [בהוספת תיבתכל — וכ\"ה בסהמ\"צ להצ\"צ ה, ב. סה\"מ תרכ\"ז ס\"ע שמה. תרכ\"ט ע' קפח. תרל\"ב ח\"ב ע' תקפה. תרל\"ט ח\"ב ס\"ע תד. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כתר יתנו לך ובהערה 16. תר\"ן ע' שנא. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490033\" data-slug=\"or-hatorah-hb\" data-id=\"8316490033\">אוה\"ת</a> איוב שם ע' תרפה ע' תרפו מצטט הכתוב בהוספת תיבת ”כל\" בב\"ר פס\"ה, כא. בזהר בראשית מה, ב. וארא ל, א. אבל לפנינו בהנ\"ל ליתא]."],["3479","18","<b>והיינו ק\"ש</b>: ראה אוה\"ת איוב כרך א ע' תרפה: ”במד\"ר פ' תולדות פס\"ה דף ע\"ד א'\" [ב\"ר פס\"ה, כא]. סה\"מ תרל\"ב ח\"ב ע' תקפה."],["3481","19","<b>וקדושה דבי סדרא</b>: ראה סוטה מט, א."],["3480","*19","<b>גם אפ\"ל . . בכי\"ו</b>: מובא גם בסה\"מ תר\"ן ע' שנא."],["3482","20","<b>בת\"א בד\"ה נר חנוכה . . ובהביאור</b>: מקץ מב, ב. מג סע\"א ואילך."]]],[2001910353,"<b>ולהבין</b> ענין ג' עטרות, צ\"ל מארז\"ל על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח<sup data-n=\"3483\">21</sup>, וצ\"ל מה\"ע שחשיב בכ\"מ מספר שלשה כמו ג' אבות וג' מדריגות בישראל כהנים לוים וישראלים<sup data-n=\"3484\">22</sup>, וגם התורה נק' אוריין תליתאי לעם תליתאה בירחא תליתאי<sup data-n=\"3485\">23</sup>, וכאן חשיב ג\"כ ג\"פ קדוש. ונבין תחילה ענין בחי' ג\"ד הנ\"ל דתורה ועבודה וגמ\"ח (כי ביום הזה בפ' אחרי דך\"ה סע\"ד<sup data-n=\"3486\">24</sup>) שהם כלל כל התורה והמצות, שענינם עכשיו בעבודה תורה ותפלה וצדקה, כי תפלה הוא במקום עבודת הקרבנות<sup data-n=\"3487\">25</sup> וגמ\"ח היינו צדקה, וכנגד ג' דברים אלו כתי' בראתיו יצרתיו אף עשיתיו<sup data-n=\"3488\">26</sup> שהם בחי' ג' לבושי הנפש מחדומ\"ע, בראתיו הוא בחי' מחשבה שהיא בחי' בריאה יש מאין<sup data-n=\"3489\">27</sup> והוא נגד התפלה שהיא עבודה שבלב כמארז\"ל ולעבדו בכל לבבכם<sup data-n=\"3490\">28</sup> איזהו עבודה שבלב זו תפלה<sup data-n=\"3491\">29</sup> שהוא בחי' הכוונה בבחי' המחשבה ברעותא דליבא<sup data-n=\"3492\">30</sup> כו', וכמארז\"ל תפלה בלא כוונה כגוף בלא נשמה<sup data-n=\"3493\">31</sup>, ודבור התפלה הוא רק שיהי' הקול מעורר הכוונה<sup data-n=\"3494\">32</sup>, לכן היא במקום הקרבנות שעבודת הקרבנות היתה תלויה בכהנים בעובדא וברעותא דליבא<sup data-n=\"3495\">33</sup> כמ\"ש בזהר, וכנודע שמחשבת חוץ פוסל בקרבן<sup data-n=\"3496\">34</sup>, ובעבודה היינו שיהי' מחשבתו וכוונתו דבוקה באוא\"ס ב\"ה בבחי' מס\"נ",[["3483","21","<b>על שלשה דברים . . גמ\"ח</b>: אבות פ\"א, מ\"ב."],["3484","22","<b>כהנים לוים וישראלים</b>: ראה רש\"י ד\"ה לעם תליתאה בהערה הבאה."],["3485","23","<b>אוריין תליתאי . . תליתאי</b>: ראה שבת פח, א."],["3486","24","<b>כי ביום הזה בפ' אחרי דך\"ה סע\"ד</b>: בלקו\"ת. צויין אליו גם באוה\"ת ויקרא כאן ע' א'נט. הבא לקמן בפנים הוא ע\"פ לשון הלקו\"ת (עם הוספות)."],["3487","25","<b>תפלה . . עבודת הקרבנות</b>: ברכות כו, א-ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380630\" data-slug=\"likkutei-torah\" data-id=\"4001380630\">לקו\"ת פינחס עז, ג</a>. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["3488","26","<b>בראתיו יצרתיו אף עשיתיו</b>: ישעי' מג, ז."],["3489","27","<b>מחשבה . . יש מאין</b>: ראה בנוסף ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380586\" data-slug=\"likkutei-torah\" data-id=\"4001380586\">לקו\"ת כאן. בלק סז, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540991\" data-slug=\"torat-chaim\" data-id=\"2300540991\">תו\"ח בא ח\"א קלא, סע\"ג</a> ואילך. וש\"נ."],["3490","28","<b>ולעבדו בכל לבבכם</b>: עקב יא, יג."],["3491","29","<b>איזהו עבודה שבלב זו תפלה</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א. רמב\"ם ריש הלכות תפלה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450608\" data-slug=\"or-hatorah-hb\" data-id=\"8316450608\">אוה\"ת עקב ע' תרח</a>."],["3492","30","<b>ברעותא דליבא</b>: זהר וירא ק, א."],["3493","31","<b>וכמארז\"ל תפלה . . כגוף בלא נשמה</b>: ראה גם סה\"מ תרל\"ב ח\"ב ע' תקמא [ושם: כמשארז\"ל]. תרל\"ג ח\"א ע' לג [ושם: וכמשארז\"ל . . וכן אמרו]. ישעות משיחו לאברבנאל (ח\"א מהדורת תשנ\"ג כה, ב). נחלת אבות להנ\"ל פ\"ב, מט\"ו (ע' קכג: וכמו שאמרו חז\"ל). פרדס שער הנשמה של\"א, ספ\"ה (כאמרם). עש\"מ מאמר חקור דין ח\"ג, פי\"ד (והיינו דאמרי אינשי). מדרש שמואל אבות פ\"ב, מט\"ו (סד\"ה והחסיד כתב). טור פטדה הל' שבת סרס\"ג, ס\"ה (שלכן שאמרו חז\"ל). של\"ה מס' תמיד ענייני תפלה רמט, סע\"ב (עוד בדברי חכמים). פ' שופטים שעט, א ד\"ה עבודה (וכמו שאמרו). עוללות אפרים — לרש\"א לונטשיץ — מאמר תצח (וידוע משל הדיוט). עקידת יצחק פ' צו שנ\"ח י, סע\"ד (וכמו שאמרו). נשמת אדם לר' אהרן שמואל מקרעמניץ פ\"א ע' כג. פ\"ח ע' קמה (מאמרם ז\"ל). אור יקר (פי' על ס\"י להרמ\"ק) פ\"ב, מ\"ג ע' פט. נשמת שבתי הלוי שער י\"ג תפלה בלא כוונה כגוף בלא נשמה. יוסף אומץ — לר\"י יוזפא האן — סל\"ו. קב הישר פ\"ח. סידור יעב\"ץ סולם בית אל ד\"ה מחשבה ו, ב (ואמרו ראשונים). תניא פל\"ח."],["3494","32","<b>הקול מעורר הכוונה</b>: ראה טושו\"ע או\"ח סס\"א, ס\"ד. ר\"ח שער הקדושה ספט\"ו. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' נה ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540812\" data-slug=\"torat-chaim\" data-id=\"2300540812\">תו\"ח בא ח\"א קו, ד</a> ובהערה 433."],["3495","33","<b>בכהנים בעובדא וברעותא דליבא</b>: ראה זהר בשלח נז, א. שמיני לט, א. אמור פח, ב. קרח קעז, ב. ביאוה\"ז ויצא קלג, א ואילך."],["3496","34","<b>שמחשבת חוץ פוסל בקרבן</b>: ראה רמב\"ם הל' פסולי המוקדשין רפי\"ג. סה\"מ תר\"ם ח\"א ע' רצד. וש\"נ."]]],[2001910354,"היינו בחי' מסירת הרצון<sup data-n=\"3497\">35</sup> שלא יהי' רק לב אחד לאבינו שבשמים<sup data-n=\"3498\">36</sup>, וכ\"ש שלא יהי' נפרד ח\"ו, וזהו ע\"י סור מרע ועשה טוב<sup data-n=\"3499\">37</sup>, והיינו שכד אתכפיא סט\"א<sup data-n=\"3500\">38</sup> ע\"י עבודתו עי\"ז יאיר אור ה' על נפשו כו' ויאיר חלקו בעולם, כמ\"ש גם את העולם נתן בלבם<sup data-n=\"3501\">39</sup>, עולם הוא מל' העלם<sup data-n=\"3502\">40</sup> מל' זה שמי לעלם<sup data-n=\"3503\">41</sup>, ובחי' העלם זה נתן בלב האדם כמ\"ש מזה בלק\"ת סד\"ה והי' מספר בהג\"ה<sup data-n=\"3504\">42</sup>, והיינו שלפ\"ע שממשיך בעצמו מהעלם אל הגילוי ע\"י בחי' הכוונה ורעו\"ד לפי ערך זה ממשיך בעולם היינו שיתגלה בחי' ההעלם של העולם שנק' עולם ע\"ש ההעלם, והמשכה זו הוא בעולם הבריאה שהיא ראשית בחי' ההעלם של העולמות שהבריאה היא ראשית בחי' היש שנתהוה מאין והרי הוא ראשית ההעלם, וע\"י שמגלה בחי' ההעלם שלו עי\"ז ממשיך המשכת אלקותו ית' שיתגלה מהעלמו בראשית בחי' ההעלם שהוא בחי' עולם הבריאה כו'.\n<b>יצרתיו</b> הוא בחי' הדבור<sup data-n=\"3505\">43</sup>, ונק' הדבור בשם יצירה ע\"ש שעושה צורה לאותיות המח' כי אותיות הדבור אינם בבחי' יש מאין כמו אותיות המחשבה כו', שהרי כבר היו האותיות בבחי' המחשבה רק שאינם נגלים לזולתו, וע\"י בחי' הדבור מתגלים לזולתו שנמצא אותיות הדבור הם כמו צורה לחומר שהצורה מגלה מה שהי' בהעלם בחומר הנסכא עד\"מ, ואינו מתחדש כלל כ\"א שמגלה ההעלם, וכך אותיות המחשבה הם כמו חומר לגבי גילוי הזולת, ואותיות הדבור מגלים את בחי' ההעלם דמח', ובחי' זו היא נגד בחי' ומדריגת התורה שעיקר מצות לימוד התורה היא בבחי' דיבור כמ\"ש ושננתם לבניך ודברת בם<sup data-n=\"3506\">44</sup>, וקי\"ל דהרהור לאו כדבור דמי<sup data-n=\"3507\">45</sup>, ואינו יוצא ידי חובתו בהרהור לבד, והגם שמעלת התורה עולה למעלה מעלה על בחי' התפלה, וכמארז\"ל ות\"ת כנגד כולם<sup data-n=\"3508\">46</sup>, אך באמת היא הנותנת שלפי שמעלתה במקורה היא ברום המעלות בבחי' סדכ\"ס<sup data-n=\"3509\">47</sup>, א\"א לקבל אורה בבחי' גילוי עד שתרד ותתלבש בגשמיות עוה\"ז בחי' קול יעקב<sup data-n=\"3510\">48</sup> בהבל הפה, ואינו יוצא בהרהור",[["3497","35","<b>מס\"נ . . מסירת הרצון</b>: ראה לקו\"ש לך ח\"ב ע' 456. שע\"ת נג, ב ואילך ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540673\" data-slug=\"torat-chaim\" data-id=\"2300540673\">תו\"ח וארא ח\"א עט, ג</a> ובהערה 483."],["3498","36","<b>לב אחד לאבינו שבשמים</b>: ע\"פ ברכות נז, א."],["3499","37","<b>סור מרע ועשה טוב</b>: תהלים לד, טו. ראה גם לעיל מאמר ד\"ה והי' אור הלבנה פ\"ב."],["3500","38","<b>שכד אתכפיא סט\"א</b>: ראה זהר תרומה קכח, ב. יתרו סז, ב. מאמרי אדה\"א שמות ח\"א ע' ה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770331\" data-slug=\"or-hatorah-hb\" data-id=\"8316770331\">אוה\"ת שלח כרך ו ע' א'תשעב</a>. וש\"נ. שה\"ש כרך ב ע' תרצט."],["3501","39","<b>גם את העולם נתן בלבם</b>: קהלת ג, יא. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ספ\"ב. וש\"נ."],["3502","40","<b>עולם הוא מל' העלם</b>: ראה ספר הבהיר ס\"י. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541025\" data-slug=\"torat-chaim\" data-id=\"2300541025\">תו\"ח שמות ח\"א יח, ד</a> הערה 783."],["3503","41","<b>זה שמי לעלם</b>: שמות ג, טו."],["3504","42","<b>בלק\"ת סד\"ה והי' מספר בהג\"ה</b>: במדבר ו, ג."],["3505","43","<b>יצרתיו הוא בחי' הדבור</b>: הבא לקמן בפנים הוא ע\"פ לשון ה<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380188\" data-slug=\"likkutei-torah\" data-id=\"4001380188\">לקו\"ת אחרי שם כו, א</a> (עם הוספות)."],["3506","44","<b>ושננתם לבניך ודברת בם</b>: ואתחנן ו, ז. ראה ספרי ופרש\"י שם. יומא יט, ב ובפרש\"י שם ד\"ה בם (הב'). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071278\" data-slug=\"likkutei-sichot\" data-id=\"1300071278\">לקו\"ש פסח כרך ז ע' 266</a> הערה 2. פקןדי כרך טז ע' 462 ואילך ובהערות שם."],["3507","45","<b>דהרהור לאו כדבור דמי</b>: ברכות כ, סע\"ב."],["3508","46","<b>ות\"ת כנגד כולם</b>: פאה פ\"א, מ\"א. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 117."],["3509","47","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8315950468\" data-slug=\"or-hatorah-hb\" data-id=\"8315950468\">אוה\"ת בשלח ע' תסח</a>. לעיל מאמר ד\"ה הים ראה וינוס על יד הערה 74 ואילך."],["3510","48","<b>קול יעקב</b>: תולדות כז, כב. ראה גם לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 115."]]],[2001910355,"וכוונה שהוא בחי' מח' כנ\"ל כ\"א בדבור דוקא בקול והבל הלב שבהם יתלבש אור ה' הגנוז בתורתו ומאיר בבחי' גילוי להחיות עולמות עליונים ותחתונים, וכידוע<sup data-n=\"3511\">49</sup> שכל דבר עליון מאד אינו בא לידי גילוי אורו כ\"א למטה בסוף מעשה<sup data-n=\"3512\">50</sup>, ומהאי טעמא עצמו אף עשיתיו כנגד מעשה הצדקה, שהיא כלליות כל המצות כמ\"ש וצדקה תהי' לנו<sup data-n=\"3513\">51</sup> כי נשמור לעשות את כל המצוה, ואף מרבה בחי' רביעית<sup data-n=\"3514\">52</sup> שהוא בחי' כתר עליון המתגלה בבחי' עשייה דוקא בחי' בירור ש' ב\"ן<sup data-n=\"3516\">54</sup>, וכמ\"ש בלק\"ת פ' בלק בביאור ע\"פ מי מנה פ\"ג<sup data-n=\"3515\">53</sup> באריכות שעיקר גילוי הרצון עליון הוא בעשייה דוקא, כמו כשאינו רוצה ללמוד ולומד מפני שהרצ\"ע הוא שילמוד תורה אזי עי\"ז מתגלה בחי' הרצון עליון, וכן להיפך כשרוצה איזה תאוה ר\"ל ועושה<sup data-n=\"3517\">55</sup> עושה בכדי שלא לעבור על רצה\"ע עי\"ז מאיר ומתגלה בחי' רצה\"ע כו', וז\"ע נעוץ תחילתן בסופן<sup data-n=\"3518\">56</sup> שבעשייה דוקא מתגלה רצון העליון כו'.\nד) <b>והנה</b> ג\"פ קדוש הוא להמשיך קדושתו ית' בג' בחי' מחדומ\"ע (בד\"ה וישלח יהושע<sup data-n=\"3519\">57</sup> בס\"פ שלח דנ\"א ג) דהנה בכי\"ו אנו אומרים נקדישך<sup data-n=\"3520\">58</sup>, ולכאו'\n\nמעשה<sup data-n=\"8614\">ח</sup> בעשייה שיתגלה שע\"י מעשה גשמיות כתפילין ועקימת שפתים דתורה זהו מתגלה בעשיי' דוקא כי לפ\"ע רוממות תרי\"ג מצות<sup data-n=\"8615\">ט</sup> שהם מגלגלתא<sup data-n=\"8616\">י</sup> שלמעלה ממו\"ס<sup data-n=\"8617\">יא</sup> היינו כתר שבכתר<sup data-n=\"8618\">יב</sup> זה מתגלה בעשייה דוקא.",[["3511","49","<b>וכידוע</b>: בלקו\"ת כאן: וכידוע ליודעי חן."],["3512","50","<b>שכל דבר עליון . . בסוף מעשה</b>: ראה ש\"א שער הפורים נח, א. סה, א. סה\"מ תרל\"ח ע' תב. וש\"נ."],["3513","51","<b>וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540914\" data-slug=\"torat-chaim\" data-id=\"2300540914\">תו\"ח שמות ח\"א יד, א</a> ובהערה 628. סה\"מ תרל\"ח ע' שמט. וש\"נ. תר\"ם ח\"א ע' צח. וש\"נ. ח\"ב ע' תפה. וש\"נ. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ועבדתם את ה\"א הערה 34."],["3514","52","<b>ואף מרבה בחי' רביעית</b>: ישעי' מג, ז. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380587\" data-slug=\"likkutei-torah\" data-id=\"4001380587\">לקו\"ת בלק סז, ב</a>. בהערה הבאה."],["3516","54","<b>ש' ב\"ן</b>: מובא כמ\"פ בע\"ח ופע\"ח וכו'. ראה גם ז\"ח רות (מהדורת מרגליות) פד, ב. ס' הפליאה פרעמישלא תרמ\"ד ל, ריש ע\"ב (הב'). שושן סודות מ, ב. מא, ע\"ב."],["3515","53","<b>ואף מרבה . . מי מנה פ\"ג</b>: סט, ג ואילך."],["3517","55","<b>ועושה</b>: אוצ\"ל: ואינו."],["3518","56","<b>נעוץ תחילתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["3519","57","<b>בד\"ה וישלח יהושע</b>: בלקו\"ת. צויין אליו גם באוה\"ת ויקרא כאן ע' א'נט. הבא לקמן בפנים הוא לשון הלקו\"ת (בשינויים קלים)."],["3520","58","<b>בכי\"ו </b> [ בכל יום]<b> אנו אומרים נקדישך</b>: בחזרת הש\"ץ.\n\n<b>ח</b> ) <b>מעשה</b>: נרשם בשולי היריעה בצד הימני ללא ציון מקומו בפנים.\n\n<b>ט</b> ) <b>תרי\"ג מצות</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה קדש ישראל לה' הערה 131.\n\n<b>י</b> ) <b>תרי\"ג מצות שהם מגלגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ (קלא, א). סה\"מ תר\"ם ח\"א ע' נה. וש\"נ.\n\n<b>יא</b> ) <b>מגלגלתא שלמעלה ממו\"ס</b>: ראה זהר אד\"ר נשא קכח, ב.\n\n<b>יב</b> ) <b>מגלגלתא . . כתר שבכתר</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381220\" data-slug=\"likkutei-torah\" data-id=\"4001381220\">לקו\"ת שה\"ש כב, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540835\" data-slug=\"torat-chaim\" data-id=\"2300540835\">תו\"ח בשלח ח\"א רכ, א</a>. וש\"נ."]]],[2001910356,"הוא נפלא לומר כן על השי\"ת שהוא קדוש ומובדל בעצמו, והאיך אנו אומרים נקדישך שאנחנו מקדשים אותך, וגם למה אומרים ג\"פ קדוש למה מספר זה דוקא, אך הענין הוא שהתורה ניתנה לנו בשלשה דברים שהם מחדומ\"ע שכמה מצות תלוים בדבור לבד, וכמה מצות תלוי' במחשבה לבדה וכמה מצות תלוים במעשה לבדה, ולכאו' יכול האדם לטעות שאין בחי' גילוי אלקות המתגלה בבחי' מעשה שוה לבחי' גילוי אלקות המתגלה בבחי' דבור ומחשבה, שבחי' מעשה הוא מתעבה ומתגשם יותר ונמשך גם בבחי' דומם כמו מעשה הצדקה בדומם בזהב וכסף ונחשת, אך באמת אינו כן כי הכל שוה אצלו ית' כי כולא קמי' כלא חשיב<sup data-n=\"3521\">59</sup> ואין הפרש אצלו בין עליונים לתחתונים כיון שהכל כאין נגדו, כי הוא ית' א\"ס ואין ערוך אליך<sup data-n=\"3522\">60</sup> כו', וזהו מה שאומרים והקדוש בשמים ובארץ<sup data-n=\"3523\">61</sup>, כלומר שבחי' שמים ובחי' ארץ שוה אצלו כי הוא קדוש ומובדל מהם, והגם שהוא מחי' את כולם<sup data-n=\"3524\">62</sup> ומהוה את כולם<sup data-n=\"3525\">63</sup> החיות הוא בבחי' רצוא ושוב<sup data-n=\"3526\">64</sup> כו' כמ\"ש במ\"א, והנה המשכת החיות מקדושתו ית' נעשה ע\"י קיום התורה והמצות כמ\"ש גוי אחד בארץ<sup data-n=\"3527\">65</sup>, פי' בארץ נעשה המשכת בחי' אחד<sup data-n=\"3528\">66</sup>, ולכן אומרים ג\"פ קדוש להמשיך קדושתו ית' בג' בחי' אלו מח' דבור ומעשה שבכולם הוא קדוש, וע\"י התורה והמצות בג' בחי' הנ\"ל ממשיכים אותך להיות נקדישך שנמשיך קדושתך כו'.",[["3521","59","<b>כולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["3522","60","<b>ואין ערוך אליך</b>: תהלים מ, ו."],["3523","61","<b>והקדוש בשמים ובארץ</b>: ברכת ישתבח. ראה גם בנוסף <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380519\" data-slug=\"likkutei-torah\" data-id=\"4001380519\">לקו\"ת שלח כאן נא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380796\" data-slug=\"likkutei-torah\" data-id=\"4001380796\">פ' ראה כ, א</a>. מאמרי אדה\"א שמות ח\"ב ס\"ע תכב. וש\"נ. דברים ח\"א ע' קפג. וש\"נ."],["3524","62","<b>שהוא מחי' את כולם</b>: נחמי' ט, ו."],["3525","63","<b>ומהוה את כולם</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה הקבצו ושמעו הערה 26."],["3526","64","<b>החיות . . רצוא ושוב</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תת. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550088\" data-slug=\"torat-chaim\" data-id=\"2300550088\">תו\"ח תצוה ח\"ב שיח, ד</a>. וש\"נ. סה\"מ תרכ\"ט ריש ע' רעו. לקמן מאמר ד\"ה שיר המעלות ממעמקים ובהערה 44."],["3527","65","<b>גוי אחד בארץ</b>: שמו\"ב ז, כג. דברי הימים-א יז, כא."],["3528","66","<b>בארץ נעשה . . אחד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370130\" data-slug=\"torah-or\" data-id=\"3901370130\">תו\"א וישב כז, סע\"ד</a>. לעיל מאמר ד\"ה כי תשא ובהערה 21."]]],[2001910357,"<h3>והנותר בירושלם</h3>\n<b>בס\"ד</b>\n<b>והנותר</b><sup data-n=\"3530\">2</sup> בירושלם<sup data-n=\"3529\">1</sup> פי' בד\"ה ושננתם פי\"א<sup data-n=\"3531\">3</sup> על מעשה המצות שעז\"נ והי' ביום ההוא יצא מ\"ח מירושלם<sup data-n=\"3532\">4</sup> עכ\"ל שם. ולכאו' מה שייך ירושלים למעשה המצות. אך הענין הוא דציון הוא פנימיות ירושלם<sup data-n=\"3533\">5</sup>, וציון הוא בחי' תורה כמ\"ש כי מציון תצא תורה<sup data-n=\"3534\">6</sup>, ודבר ה' מירושלם י\"ל דבר ה' היינו בחי' דבר מלך שלטון<sup data-n=\"3535\">7</sup> בחי' מצות המלך<sup data-n=\"3536\">8</sup> שהוא בחי' מעשה המצות, ולע\"ל ע\"י הבירור יתעלו בשרשם היינו בחי' גלגלתא<sup data-n=\"3537\">9</sup> בחי' חיצונית הכתר וזהו שתורה היא ציון היא פנימיות ירושלם שהתורה שרשה מבחי' ח\"ס<sup data-n=\"3538\">10</sup> פנימיות הכתר<sup data-n=\"3539\">11</sup> שרש בחי' ממכ\"ע<sup data-n=\"3540\">12</sup>, והמצות שרשם מגלגלתא חיצונית הכתר<sup data-n=\"3542\">14</sup> שרש בחי'<sup data-n=\"3543\">15</sup> סוכ\"ע<sup data-n=\"3541\">13</sup>, ובחי' זו עצמה בבחי' מל' עצמה המצות הם בחי' כתר מל' שהמל' היא כתר דאור חוזר כדפרישת<sup data-n=\"3544\">16</sup> בד\"ה ואכלתם אכול בלק\"ת פ' צו<sup data-n=\"3545\">17</sup>, נמצא דבר ה' הוא בחי' מל' מצות המלך מירושלם בחי' חיצונית הכתר דאו\"ח בחי' גלגלתא, והתורה היא מציון פנימיות ירושלם היינו חכמה סתימאה שבכתר דאו\"ח היינו בבחי' כתר מל', ולכן והיה ביום ההוא דהיינו לע\"ל שאותיות ו\"ה יהי' קודם י\"ה כמ\"ש בד\"ה וידבר כו' דבר כו' קדושים<sup data-n=\"3546\">18</sup>, יצאו מים חיים מירושלם מעשה המצות כתר שבכתר דאור חוזר חצים אל הים הקדמוני חכ' שבכתר דאור חוזר כו'.",[["3530","2","<b>והנותר בירושלם</b>: ישעי' ד, ג."],["3529","1","<b>והנותר בירושלם</b>: המאמר נרשם בגוכתי\"ק."],["3531","3","<b>פי' בד\"ה ושננתם פי\"א</b>: ראה גם לעיל מאמר ד\"ה וידבר כו' קדושים תהיו ובהערה 134."],["3532","4","<b>והי' ביום ההוא יצא מ\"ח מירושלם</b>: זכרי' יד, ח [ושם: יצאו (וכ\"ה בסיום המאמר כאן) — ראה גם סה\"מ תר\"ם ח\"ב ע' תתקד ובהערה שם]."],["3533","5","<b>דציון הוא פנימיות ירושלם</b>: ראה סידור שחרית סב, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380716\" data-slug=\"likkutei-torah\" data-id=\"4001380716\">לקו\"ת דברים א, ג</a>. אוה\"ת (יהל אור) תהלים ע' תקעה."],["3534","6","<b>כי מציון תצא תורה</b>: ישעי' ב, ג. מיכה ד, ב. ראה גם לעיל מאמר ד\"ה וידבר כו' קדושים תהיו על יד הערה 133."],["3535","7","<b>דבר מלך שלטון</b>: קהלת ח, ד."],["3536","8","<b>מצות המלך</b>: ראה אסתר ג, ג. מאמרי אדה\"א שמות ח\"א ע' יא. וש\"נ. נ\"ך ע' רלה. ש\"א ע' נו."],["3537","9","<b>המצות . . בשרשם . . גלגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ (קלא, א). סה\"מ תר\"ם ח\"א ע' נה. וש\"נ."],["3538","10","<b>שהתורה שרשה מבחי' ח\"ס</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381220\" data-slug=\"likkutei-torah\" data-id=\"4001381220\">לקו\"ת שה\"ש כב, ד</a>."],["3539","11","<b>ח\"ס פנימיות הכתר</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, פ\"א."],["3540","12","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200126\" data-slug=\"or-hatorah-hb\" data-id=\"8159200126\">ח\"ס</a> . . שרש בחי' ממכ\"ע</b>: ראה גם אוה\"ת אמור כרך ג ע' תתמ־ סה\"מ תרל\"ח ע' שלב שמציינים לד\"ה ביוהשמע\"צ שלא נדפס [ראה אוה\"ת שמע\"צ ע' א'תשפא ואילך]. לקמן מאמר ד\"ה ונקדשתי על יד הערה ג."],["3542","14","<b>מגלגלתא חיצונית הכתר</b>: ראה לעיל הערה 11."],["3543","15","<b>מגלגלתא . . שרש בחי' סוכ\"ע</b>: ראה לעיל הערה 12."],["3541","13","<b>ממכ\"ע . . סוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["3544","16","<b>כדפרישת</b>: כ\"ה בגוכתי\"ק."],["3545","17","<b>ואכלתם אכול בלק\"ת פ' צו</b>: ז, ג. הועתק גם לעיל מאמר ד\"ה וידבר כו' קדושים תהיו על יד הערה 60 ואילך."],["3546","18","<b>בד\"ה וידבר כו' דבר כו' קדושים</b>: על יד הערה 135 ואילך."]]],[2001910358,"<h3>ונקדשתי בתוך בנ\"י</h3>\n<b>אמור ך\"ב ל\"ב</b>\n<b>ונקדשתי</b> בתוך בנ\"י<sup data-n=\"3547\">1</sup>, אני כו' מקדשכם<sup data-n=\"3548\">2</sup>, ותחלה אמר ולא תחללו<sup data-n=\"3549\">3</sup>, י\"ל שזהו כענין קדושים תהיו כי קדוש אני<sup data-n=\"3550\">4</sup>, שע\"י שתהי' פרושים מן העריות<sup data-n=\"3551\">5</sup> שזהו מה שא' כאן ולא תחללו ל' חללה, וכמ\"ש גבי אשה זונה וחללה<sup data-n=\"3552\">6</sup>, אני ה' מקדישכם שמזה פי' רש\"י והוא מהמד\"ר<sup data-n=\"3554\">8</sup> שכ\"מ שאתה מוצא גדר ערוה אתה מוצא קדושה<sup data-n=\"3553\">7</sup>.\n\nבלק\"ת<sup data-n=\"8619\">א</sup> פי'<sup data-n=\"8620\">ב</sup> קדוש הא' העלאה, והב' המשכה, והג' תומ\"צ, וע\"פ מ\"ש במ\"א מו\"ס<sup data-n=\"8621\">ג</sup> מקור ממכ\"ע<sup data-n=\"8622\">ד</sup> גלגלתא מקור<sup data-n=\"8621\">ג</sup> סוכ\"ע<sup data-n=\"8622\">ד</sup>, קדוש הג' רדל\"א<sup data-n=\"8623\">ה</sup>, עפ\"ז י\"ל קדוש שנטל לעצמו זהו הקדוש דרדל\"א שניים שנתן בראש בניו<sup data-n=\"8624\">ו</sup> מו\"ס וגלגלתא, ובעבודה תורה המשכה בפנימיות לחם<sup data-n=\"8625\">ז</sup>, ותורתך בתוך מעי<sup data-n=\"8626\">ח</sup> ממכ\"ע, מצות שרשם מגלגלתא<sup data-n=\"8627\">ט</sup> סוכ\"ע, אך צ\"ל ברכו בתורה<sup data-n=\"8628\">י</sup>, שזהו ע\"י התפילה העלאה וז\"ע קדוש הא' ועי\"ז ונתקדשתי<sup data-n=\"8629\">יא</sup> בתוך, דבר מתוך דבר<sup data-n=\"8630\">יב</sup>, תוך דבר ממכ\"ע דבר סוכ\"ע<sup data-n=\"8631\">יג</sup>, וילה\"ק ענין נקדישך<sup data-n=\"8632\">יד</sup> הלא אתה קדוש<sup data-n=\"8633\">טו</sup> אין קדוש כה'<sup data-n=\"8634\">טז</sup> לא נערוך אליו<sup data-n=\"8635\">יז</sup>, עג\"ד העולם עומד<sup data-n=\"8636\">יח</sup>, והם נגד בי\"ע תפלה צדקה תורה, ג\"פ קדוש<sup data-n=\"8637\">יט</sup>.",[["3547","1","<b>ונקדשתי בתוך בנ\"י</b>: המאמר נרשם בגוכתי\"ק."],["3548","2","<b>ונקדשתי . . אני כו' מקדשכם</b>: אמור כב, לב (כנרשם בהכותרת כאן)."],["3549","3","<b>ולא תחללו</b>: התחלת כתוב זה (ונקדשתי)."],["3550","4","<b>קדושים תהיו כי קדוש אני</b>: קדושים יט, ב."],["3551","5","<b>קדושים . . פרושים מן העריות</b>: רש\"י שם מתו\"כ."],["3552","6","<b>אשה זונה וחללה</b>: אמור כא, ז."],["3554","8","<b>מהמד\"ר</b>: ויק\"ר פכ\"ד, ו."],["3553","7","<b>פי' רש\"י . . שכ\"מ . . קדושה</b>: קדושים יט, ב.\n\n<b>א</b> ) <b>בלק\"ת</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים.\n\n<b>ב</b> ) <b>בלק\"ת פי'</b>: ראה שם אמור לב, ב ואילך. לקמן מאמר ד\"ה כתר יתנו לך ספ\"ג ואילך.\n\n<b>ג</b> ) <b>מו\"ס . . גלגלתא מקור סוכ\"ע</b>: ראה גם לעיל מאמר ד\"ה והנותר בירושלם ובהערה 12.\n\n<b>ד</b> ) <b>ממכ\"ע . . סוכ\"ע</b>: זהר רע\"מ פינחס רכה, א.\n\n<b>ג</b> ) <b>מו\"ס . . גלגלתא מקור סוכ\"ע</b>: ראה גם לעיל מאמר ד\"ה והנותר בירושלם ובהערה 12.\n\n<b>ד</b> ) <b>ממכ\"ע . . סוכ\"ע</b>: זהר רע\"מ פינחס רכה, א.\n\n<b>ה</b> ) <b>רדל\"א</b>: ראה זהר אד\"ז האזינו רפח, א. ע\"ח שער א\"א שי\"ג, פ\"ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380801\" data-slug=\"likkutei-torah\" data-id=\"4001380801\">לקו\"ת פ' ראה כא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">יו\"כ עא, ג</a>-ד. סה\"מ תרמ\"ז ע' צא.\n\n<b>ו</b> ) <b>קדוש שנטל . . בראש בניו</b>: ראה ויק\"ר פכ\"ד, ח. לעיל מאמר ד\"ה נקדישך בתחילתו ובהנסמן לשם.\n\n<b>ז</b> ) <b>תורה . . לחם</b>: ראה שבת קכ, א. לקו\"ש בהעלותך כרך ד ע' 1038 הערה 26. תניא פ\"ה ובמ\"מ הגהות והע\"ק לשם. סה\"מ תרכ\"ז ע' קמט. וש\"נ. תרל\"ג ח\"ב ע' תלה. וש\"נ. לעיל מאמר ד\"ה וברך את לחמך בתחילתו.\n\n<b>ח</b> ) <b>ותורתך בתוך מעי</b>: תהלים מ, ט. ראה תניא שם.\n\n<b>ט</b> ) <b>מצות שרשם מגלגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ (קלא, א). סה\"מ תר\"ם ח\"א ע' נה. וש\"נ.\n\n<b>י</b> ) <b>ברכו בתורה</b>: ראה ב\"מ פה, ב. נדרים פא, א. לקו\"ת פ' ראה כט, א. לעיל מאמר ד\"ה להבין ענין טהרת המצורע וכו' זאת תהי' תורת המצורע על יד הערה 43 ואילך.\n\n<b>יא</b> ) <b>ונתקדשתי</b>: אוצ\"ל: ונקדשתי.\n\n<b>יב</b> ) <b>דבר מתוך דבר</b>: ראה חגיגה יד, א.\n\n<b>יג</b> ) <b>תוך דבר ממכ\"ע דבר סוכ\"ע</b>: ראה סה\"מ תרל\"ח ע' רכב ואילך ובהנסמן שם.\n\n<b>יד</b> ) <b>נקדישך</b>: נוסח הקדושה.\n\n<b>טו</b> ) <b>אתה קדוש</b>: נוסח תפלת שמו\"ע.\n\n<b>טז</b> ) <b>אין קדוש כה'</b>: שמו\"א ב, ב.\n\n<b>יז</b> ) <b>לא נערוך אליו</b>: פיוט יגדל. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח סב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380647\" data-slug=\"likkutei-torah\" data-id=\"4001380647\">לקו\"ת (מטות פא, ב</a>) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540220\" data-slug=\"torat-chaim\" data-id=\"2300540220\">יו\"כ ע, א</a>. תו\"ח בשלח ח\"א קסג, א. וש\"נ.\n\n<b>יח</b> ) <b>עג\"ד העולם עומד</b>: אבות פ\"א, מ\"ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">לקו\"ת אחרי כה, ד</a> ואילך. לעיל מאמר ד\"ה נקדישך על יד הערה 21 ואילך.\n\n<b>יט</b> ) <b>עג\"ד . . ג\"פ קדוש</b>: ראה גם לקמן מאמר ד\"ה כתר יתנו לך ובהערה 13."]]],[2001910359,"<h3>כתר יתנו לך</h3>\n<b>ש\"פ אמור מ\"א</b>\n<b>כתר</b> יתנו לך<sup data-n=\"3555\">1</sup> כו' מלאכים המוני מעלה ועמך ישראל<sup data-n=\"3556\">2</sup>, משמע שרק כתר אחד יתנו לך, ובמד\"ר פ' קדושים פך\"ד<sup data-n=\"3557\">3</sup> העליונים מכתירים לך כו' ג' קדושות ופי' שם שהם ג' עטרות. ויובן בהקדם: מה דאיתא בספר ערה\"כ.\n<b>ויובן</b> עוד ענין שייכות בחי' קדושים תהיו לבחי' כי קדוש אני<sup data-n=\"3559\">5</sup>, ע\"פ<sup data-n=\"3558\">4</sup> מה דאיתא בספר ערה\"כ של הסה\"ד בערך נשמה בשם התיקונים<sup data-n=\"3560\">6</sup> שהנשמה בגוף האדם היא בדרך הלואה, שהקב\"ה הוא המלוה כו', ובערך הלואה הביא בשם ספר שמנה לחמו<sup data-n=\"3561\">7</sup>, שנק' בשם הלואה ועיסקא, והנה בדין היתר עיסקא<sup data-n=\"3562\">8</sup> אמרו אי פלגא באגר תרי תילתא בהפסד, ואם המלוה אינו רוצה לקבל תרי תלתא בהפסד כ\"א פלגא הפסד אזי לא יקבל באגר כ\"א תלתא לבד, וע' בגמרא ב\"מ פ' איזהו נשך דס\"ח סע\"ב וריש דס\"ט, ובתוספות ד\"ה אי פלגא באגר, והנה מצינו בגמ' שבת דף פ\"ט ע\"ב ע\"פ כי אתה אבינו (ישעי' ס\"ג ט\"ז) שלע\"ל יאמרו ליצחק כי אתה אבינו שאברהם לא כו' וישראל כו' והיינו שיצחק כשיאמר לו הקב\"ה בניך חטאו יעשה החשבון מע' שנה דל",[["3555","1","<b>כתר יתנו לך</b>: מאמר זה הוא מאמר ד\"ה דבר כו' קדושים תרכ\"ט (פרט להפתיחה והסיום) עם הוספות ושינויים. פ\"א ורפ\"ב נרשם בגוכתי\"ק וההמשך בכת\"י מעתיק עם הגהות בגוכתי\"ק.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לקמן בחלק הנחותיו."],["3556","2","<b>כתר יתנו לך . . ועמך ישראל</b>: נוסח קדושת כתר — צויין להלן בפנים."],["3557","3","<b>ובמד\"ר פ' קדושים פך\"ד</b>: ראה שם סימן ח. לעיל מאמר ד\"ה [נקדישך] וביאור הענין הערה 2."],["3559","5","<b>קדושים תהיו . . כי קדוש אני</b>: קדושים יט, ב."],["3558","4","<b>ויובן עוד . . ע\"פ</b>: אולי הכוונה להשמיט תיבות אלו."],["3560","6","<b>בספר ערה\"כ . . בשם התיקונים</b>: בערה\"כ שם: ”בתיקוני' . . כאא\"ז\" [ כבוד אדוני אבי זקני] וכ\"ה בערך גוף. ובערך הלואה המובא בסמוך בפנים: ”ובק\"ש [ ובקרבן שבת] פ\"ב סי' ג בשם תיקונים\". ובקרבן שבת — דיהרן פארט תנ\"א לר' בצלאל דרשן בסלוצק — ”בתיקונין שבע' אנפין בדף קמ\"א ע\"א\" ולפנינו (ראה) ת\"ז תקונא חמישאה קמב, ב ואילך. וראה גם סה\"מ תרל\"ח ע' לד. וש\"נ."],["3561","7","<b>שמנה לחמו</b>: ח\"ב פי\"ב. דעסא תס\"א — לר' אשר אנשיל בר' יצחק מפרמישלא."],["3562","8","<b>היתר עיסקא</b>: ראה ב\"מ המצויין בסמוך בפנים. שו\"ע אדה\"ז הל' רבית סל\"ח. סה\"מ תרל\"ח שם. וש\"נ."]]],[2001910360,"ך' שאינו בר עונשין, וך\"ה דלילותא, וי\"ב וחצי דצלוי ומיכלא ובהכ\"ס, ונשאר י\"ב וחצי, אם אתה סובל את כולם מוטב וא\"ל פלגא עלי ופלגא עלך, ונמצא שכאשר הלוה מקבל פלגא בהפסד צריך המלוה לקבל רק שליש מהרויח בכדי שלא יהי' ריבית, והנה עפ\"ז יובן מה דאיתא במד\"ר פ' קדושים פך\"ד משל על קדושים תהי' כי קדוש אני, למלך שעשו לו בני המדינה ג' עטרות כו' נטל אחת ונתן בראשו, ושנים בראש בניו, וכך קדושים תהיו, וכתי' והתקדשתם והייתם קדושים<sup data-n=\"3564\">10</sup> זהו שנים שנתן בראש בניו, וא' נטל לעצמו זהו דכתי' כי קדוש אני וע' במת\"כ שם<sup data-n=\"3565\">11</sup>. ונמצא זהו לפי היתר עיסקא שכאשר המלוה מקבל פלגא הפסד אזי א\"צ לקבל ברויח<sup data-n=\"3563\">9</sup> כ\"א שליש, וז\"ע העטרה א' שנתן בראשו. והענין הוא דהנה ארז\"ל על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח<sup data-n=\"3566\">12</sup>, והיינו שג' דברים אלו ז\"ע ג\"פ קדוש<sup data-n=\"3567\">13</sup> שהם ג' עטרות הנ\"ל וכמ\"ש בנוסח קדושת מוסף כתר יתנו כו' מלאכים כו' ועמך כו' וקרא כו' ואמר קק\"ק ה' צבאות<sup data-n=\"3568\">14</sup> כו' שזהו ג\"פ קדוש שמהם נעשים ג' עטרות וכתרים, ומה שחשיב מלאכים קודם כמ\"ש מלאכים המוני מעלה ועמך ישראל הגם כי באמת ארז\"ל בחולין דצ\"א סע\"ב ואין המלאכים אומרים שירה עד שיאמרו ישראל תחלה שנא' (איוב ל\"ח זיין) ברן יחד כוכבי בקר, היינו ישראל שקוראים ק\"ש בבקר והדר ויריעו כל בני אלקים היינו המלאכים, זהו מפני כי השירה דישראל אינו קדוש כ\"א ק\"ש<sup data-n=\"3569\">15</sup> שמע<sup data-n=\"3570\">16</sup> כו', אך לפי מה שתקנו בברכת ק\"ש לומר ג\"פ קדוש והמלאכים אינם אומרים שירה קודם השירה דק\"ש דישראל א\"כ קדוש דיוצר הוא ג\"כ קודם קדוש דמלאכים, ולמה תיקנו לומר בקדושה דמוסף מלאכים כו' ואח\"כ ישראל, וי\"ל שזהו מפני שהעטרה והכתר שנעשה למעלה מתפילותיהם של ישראל זהו ע\"י המלאכים כמארז\"ל מט\"ט (ופעם אמרו סנדל<sup data-n=\"3572\">18</sup>) קושר כתרים לקונו<sup data-n=\"3571\">17</sup> מתפילותיהם ש\"י, וכמ\"ש בזהר דגפיף להון ומנשק להון<sup data-n=\"3573\">19</sup> וכמ\"ש הפי' בת\"א בד\"ה מזוזה מימין ובהביאור<sup data-n=\"3574\">20</sup> שהדבור שלהם הוא זך כערך",[["3564","10","<b>והתקדשתם והייתם קדושים</b>: קדושים כ, ז."],["3565","11","<b>וע' במת\"כ שם</b>: הועתק גם לעיל מאמר ד\"ה [נקדישך] וביאור הענין רפ\"ג."],["3563","9","<b>מהרויח . . ברויח</b>: אוצ\"ל: מהריוח . . בריוח."],["3566","12","<b>על שלשה דברים . . גמ\"ח</b>: אבות פ\"א, מ\"ב."],["3567","13","<b>על שלשה דברים . . ג\"פ קדוש</b>: ראה בסמוך בפנים. סה\"מ תרל\"ט ח\"ב ע' תו. לעיל מאמר ד\"ה ונקדשתי בתוך בנ\"י על יד הערה יט. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 13."],["3568","14","<b>וקרא . . קק\"ק ה' צבאות</b>: ישעי' ו, ג."],["3569","15","<b>השירה דישראל . . ק\"ש</b>: ראה אוה\"ת איוב כרך א ע' תרפה: ”במד\"ר פ' תולדות פס\"ה דף ע\"ד א'\" [ב\"ר פס\"ה, כא]. סה\"מ תרל\"ב ח\"ב ע' תקפה. בהערה הבאה."],["3570","16","<b>שמע</b>: ואתחנן ו, ד. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 18."],["3572","18","<b>ופעם אמרו סנדל</b>: ראה זהר וישלח קסז, ב. מאמרי אדה\"א נ\"ך ע' שיג. וש\"נ."],["3571","17","<b>מט\"ט . . קושר כתרים לקונו</b>: ראה זהר בראשית לז, ב. סה\"מ תש\"ח ע' 202 בהערה."],["3573","19","<b>דגפיף להון ומנשק להון</b>: ראה זהר בראשית כג, ב. ויקהל רא, ב. סידור שער החנוכה רעג, א ואילך. מאמרי אדה\"א שמות ח\"א ע' רמז. וש\"נ. סה\"מ תרכ\"ז ריש ע' שצז. תרכ\"ט ע' ג. וש\"נ. ע' קז. תרל\"ה ח\"א ס\"ע רז ואילך."],["3574","20","<b>בת\"א בד\"ה מזוזה מימין ובהביאור</b>: מקץ מב, ב. מג סע\"א ואילך."]]],[2001910361,"המחשבה שלנו<sup data-n=\"3575\">21</sup>, וגבוה מעל גבוה<sup data-n=\"3576\">22</sup> כו' עד משכן מלאך מט\"ט כו', לכן הקדימו המלאכים, ומזה הטעם אמרו במד\"ר ג\"כ העליונים מכתירים בכי\"ו ויום ג' עטרות, והיינו שלבד שהשרפים אומרים ג\"פ קדוש<sup data-n=\"3577\">23</sup> הנה הקדוש שאומרים ישראל ג\"כ נעשה הכתר ע\"י המלאכים כנ\"ל.\nב) <b>ולהבין</b> זה צ\"ל שרש ענין ירידת הנשמה בגוף שהיא צורך עליה<sup data-n=\"3578\">24</sup> מהו העליה הלא הנשמה<sup data-n=\"3579\">25</sup> כמו שהיתה למעלה קודם התלבשותה בגוף ונה\"ב הנה כתי' חי ה' אשר עמדתי לפניו<sup data-n=\"3580\">26</sup> שהי' למעלה בבחי' עמידה וביטול לאלקות<sup data-n=\"3581\">27</sup> והיא מבחי' טהורה היא כמ\"ש נשמה שנתת בי טהורה היא<sup data-n=\"3582\">28</sup>, ולמה היתה כזאת מלפניו שתרד בגוף ותתלבש בגוף ונה\"ב, אין זה כ\"א שזהו צורך עליה, וצ\"ל מהו העליה. אך הנה עלי' זו היא ע\"ד שארז\"ל מקום שבע\"ת עומדין<sup data-n=\"3583\">29</sup> אין צד\"ג יכולים לעמוד שם, כי הנשמה קודם התלבשותה בגוף הי' בבחי' צדיקים כי ענין הצדיקים הוא שלא חטא מעולם<sup data-n=\"3584\">30</sup>, וכמו\"כ הנשמה קודם התלבשותה בגוף היתה בלא חטא ועון, וזהו טהורה היא, אך אחר ירידתה בגוף היא נעשה במדרגת בע\"ת<sup data-n=\"3585\">31</sup>, ולא ע\"י חטא ועון ח\"ו, כי התשובה אינה מעבירות דוקא<sup data-n=\"3586\">32</sup> כו', וזהו ענין העלי' שאחר הירידה. ולהבין ביאור ענין ירידת הנשמה בגוף וענין עלייתה, הנה איתא בזהר שהמלאכים נקראים בשם נוני ימא<sup data-n=\"3587\">33</sup>, והיינו כמו שהדגים שבים הם מובלעים בים כך הנה המלאכים האלו הם תמיד בבחי' ביטול בתוך הים, וכך הנה יש נשמות שהם ג\"כ בטלים בים והיינו הנשמה קודם התלבשותה בגוף היא עומדת בבחי' ביטול, שזהו מ\"ש חי ה' אשר עמדתי לפניו, וכמו\"כ המלאכים נקראים ג\"כ עומדים כמ\"ש שרפים עומדים<sup data-n=\"3588\">34</sup>,",[["3575","21","<b>שהדבור שלהם . . המחשבה שלנו</b>: ראה גם בנוסף להתו\"א מאמרי אדה\"א קונטרסים ע' תקמז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540453\" data-slug=\"torat-chaim\" data-id=\"2300540453\">תו\"ח וארא ח\"א עו, א</a>. וש\"נ. סה\"מ תרכ\"ט ע' קז. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 21."],["3576","22","<b>וגבוה מעל גבוה</b>: קהלת ה, ז."],["3577","23","<b>שהשרפים אומרים ג\"פ קדוש</b>: ישעי' ו, ב-ג. ראה חולין צא, ב ואילך ובתוד\"ה ברוך (שם צב, רע\"א)."],["3578","24","<b>ירידת הנשמה . . צורך עליה</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["3579","25","<b>הלא הנשמה</b>: מכאן ואילך לשון סה\"מ תרכ\"ט ע' קעח ואילך — נרשם בכת\"י מעתיק עם הגהות בגוכתי\"ק."],["3580","26","<b>חי ה' אשר עמדתי לפניו</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 67."],["3581","27","<b>עמידה וביטול לאלקות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370281\" data-slug=\"torah-or\" data-id=\"3901370281\">תו\"א בשלח סב, סע\"ד</a>. סה\"מ תרל\"ח ע' ת. וש\"נ. תר\"ם ח\"א ע' יב. וש\"נ."],["3582","28","<b>נשמה שנתת בי טהורה היא</b>: ברכת אלקי נשמה."],["3583","29","<b>מקום שבע\"ת עומדין</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a>. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח."],["3584","30","<b>הצדיקים הוא שלא חטא מעולם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a>. סה\"מ תר\"ם ח\"ב ע' תקמב-תקמג. ע' תתקח. ע' תתקלה."],["3585","31","<b>אחר ירידתה בגוף . . בע\"ת</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540904\" data-slug=\"torat-chaim\" data-id=\"2300540904\">תו\"ח בשלח ח\"א קעו, ד</a> ובהערה 571."],["3586","32","<b>התשובה אינה מעבירות דוקא</b>: ראה חובת הלבבות שער עבודת אלקים פ\"ג (ד\"ה והחמישי כי מצות). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370205\" data-slug=\"torah-or\" data-id=\"3901370205\">תו\"א ויחי מה, א</a>. לקמן מאמר ד\"ה שיר המעלות ממעמקים פ\"ד. סה\"מ תר\"ם ח\"ב ע' תקכט. וש\"נ."],["3587","33","<b>שהמלאכים . . נוני ימא</b>: ראה זהר בשלח מח, ב ובמק\"מ שם. ביאוה\"ז בשלח מא, סע\"ג. מב, ג. ולהצ\"צ כרך א ע' רח. ע' ריב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380110\" data-slug=\"likkutei-torah\" data-id=\"4001380110\">לקו\"ת צו ח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380150\" data-slug=\"likkutei-torah\" data-id=\"4001380150\">שמיני יח, א</a>."],["3588","34","<b>בבחי' ביטול . . שרפים עומדים</b>: ישעי' ו, ב. ראה סוטה לט, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380390\" data-slug=\"likkutei-torah\" data-id=\"4001380390\">לקו\"ת נשא כ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380398\" data-slug=\"likkutei-torah\" data-id=\"4001380398\">כב, ג</a>."]]],[2001910362,"שהנשמות קודם התלבשותם בגוף והמלאכים הם במדרגה אחת שעומדים בבחי' ביטול וזהו בחי' ים, ובחי' יבשה היא בחי' ארץ נפרדים, וזהו ענין הירידה מבחי' ים לבחי' יבשה ארץ נפרדים. וביאור ענין ים ויבשה, הנה כתי' לרוקע הארץ על המים<sup data-n=\"3589\">35</sup>, פי' כי הנה מתחלת הבריאה היו המים מקיפים את הארץ והארץ הי' מוקף מהמים ועל המים הי' בחי' הרוח כמ\"ש ורוח אלקים מרחפת ע\"פ המים<sup data-n=\"3590\">36</sup>, והיינו כי יש ד' יסודות ארמ\"ע<sup data-n=\"3591\">37</sup>, וכל היסוד שהוא גשמי יותר הוא למטה ביותר והיסוד הרוחני ממנו שוכן עליו, ולכן יסוד העפר שהוא גשמי' יותר מכל הד' יסודות לכן הי' למטה יותר מכל הד' יסודות, ויסוד המים שהם רוחני' יותר מיסוד העפר הי' מקיף את העפר, והרוח שהוא רוחני יותר מיסוד המים הוא שוכן על יסוד המים וכמ\"ש ורוח אלקים מרחפת ע\"פ המים, וזהו מצד טבע הבריאה, ואח\"כ גזר שיקוו המים<sup data-n=\"3592\">38</sup> מתחת השמים אל מקום אחד ותראה היבשה דוקא שהמים לא יחופו על העפר כ\"א המים יסתלקו למקום אחד ותראה היבשה, וזהו לרוקע הארץ על המים שיהי' הארץ על המים דוקא, כי עיקר המכוון הוא בשביל בריאת האדם וכמ\"ש אנכי עשיתי ארץ<sup data-n=\"3593\">39</sup> ואדם עליה בראתי, ובריאת האדם א\"א כ\"א בארץ דוקא ולא בים כו'. ולכן כתי' יורדי הים<sup data-n=\"3594\">40</sup> שעכשיו לאחר הגזירה כשצריכין להלוך על הים נק' ירידה כי העפר הוא למעלה מבחי' הים, וזהו ע\"פ פשוט.\nג) <b>ולהבין</b> זה בלשון החסידות, הנה מי הים הם מלוחים<sup data-n=\"3595\">41</sup> בטבע שא\"א לשתות אותם מחמת שהם מלוחים, והנה המים אלו שבים גופא כאשר בוקעי' את עפר הארץ<sup data-n=\"3596\">42</sup> ויוצאין אזי הם נעשים מים חיים<sup data-n=\"3597\">43</sup> שאז הם מתוקים ועריבים לשתות כו', וכך הנה הנשמה כמו שהיתה למעלה היתה בבחי' ים כנ\"ל שהמים הם מלוחים ובירידתם לגוף שנמשל לארץ אזי כשבוקעים את הסתר הגוף נעשים עי\"ז בשם מים חיים כו'. ולפ\"ז הנה מים מלוחים הם חסרון<sup data-n=\"3598\">44</sup> כו', אך באמת הנה מים מלוחים הם ג\"כ מדריגה גבוה, אך אינם כמו מים חיים כו', כי הנה כתי' ולא תשבית מלח ברית אלקיך, על כל קרבנך<sup data-n=\"3599\">45</sup> תקריב מלח, ובאהרן כתיב ברית מלח עולם<sup data-n=\"3600\">46</sup>",[["3589","35","<b>לרוקע הארץ על המים</b>: תהלים קלו, ו."],["3590","36","<b>ורוח אלקים מרחפת ע\"פ המים</b>: בראשית א, ב."],["3591","37","<b>ד' יסודות ארמ\"ע</b>: ראה לעיל מאמר ד\"ה וידעת היום הערה 106."],["3592","38","<b>שיקוו המים</b>: בראשית א, ט. ראה סה\"מ תש\"ח ע' 205."],["3593","39","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["3594","40","<b>יורדי הים</b>: תהלים קז, כג. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380333\" data-slug=\"likkutei-torah\" data-id=\"4001380333\">לקו\"ת במדבר ו, ב</a>. מאמרי אדה\"ז תקס\"ח ח\"א ע' ריט. שער האמונה נ, א ובהערה 8."],["3595","41","<b>מי הים הם מלוחים</b>: ראה שו\"ע אדה\"ז הל' נט\"י סקנ\"ט, סוסט\"ז. הל' שבת סשכ\"ח, סמ\"ח. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380325\" data-slug=\"likkutei-torah\" data-id=\"4001380325\">לקו\"ת במדבר ד, ב</a>. מאמרי אדה\"ז תקס\"ב ח\"א [ובמקביליו] ע' קעד. ע' קעו. ע' קצט. תקס\"ד ע' קסו. ע' קעא. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450591\" data-slug=\"or-hatorah-hb\" data-id=\"8316450591\">אוה\"ת</a> קדושים כרך ד ע' א'ס בשולי היריעה. ע' א'סא רפ\"ג. סה\"מ תרל\"ט ח\"ב ריש ע' תט. תרל\"ה ח\"ב ע' שנז. וש\"נ. תרמ\"ט ע' רנב. תר\"ן ע' שנג. תש\"ח ע' 205."],["3596","42","<b>המים אלו שבים . . עפר הארץ</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קעד: הארץ . . על התהום הגדול הוא הים אוקיינוס הסובבה מכל צד."],["3597","43","<b>המים . . כאשר בוקעי' . . מים חיים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370093\" data-slug=\"torah-or\" data-id=\"3901370093\">תו\"א תולדות כ, א</a>. ב. לעיל מאמר ד\"ה שלש רגלים תחוג לי ובהערה 143."],["3598","44","<b>מים מלוחים הם חסרון</b>: ראה גם אוה\"ת קדושים שם ע' א'סב."],["3599","45","<b>ולא תשבית מלח . . על כל קרבנך</b>: ויקרא ב, יג [בדילוג]."],["3600","46","<b>ברית מלח עולם</b>: קרח יח, יט."]]],[2001910363,"כו', שענין המלח הוא שנותן טעם<sup data-n=\"3601\">47</sup> בדבר הנמלח בו וכמו כאשר מולחי' בשר הנה ראשית פעולתו שמוציא את הדם<sup data-n=\"3602\">48</sup> שהוא בחי' פסולת, ואח\"כ נותן טעם בהבשר שבלא מלח א\"א לאכול וכמ\"ש היאכל תפל מבלי מלח<sup data-n=\"3603\">49</sup> שהמלח משלים הדבר ומקיימו כשמולחים לקיום, כך הנה יובן למעלה ששרש המלח הוא מבחי' טעמים<sup data-n=\"3604\">50</sup> שהוא גבוה מאד, וז\"ש מלח ברית אלקי' שממתיק הגבורות דש' אלקים<sup data-n=\"3605\">51</sup>, והענין הוא דאיתא בכתהאריז\"ל מלח כחשבון ג' שמות הוי'<sup data-n=\"3606\">52</sup>, ולכן נא' באהרן ברית מלח עולם, כי הכהנים מברכים את העם בג' שמות הוי' דיברכך יאר ישא<sup data-n=\"3607\">53</sup>, וא\"כ פי' ברית מלח שהמלח הוא ברית המקשר ומחבר בחי' ש' ה' בש' אלקים<sup data-n=\"3608\">54</sup> וזהו ברית אלקי' וז\"ע מה שמי הים הם מלוחים, כי הנה בש' אלקים יש ק\"ך צירופי'<sup data-n=\"3609\">55</sup> שיש בו ה' אותיות וכל אות יש בו ך\"ד צירופי'<sup data-n=\"3610\">56</sup>, והנה משני אותיות אחרונים שהם אותיות ים יכול להיות יניקה<sup data-n=\"3611\">57</sup> לחיצוני', וכמו מצרים מיצר ים<sup data-n=\"3612\">58</sup>, וזהו פעולת המלח שהוא בחי' טעם והיינו מבחי' חכמה<sup data-n=\"3613\">59</sup>, שבחכ' אתברירו<sup data-n=\"3614\">60</sup> שלא יהי' יניקה לחיצוני' ולכן מי הים מלוחי' כו', כדי שלא יהי' יניקה לחיצונים מבחי' ים אותיות אחרוני' דש' אלקים, והנה כאשר מי הים בוקעים את עפר הארץ אזי הם נעשים מים חיים, שבחי' מים חיים הם גבוהים יותר מבחי' מי הים וכמשארז\"ל שהמעיין מטהר<sup data-n=\"3615\">61</sup> אפי' טומאות חמורות זבין<sup data-n=\"3616\">62</sup> וזבות (ע' בב\"י ביו\"ד רסי' ר\"א<sup data-n=\"3617\">63</sup>)",[["3601","47","<b>המלח הוא שנותן טעם</b>: ברכות ה, סע\"א. מנחות כא, סע\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380089\" data-slug=\"likkutei-torah\" data-id=\"4001380089\">לקו\"ת ויקרא ג, סע\"ד</a>."],["3602","48","<b>מולחי' בשר . . שמוציא את הדם</b>: חולין קיג, א."],["3603","49","<b>היאכל תפל מבלי מלח</b>: איוב ו, ו."],["3604","50","<b>ששרש המלח . . טעמים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380090\" data-slug=\"likkutei-torah\" data-id=\"4001380090\">לקו\"ת ויקרא ד, א</a>. מאמרי אדה\"ז תקס\"ד ע' פז."],["3605","51","<b>שממתיק הגבורות דש' אלקים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380100\" data-slug=\"likkutei-torah\" data-id=\"4001380100\">לקו\"ת ויקרא ו, רע\"ג</a>."],["3606","52","<b>מלח כחשבון ג' שמות הוי'</b>: פע\"ח שער השבת שי\"ז, פי\"ז. שער הכוונות ענין השולחן. מאו\"א מערכת מלח אות עא. מק\"מ ויחי רמא, ב. לקו\"ת שם [ובכהאריז\"ל]. סידור שער בהמ\"ז ע' 202 ואילך. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע לט ואילך."],["3607","53","<b>בג' שמות הוי' דיברכך יאר ישא</b>: נשא ו, כד. כה. כו."],["3608","54","<b>שהמלח . . המקשר . . ה' בש' אלקים</b>: ראה גם לקו\"ת שם."],["3609","55","<b>בש' אלקים יש ק\"ך צירופי'</b>: ראה גם לעיל מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' הערה ג."],["3610","56","<b>ה' אותיות . . ך\"ד צירופי'</b>: ראה ס\"י פ\"ד, מי\"ב."],["3611","57","<b>משני אותיות . . ים . . יניקה</b>: ראה גם לעיל מאמר ד\"ה והנה תורה היא בחי' קו האמצעי ובהערה 274."],["3612","58","<b>מצרים מיצר ים</b>: פע\"ח שער חה\"מ שכ\"א, פ\"ז. ראה גם סה\"מ תרכ\"ז ע' שסז. וש\"נ."],["3613","59","<b>המלח . . חכמה</b>: ראה לקו\"ת ויקרא שם. ויש לציין שבסה\"מ תש\"ט ע' 189 מציין: ראה זח\"א רמ\"א, ב."],["3614","60","<b>שבחכ' אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר היכלות פקודי רנד, סע\"ב. ע\"ח שער דרושי נקודות ש\"ח, פ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550161\" data-slug=\"torat-chaim\" data-id=\"2300550161\">תו\"ח תשא ח\"ב שפד, ד</a> ואילך."],["3615","61","<b>שהמעיין מטהר</b>: בסה\"מ תרכ\"ט כאן ס\"ע קפ ואילך: שהמעיין מטהר ”בכל שהוא, וגם המעיין מטהר\". בכת\"י הר\"ש סופר כאן שהוא העתק סה\"מ הנ\"ל (עם הגהות בגוכתי\"ק) לא העתיק התיבות שבין המרכאות. ואולי זהו השמטת המעתיק מפני תיבות הדומות: מטהר . . מטהר. ולפ\"ז גם כאן צ\"ל כבסה\"מ הנ\"ל. וראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 66."],["3616","62","<b>שהמעיין מטהר . . זבין</b>: מצורע טו,יג. מקואות פ\"א, מ\"ח. רמב\"ם הל' מקואות פ\"א, ה\"ח."],["3617","63","<b>שהמעיין . . וזבות . . בב\"י . . ר\"א</b>: ד\"ה ומ\"ש ואפי' אינם. ראה גם סה\"מ תרל\"ט ח\"א ע' תט. אנציק' תלמודית מערכת זבה ע' תרעה הערה 283. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380481\" data-slug=\"likkutei-torah\" data-id=\"4001380481\">לקו\"ת שלח מב, ב</a> ובהערות וציונים לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221321\" data-slug=\"likkutei-sichot\" data-id=\"1300221321\">לקו\"ש מצורע כרך כב ע' 305</a>."]]],[2001910364,"ומצורעים<sup data-n=\"3618\">64</sup> וכן לקידוש מי חטאת<sup data-n=\"3619\">65</sup> אינו כ\"א מ\"ח דוקא, אבל מי הים יש דיעה שמי הים אינם אלא כמקוה<sup data-n=\"3620\">66</sup> ויש דיעה שמטהרים בזוחלים<sup data-n=\"3621\">67</sup>, אבל עכ\"ז אינם כמו מים חיים<sup data-n=\"3622\">68</sup>, וזהו הירידה צורך עלי', כי הנשמה כמו שהיתה למעלה היתה בבחי' ים שמי הים הם מלוחי' בחי' טעם דהיינו שהיתה בבחי' טעם והשגה באלקות, אבל אחר ירידתה בגוף יכולה לבא לבחי' מים חיים שגבוהים יותר מבחי' מי הים.\nד) <b>ולהבין</b> זה בעבודה, הנה יש ב' מיני אהבות, והם אהבה דבכל נפשך ואהבה דבכל מאדך<sup data-n=\"3623\">69</sup>, והנה אהבה שבכל נפשך היא אהבה שע\"פ טעם ושכל וכמשל הנפש שמחיה את הגוף, הנה אם האדם אינו בשלימות בריאותו ירצה מאד שיתפשט הנפש שנית להחיות את הגוף מפני שיודע שטוב לו יותר כו', וכמ\"כ יובן למעלה שהקב\"ה מחי' את כל העולם לכן הוא אוהב אותו וכמ\"ש לאהבה את ה' כי הוא חייך<sup data-n=\"3624\">70</sup> כו', אכן אהבת בכל מאדך היא אהבה שלמעלה מן הטעם ודעת שהיא בלי גבול<sup data-n=\"3625\">71</sup>, ואהבה זו היא באה דוקא כאשר הנפש מתלבשת בגוף דוקא כמו המים כאשר סותמים אותם<sup data-n=\"3626\">72</sup> לבלי יצאו הנה עי\"ז מתגברים המים יותר ושוברים הסתימה והולכים בתגבורת יותר כן ממש הנה הנפש כמו שהיא למעלה בגוף<sup data-n=\"3627\">73</sup> היתה בבחי' אהבה בכל נפשך, שהיא האהבה שע\"פ טעם שז\"ע מה שמי הים מלוחים כנ\"ל שמלח נותן טעם כו' ששרשו מבחי' טעמי' שבחכמה<sup data-n=\"3628\">74</sup> כו', אך לאחר ירידתה בגוף שמסתיר ומעלים ונמשל לעפר שמסתיר ומעלים, הנה כשבוקע את עפר הארץ דהיינו הגוף ונה\"ב המסתירים נעשה בחי' מים חיים שהיא אהבה שבכל מאדך שהיא בלי גבול בבחי' מס\"נ, ונמשלה אהבה זו לבחי' מים חיים היינו שכמו שהמים הנובעים מן המעיין הם נובעים תמיד כך הנה אהבה זו יכולה להיות בתמידות, וזהו מ\"ש זכור",[["3618","64","<b>שהמעיין . . ומצורעים</b>: מצורע יד, ה. נגעים רפי\"ד. מקואות שם. רמב\"ם שם. הל' טומאת צרעת רפי\"א."],["3619","65","<b>שהמעיין . . לקידוש מי חטאת</b>: חוקת יט, יז. מקואות שם. רמב\"ם הל' מקואות שם. הל' פרה אדומה רפ\"ו."],["3620","66","<b>שמי הים . . כמקוה</b>: ראה פרה פ\"ח, ה\"ח. מקואות פ\"ה, מ\"ד. רמב\"ם הל' פרה אדומה פ\"ו, ה\"י. מקואות פ\"ט, ה\"ח. הי\"ב."],["3621","67","<b>שמי הים . . שמטהרים בזוחלים</b>: ראה הערה שלפנ\"ז. שו\"ע יו\"ד הל' מקואות סר\"א, ס\"ה."],["3622","68","<b>אינם כמי מים חיים</b>: ראה לעיל הערה 66."],["3623","69","<b>אהבה דבכל נפשך . . דבכל מאדך</b>: ואתחנן ו, ה."],["3624","70","<b>לאהבה את ה' כי הוא חייך</b>: נצבים ל, כ [בדילוג]."],["3625","71","<b>אהבת בכל מאדך . . בלי גבול</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370179\" data-slug=\"torah-or\" data-id=\"3901370179\">תו\"א מקץ לט, ג</a>."],["3626","72","<b>המים כאשר סותמים אותם</b>: עד\"ז מובא בכ\"מ ומהם: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380690\" data-slug=\"likkutei-torah\" data-id=\"4001380690\">לקו\"ת מסעי צא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380941\" data-slug=\"likkutei-torah\" data-id=\"4001380941\">ר\"ה נה, ג</a>. אוה\"ת וישב ח\"ב ס\"ע 508. סה\"מ תרכ\"ט ע' מה. כאן ע' קפא. ע' שכג. תרל\"ט ח\"א ע' עד [נדפס גם בדרושי חתונה שלו ע' יד]. תר\"ם ח\"א ע' לז. ח\"ב ע' תקיד. ע' תשלט. ע' תתעט. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 73."],["3627","73","<b>שהיא למעלה בגוף</b>: בסה\"מ תרכ\"ט כאן: שהיתה למעלה."],["3628","74","<b>טעמי' שבחכמה</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. לקו\"ת חוקת נז, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' א'יט. מאמרי אדה\"א ויקרא ח\"ב ריש ע' תתלד. וש\"נ. דברים ח\"ד ע' א'תע. וש\"נ."]]],[2001910365,"אב נמשך אחריך כמים<sup data-n=\"3629\">75</sup> שאהבה זו היא כמים<sup data-n=\"3630\">76</sup> שנמשכים תמיד מן המעיין כי יש אהבה שהיא ברשפי אש והיא בחי' אהבה דבכל נפשך, אך הנה אהבה זו היא מחמת הטעם כנ\"ל ולכן בהחלף ההתבוננו' הנה חולף ועובר גם האה' הנולדה מההתבוננות, אבל בחי' אהבה זו שבכל מאדך יכולה להיות בתמידות בבחי' באר הנובעות תמיד מפני שהיא למעלה מן הטעם כו', וזהו לרוקע הארץ על המים שבחי' זו באה דוקא ע\"י בחי' ארץ הוא בחי' הגוף דוקא כדמיון המים כאשר בוקעים עפר הארץ נעשו מים חיים, כן הוא כאשר פועל בעבודתו להיות יוצא מהגוף במס\"נ באהבה דבכל מאדך היא יותר נעלה מכמו שהיתה קודם התלבשותה בגוף שהיתה בבחי' אהבה דבכל נפשך כו', והנה הבהמ\"ק נק' בשם באר כמ\"ש הרמב\"ן שענין הבארות שחפר יצחק<sup data-n=\"3631\">77</sup> זהו ענין המקדשי' בית ראשון ובית שני ע\"ש, והנה בבהמ\"ק היו מקריבין בהמה גשמי' ע\"ג המזבח והיו מעלים אותה ועכשיו תפלה כנגד תמידין תקנום<sup data-n=\"3632\">78</sup> ובתפלה הוא בחי' העלאת הנפש באהבה דבכל מאדך ולכן אומרים אחר שמו\"ע אליך ה' נפשי אשא<sup data-n=\"3633\">79</sup> שהוא בחי' מס\"נ אהבה דבכל מאדך, וזה\"ע עמוד העבודה שהוא בחי' העלאה מלמטלמ\"ע דוגמת עבודת הקרבנות<sup data-n=\"3634\">80</sup> שהי' מלמטלמ\"ע<sup data-n=\"3635\">81</sup>, וזהו בחי' רצוא, והוא בחי' קדוש הא'<sup data-n=\"3636\">82</sup> שהוא בחי' העלאה מלמטלמ\"ע ועי\"ז ממשיכין בחי' קדוש הא'.\nה) <b>והנה</b> אחר הרצוא הוא ענין השוב וכמ\"ש והחיות רצוא ושוב<sup data-n=\"3637\">83</sup>, והשוב הוא בחי' עמוד הגמ\"ח שהוא בד\"כ כל המצות שנקראים בדרך כלל בשם מצות הצדקה<sup data-n=\"3638\">84</sup> וחסד כו', כי הנה אנו מברכין אשר קדשנו במצותיו שע\"י המצות ממשיכים מבחי' אשר תענוג<sup data-n=\"3639\">85</sup> עליון, דהנה כתי' תחת אשר לא עבדת<sup data-n=\"3640\">86</sup> את ה' אלקיך בשמחה ובטוב לבב מרוב כל, פי' כי ענין עבודת המצות הוא יותר טוב מרוב כל, כי פי' כל",[["3629","75","<b>זכור אב נמשך אחריך כמים</b>: תפלת גשם."],["3630","76","<b>שאהבה זו היא כמים</b>: ראה גם לקו\"ת חוקת סג, א."],["3631","77","<b>כמ\"ש הרמב\"ן . . שחפר יצחק</b>: תולדות כו, כ [וכן צ\"ל בלקו\"ש דלהלן].\nנזכר גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080202\" data-slug=\"or-hatorah-hb\" data-id=\"8160080202\">אוה\"ת קדושים</a> שבהערה 41. (ויצא כרך א ע' רב. ע' 418). (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 74. סה\"מ תש\"ט ע' 191. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410180\" data-slug=\"likkutei-sichot\" data-id=\"1301410180\">לקו\"ש קדושים כרך ל ע' 116</a> ואילך."],["3632","78","<b>תפלה כנגד תמידין תקנום</b>: ראה ברכות כו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380630\" data-slug=\"likkutei-torah\" data-id=\"4001380630\">לקו\"ת פינחס עז, ג</a>."],["3633","79","<b>אליך ה' נפשי אשא</b>: תהלים כה, א."],["3634","80","<b>עמוד העבודה . . עבודת הקרבנות</b>: ראה אבות פ\"א, מ\"ב ובמפרשים שם. סה\"מ תרל\"ח ע' לד הערה 79."],["3635","81","<b>עבודת הקרבנות שהי' מלמטלמ\"ע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא פל\"ד</a>. לעיל מאמר ד\"ה וירא ישראל את היד הגדולה ובהערה 91."],["3636","82","<b>קדוש הא'</b>: ראה הערה בסה\"מ תרכ\"ט כאן ע' קפב. לעיל מאמר ד\"ה ונקדשתי בתוך בנ\"י ובהערה ב."],["3637","83","<b>והחיות רצוא ושוב</b>: יחזקאל א, יד."],["3638","84","<b>כל המצות . . מצות הצדקה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). לעיל מאמר ד\"ה [נקדישך] וביאור הענין ובהערה 51."],["3639","85","<b>אשר קדשנו במצותיו . . תענוג</b>: נוסח ברכת המצות. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370362\" data-slug=\"torah-or\" data-id=\"3901370362\">תו\"א</a> יתרו ע, ריש ע\"ב. שם תצוה פא, א. סה\"מ תר\"ם ח\"א ס\"ע נד. וש\"נ."],["3640","86","<b>תחת אשר לא עבדת</b>: תבוא כח, מז. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>. מאמרי אדה\"א נ\"ך ע' כז ואילך ובהנסמן שם."]]],[2001910366,"הוא עמוד<sup data-n=\"3641\">87</sup> המחבר געה\"ת וגעה\"ע<sup data-n=\"3642\">88</sup>, ופי' רוב כל היינו יש<sup data-n=\"3643\">89</sup> כמה בחי' ג\"ע התחתון וג\"ע העליון<sup data-n=\"3644\">90</sup> כמ\"ש במ\"א, ועשיי' המצות בגשמיות הוא יותר טוב מכל בחי' הג\"ע כי אף שהג\"ע הוא תענוג נפלא מאד, וכמשארז\"ל מוטב דלידייני'<sup data-n=\"3645\">91</sup> וליתי לעלמא דאתי שכדאי כל יסורי גיהנם בכדי לבוא לבחי' ג\"ע, אך עכ\"ז הנה המצות בגשמיות הוא יותר טוב מכל תענוג שבג\"ע, וזהו כמשארז\"ל יפה שעה אחת<sup data-n=\"3646\">92</sup> בתשובה ומעש\"ט בעוה\"ז מכל חיי העוה\"ב, כי בעוה\"ב בג\"ע התשלום שכר הוא רק הארה מבחי' המצוה כנודע ולא המצוה עצמה אכן למטה בעשיית המצוה הנה הוא עושה כל המצוה כו', וזהו לרוקע הארץ דוקא שבחי' זו היא ג\"כ בארץ דוקא, כי המלאכים ביקשו שינתן להם התורה והיינו שביקשו שיותן להם פנימית התורה<sup data-n=\"3647\">93</sup> היינו כי ל\"ב חוטי הציצית רומזים לל\"ב נתיבות החכ'<sup data-n=\"3648\">94</sup> ורצו שישיגו בחי' ל\"ב נתיבות החכ' כו' וכדומה, ולא ניתן להם כ\"א ניתנה למטה בארץ דוקא, והיינו מפני שמה שהוא גבוה מאד הנה הוא נשפל למטה מאד<sup data-n=\"3649\">95</sup>, וכמו משל האותיות כאשר הם חקוקי' על האבן טוב הנה מחמת בהירות האבן טוב אינם ניכרים כלל כ\"א כאשר חותמים אותם על השעוה אז הם ניכרים דוקא, או כמו משל ראי' ושמיעה<sup data-n=\"3650\">96</sup> שכח הראי' הוא רוחני יותר מכמו השמיעה, וכמשארז\"ל אינו דומה שמיעה לראי'<sup data-n=\"3651\">97</sup> שכח הראי' נעלה יותר ואעפ\"כ הנה כח הראי' תופס דבר גשמי דוקא ולא רוחני כמו כח השמיעה שאינו תופס כ\"א דבר רוחני שהוא הקול כו', והיינו מפני שכל שהוא רוחני יותר הוא",[["3641","87","<b>כל הוא עמוד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370447\" data-slug=\"torah-or\" data-id=\"3901370447\">תו\"א מג\"א ק, סע\"ב</a> ואילך [במהדורת קה\"ת תשט\"ו. ובמהדורות שלאח\"ז ק, ג] ”ועמש\"ל ע\"פ ואתה תצוה שהעמוד נק' ג\"כ כל וזהו ענין מרוב כל\". ראה שם פא, ב [ד\"ה והנה] ואילך. מאמרי אדה\"ז תקס\"ז ע' סח. סה\"מ תרכ\"ט כאן ע' קפב."],["3642","88","<b>עמוד המחבר געה\"ת וגעה\"ע</b>: ראה תו\"א מג\"א ק, סע\"ב. וש\"נ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשעג ובהנסמן במ\"מ לשם. מאמרי אדה\"א נ\"ך ס\"ע תעו. וש\"נ."],["3643","89","<b>יש</b>: אוצ\"ל: שיש. בסה\"מ תרכ\"ט כאן ע' קפב תקנו המו\"ל בפנים: [כי] יש."],["3644","90","<b>כמה בחי' ג\"ע . . העליון</b>: ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן בהערה 85."],["3645","91","<b>מוטב דלידייני'</b>: חגיגה טו, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תערב ובהנסמן במ\"מ לשם. תקס\"ז ע' שכ. מאמרי אדה\"א שמות ח\"ב ע' שטז. דברים ח\"א ע' נט."],["3646","92","<b>יפה שעה אחת</b>: אבות פ\"ד, מי\"ז."],["3647","93","<b>המלאכים ביקשו . . פנימית התורה</b>: שבת פח, ב. ראה גם ביאוה\"ז בראשית א, סע\"ד ואילך. ולהצ\"צ שם כרך ב ע' תריב ואילך. מאמרי אדה\"ז תק\"ע ע' צח. מאמרי אדה\"א במדבר ח\"א ע' מה. דברים ח\"ד ע' א'תעא. לעיל סוף מאמר ד\"ה שלש רגלים תחוג לי ולקמן (בחלק ההנחות) בהנחה שם. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 92. סה\"מ תרכ\"ז ע' רפז. תרכ\"ט ע' ק. כאן ע' קפג. ע' רכב. תרל\"א ח\"א ע' קסח. תרל\"ט ח\"ב ע' תח. תר\"ם ח\"ב ע' תרד. ע' תשפו. סה\"מ תרצ\"ז ע' 262."],["3648","94","<b>ל\"ב חוטי הציצית . . החכ'</b>: ראה זח\"ג תוספת שא, א. בחיי שלח טו, לח ד\"ה וע\"ד הקבלה (ירושלים תשל\"ב ס\"ע קא). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקטז ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380523\" data-slug=\"likkutei-torah\" data-id=\"4001380523\">לקו\"ת קרח נב, ב</a>. ד."],["3649","95","<b>שמה שהוא גבוה מאד. . למטה מאד</b>: ראה שערי אורה שער הפורים נח, א. סה, א. סה\"מ תרל\"ח ע' תב. וש\"נ."],["3650","96","<b>משל ראי' ושמיעה</b>: ראה מאמרי אדה\"ז תקס\"ט ע' פט ובהנסמן במ\"מ לשם ובריש המאמר שם. המשך וככה תרל\"ז פל\"ג. פנ\"ז. סה\"מ תרכ\"ט כאן ע' קפג. וש\"נ."],["3651","97","<b>אינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לק\"ט שלח יג, יח. סה\"מ תר\"ם ח\"א ע' כד. וש\"נ."]]],[2001910367,"משפיל למטה ביותר, כך הנה המצות מחמת שהם גבוהים בשרשן מאד א\"א להם להיות נגלי' למעלה למלאכים כ\"א למטה דוקא בארץ לנשמות כו', וזהו לרוקע הארץ על המים כל\"ח שהוא בחי' המשכת החסדים שבדרך כלל נק' התורה ג\"כ בשם חסד<sup data-n=\"3652\">98</sup> וכמ\"ש פיה פתחה בחכמה ותורת חסד על לשונה<sup data-n=\"3653\">99</sup> כו', וזהו בחי' קדוש הב' שנמשך ע\"י המצות.\nוא\"ו) <b>וזהו</b> מה שתרגם על הפסוק קק\"ק קדיש בשמי מרומא עילאה בית שכינתי' והיינו קדוש הא' שהוא בחי' העלאה מלמטלמ\"ע, ועי\"ז נמשך המשכה למעלה וזהו בשמי מרומא עילאה בית שכינתי', וקדוש הב' הוא בחי' המשכה מלמעלה למטה, וזהו מה שתרגם קדיש על ארעא עובד גבורתי' שהוא בחי' המשכה למטה בארץ, קדיש לעלם ולעלמי עלמיא זהו בחי' קדוש הג' שהוא בחי' קדוש דתורה, והיינו שכדי שיכול להיות ההעלאה מלמטלמ\"ע וההמשכה מלמעלמ\"ט צ\"ל כח ע\"ז מלמעלה, הן אמת שע\"י שבוקעים את עפר הארץ דהיינו הגוף נעשה בחי' מים חיים, אך הכח ע\"ז שיוכל לבקוע את עפר הארץ הוא הגוף צ\"ל כח ע\"ז מלמעלה, וכמו\"כ בענין ההמשכה ע\"י המצות זהו מעלת ומדרגת התורה, כי התו' יש בה בחי' העלאה ובחי' המשכה<sup data-n=\"3654\">100</sup>, כי הנה בתורה יש דבור התורה ובחי' עיון התורה<sup data-n=\"3655\">101</sup>, דבור התורה הוא בחי' המשכה ועיון התורה הוא בחי' העלאה<sup data-n=\"3656\">102</sup>, כי העיון הוא שמקשר שכלו ומחשבתו בתורה, ובדרך כלל הוא בחי' תושב\"כ ותושבע\"פ, תושב\"כ בחי' דבור וכמ\"ש וידבר לאמר<sup data-n=\"3658\">104</sup> כו' ותושבע\"פ העיקר הוא בבחי' עיון<sup data-n=\"3657\">103</sup> כו', וזהו הנותן כח לבוא לבחי' ההעלאה הוא בחי' עיון התורה והנותן כח לבוא לבחי' המשכה דמצות זהו בחי' דבור התורה כו', וזהו קדיש לעלם ולעלמי עלמיא שכח זה ניתן לעלם ולעלמי עלמיא פי' שניתן כח זה לדורות ע\"י התורה כדי שיוכל להיות בחי' העלאה והמשכה כו', וכמ\"ש במ\"א בפי' לאמר שבעשה\"ד שלכאו' הוא מיותר<sup data-n=\"3659\">105</sup> שהרי כל ישראל שמעו עשה\"ד, אלא שזהו הכח לדורות<sup data-n=\"3660\">106</sup> ע'",[["3652","98","<b>נק' התורה ג\"כ בשם חסד</b>: ראה סוכה מט, ב."],["3653","99","<b>פיה פתחה בחכמה ותורת חסד על לשונה</b>: משלי לא, כו."],["3654","100","<b>התו' . . העלאה ובחי' המשכה</b>: ראה גם דרך חיים שער התפלה נד, ב. שערי אורה שער הפורים צא, א. מאמרי אדה\"א דברים ח\"ד ס\"ע א'תסו ואילך. פלח הרמון בחוקותי ע' תקיז."],["3655","101","<b>דבור התורה ובחי' עיון התורה</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. מאמרי אדה\"א בראשית ע' תקכז. וש\"נ. קונטרסים ע' תקמב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540569\" data-slug=\"torat-chaim\" data-id=\"2300540569\">תו\"ח בשלח ח\"א קסט, ב</a>. וש\"נ."],["3656","102","<b>דבור . . המשכה ועיון . . העלאה</b>: ראה גם סה\"מ תרל\"ט ח\"ב ע' תיב ואילך. פלח הרמון בחוקותי שם."],["3658","104","<b>תושב\"כ . . דבור . . וידבר לאמר</b>: יתרו כ, א. ראה גם בהערות הבאות. לעיל מאמר ד\"ה וענין מתיבתא דרקיע ובהערה 35. ד\"ה להבין ענין טהרת המצורע וכו' זאת תהי' תורת המצורע ובהערה 56."],["3657","103","<b>תושב\"כ . . דבור . . ותושבע\"פ . . עיון</b>: ראה הל' ת\"ת שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380095\" data-slug=\"likkutei-torah\" data-id=\"4001380095\">לקו\"ת ויקרא ה, ב</a> ואילך. מאמרי אדה\"א בראשית ע' תקכז. שערי תשובה שער התפלה לט, ב. פלח הרמון בחוקותי שם. וראה גם שערי תשובה חינוך קכא, ב ואילך."],["3659","105","<b>לאמר שבעשה\"ד שלכאו' הוא מיותר</b>: ראה גם (בנוסף להמצויין בפנים) חזקוני וברטנורא שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381289\" data-slug=\"likkutei-torah\" data-id=\"4001381289\">לקו\"ת שה\"ש מ, ב</a>."],["3660","106","<b>שזהו הכח לדורות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381296\" data-slug=\"likkutei-torah\" data-id=\"4001381296\">לקו\"ת שה\"ש מב, סע\"א</a>."]]],[2001910368,"בהגהות<sup data-n=\"3661\">107</sup> לד\"ה בחדש השלישי* שבת\"א פ' יתרו<sup data-n=\"3662\">108</sup>. וזהו קדושים תהיו כי קדוש אני, פי' כי קדוש אני הוא בחי' הנותן כח בכם שתוכלו להיות קדושים, והוא בחי' עמוד התורה הנותן כח שיוכל להיות ב\"פ קדוש ע\"י העלאה והמשכה כנ\"ל, וזהו פי' א' בפי' כי קדוש אני, וא\"כ לא קשה מידי מהו דמיון הערך קדושים תהיו לבחי' כי קדוש אני, כי בחי' קדוש אני הוא הנותן כח שתוכלו להיות בחי' קדושים כו'. ואפ\"ל שג\"פ קדוש זהו ענין ג' פרשיות של ק\"ש<sup data-n=\"3663\">109</sup>, פ' ראשונה הוא בחי' העלא' ש'<sup data-n=\"3665\">111</sup> מ\"ב<sup data-n=\"3664\">110</sup> וכמ\"ש בזהר שש' מ\"ב עולה ואינו יורד<sup data-n=\"3666\">112</sup>, ופ' שני' הוא בחי' המשכה ש'<sup data-n=\"3668\">114</sup> ע\"ב<sup data-n=\"3667\">113</sup>, ופ' ציצית הוא כנגד עמוד התורה הנותן כח שכתי' בה אני ה' אלקיכם<sup data-n=\"3669\">115</sup> אשר הוצאתי אתכם מאמ\"צ, פי' אני הוא שנתתי בכם כח שתוכלו לצאת ממ\"ט שע\"ט<sup data-n=\"3670\">116</sup> שהייתם באמ\"צ כו', ואמנם ע\"פ המדרש הנ\"ל במשל למלך כו' נטל עטרה א' ונתנה בראשו ושנים בראש בניו, צ\"ל מ\"ש כי קדוש אני קאי על עמוד העבודה שהוא בחי' העלאה בכל מאדך ואינו נמשך מהעלאה זו למטה כלל כ\"א ע\"י העלאה זו נמשך למעלה, וזהו נטל עטרה א' דהיינו בחי' קדוש א' לעצמו, שז\"ע שליש הרויח שמקבל המלוה כו', ושנים בראש בניו שהם ב' בחי' קדוש דהיינו בחי' קדוש דתורה וקדוש דגמ\"ח הם בחי' המצות כנ\"ל, ולפ\"ז פי' קדושים תהיו כי קדוש אני שמפני שאתם צריכים להמשיך אותו ית' שאני קדוש, לכן תהיו אתם קדושים שתהיו כלי להמשכה זו, וע' בדרוש בהרת ספ\"ג בס' רל\"ה דקפ\"ז<sup data-n=\"3671\">117</sup>**, והכח שיש\n\n*)נרשם בכת\"י מעתיק בשולי היריעה (אחרי הערה שלאח\"ז) ללא ציון מקומו בפנים, ואולי שייך כאן:\nלהעיר מענין לאמר שבעשה\"ד כמ\"ש בד\"ה בחדש השלישי.\n**)נרשם בשולי היריעה (בכת\"י מעתיק) ללא ציון מקומו בפנים, ואולי שייך כאן:\nוע' בס' רלה בדרוש בהרת ספ\"ג דקפ\"ז שפי' קדושים תהיו כו' כי קדוש אני שמפני שאתם צריכים להמשיך אותו ית' שאני קדוש לכן תהיו אתם קדושים שתהיו בחי' כלי להמשכה זו.",[["3661","107","<b>בהגהות</b>: אולי הכוונה לאוה\"ת יתרו ע' תשפג-תשפה."],["3662","108","<b>שבת\"א פ' יתרו</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א יתרו סז, ב</a>."],["3663","109","<b>שג\"פ קדוש . . ג' פרשיות של ק\"ש</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 110. סה\"מ תרכ\"ט כאן ע' קפד. סה\"מ תרל\"ט ח\"ב ע' תיג."],["3665","111","<b>ש' מ\"ב</b>: ראה זהר תרומה קלב, ב. ועוד. פרדס שער פרטי השמות שכ\"א, פי\"ב. פי\"ג. מכתב להרב בראנדט נדפס ברשימות חוברת מא (לפ' אחו\"ק). מאמרי אדה\"א שמות ח\"א ע' קמא. וש\"נ."],["3664","110","<b>פרשה ראשונה . . ש' מ\"ב</b>: ראה פע\"ח שער הק\"ש ש\"ח, פי\"ח. לקו\"ת ואתחנן יב, ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. ע' תשכ. נדפסו גם במאמרי אדה\"ז תקס\"ו מהדורת תשס\"ד ח\"א ע' א. ע' טו. שם ע' יז. סידור שער הק\"ש עג, ג. מאמרי אדה\"א שמות ח\"א ע' רעו ואילך. אמרי בינה שער הק\"ש פמ\"ה. ספר המצות להצ\"צ ע' קכ."],["3666","112","<b>בזהר שש' מ\"ב עולה ואינו יורד</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380707\" data-slug=\"likkutei-torah\" data-id=\"4001380707\">לקו\"ת מסעי צה, ד</a>: ”ואפשר שזהו פי' מ\"ש בזהר תרומה (דקל\"ב, ב) מ\"ב סליק ולא נחית\". סה\"מ תרל\"א ח\"א ע' עה. וש\"נ."],["3668","114","<b>ש' ע\"ב</b>: ראה זהר תרומה קלב, ב. ועוד. פרדס שער פרטי השמות שכ\"א, פ\"ה. מכתב להרב בראנדט נדפס ברשימות חוברת מא (לפ' אחו\"ק)."],["3667","113","<b>ופ' שני' . . ש' ע\"ב</b>: ראה לעיל הערה 110."],["3669","115","<b>אני הוי' אלקיכם</b>: שלח טו, מא."],["3670","116","<b>מאמ\"צ . . לצאת ממ\"ט שע\"ט</b>: ראה ז\"ח יתרו לא, א. סה\"מ תר\"ם ח\"א ע' קמב. וש\"נ."],["3671","117","<b>בדרוש בהרת . . דקפ\"ז</b>: סה\"מ תרל\"ה ח\"א ע' רכד. הועתק גם לעיל במאמר ד\"ה בגמ' כו' קא מפלגי במתיבתא דרקיע ספ\"ב."]]],[2001910369,"בנש\"י שיכולים לקבל ב' בחי' קדוש אלו זהו מפני שהם בני ישראל, וזהו מ\"ש כאן דבר אל כל עדת בנ\"י<sup data-n=\"3672\">118</sup>, פי' כי האבות נקראים ישראל כמשנ\"ת לעיל<sup data-n=\"3674\">120</sup> ממארז\"ל במד\"ר<sup data-n=\"3673\">119</sup> שאברהם נק' ישראל ממ\"ש ומושב בנ\"י אשר ישבו במצרים ארבע מאות ושלשים שנה<sup data-n=\"3675\">121</sup>, והתחלת החשבון הוא מאברהם<sup data-n=\"3676\">122</sup>, א\"כ נק' אברהם ישראל, וכמו\"כ יצחק כו' יעו\"ש, ופי' ישראל הוא ל' שררה מל' כי שרית עם אלקים<sup data-n=\"3677\">123</sup> שהוא בחי' ש' הוי' המושל על ש' אלקים<sup data-n=\"3678\">124</sup>, כי האבות היו מרכבה<sup data-n=\"3679\">125</sup> לבחי' חג\"ת<sup data-n=\"3680\">126</sup> שלמעלה מבחי' ש' אלקים כו' ונש\"י הם בנ\"י לכן הם הזוכים לקבל ב' בחי' קדוש אלו, וע\"פ הקבלה הנה ג\"פ קדוש<sup data-n=\"3681\">127</sup> אלו הם כתר דאריך וכתר דז\"א וכתר דמל', והנה פי' עטרה א' שנטל לעצמו הוא בחי' כתר דאריך שנמשך ע\"י בחי' בכל מאדך שהיא מגעת בעצמיות אוא\"ס, כי מאד היא בלי גבול<sup data-n=\"3682\">128</sup> ולכן מגיע לבחי' אוא\"ס שלמעלה מבחי' גבול, ושנים שנתן בראש בניו הם בחי' כתר דז\"א וכתר דנוק', וישראל מפני שהם בני ישראל בחי' אבות הם המרכבה לבחי' חג\"ת לכן הם הזוכים לקבל בחי' כתר דז\"א וכתר דמל'.",[["3672","118","<b>דבר אל כל עדת בנ\"י</b>: קדושים יט, ב."],["3674","120","<b>כמשנ\"ת לעיל</b>: במאמר ד\"ה וידבר כו' קדושים תהיו על יד הערה 25 ואילך."],["3673","119","<b>האבות נקראים ישראל . . במד\"ר</b>: ב\"ר פס\"ג, ג. ראה גם ילקוט שמעוני ר\"פ תולדות רמז קי."],["3675","121","<b>ומושב בנ\"י . . שנה</b>: וכ\"ה בסה\"מ תרכ\"ט כאן ע' קפד (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וידבר כו' קדושים תהיו על יד הערה 21 — בא יב, מ [ושם: שלשים שנה וארבע מאות שנה]."],["3676","122","<b>והתחלת החשבון הוא מאברהם</b>: ראה מכילתא ולק\"ט בא שם. רש\"י מגילה ט, א־ בא ובב\"ר שם."],["3677","123","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["3678","124","<b>ש' הוי' המושל על ש' אלקים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380606\" data-slug=\"likkutei-torah\" data-id=\"4001380606\">לקו\"ת בלק עב, סע\"א</a>."],["3679","125","<b>האבות היו מרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670263\" data-slug=\"torat-chaim\" data-id=\"2300670263\">תו\"ח נח מט, ד</a> ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["3680","126","<b>האבות . . חג\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540325\" data-slug=\"torat-chaim\" data-id=\"2300540325\">תו\"ח וארא ח\"א סא, ד</a>. וש\"נ."],["3681","127","<b>וע\"פ הקבלה הנה ג\"פ קדוש</b>: ראה גם סה\"מ תרכ\"ט כאן ע' קפה. וש\"נ."],["3682","128","<b>מאד היא בלי גבול</b>: ראה אגה\"ק סי\"ז. סה\"מ תר\"ם ח\"א ע' תכט. וש\"נ. לעיל הערה 71."]]],[2001910370,"<h3>כי תבואו וכו' ושבתה</h3>\n<b>בס\"ד ש\"פ בהר</b>\n<b>כי</b> תבואו אל הארץ ושבתה<sup data-n=\"3684\">2</sup> הארץ<sup data-n=\"3683\">1</sup> כו', שש שנים תזרע כו' ושש שנים תזמור<sup data-n=\"3685\">3</sup> כו' ובשנה השביעית שבת שבתון<sup data-n=\"3686\">4</sup> כו', וצ\"ל שמשמע שמיד כי תבואו אל הארץ תשבות הארץ קודם השש שנים של זריעה, ובאמת אינו כן כ\"א כמ\"ש אח\"ז שש שנים תזרע כו', ובשנה השביעית שבת שבתון. אך הענין יובן בהקדם מה שצ\"ל מפני מה הי' א\"י תחלה תחת כנען שלכן נק' ארץ כנען<sup data-n=\"3687\">5</sup>, הלא בכנען כתי' ארור כנען עבד עבדים יהי'<sup data-n=\"3688\">6</sup> כו' וא\"כ מפני מה היתה תחלה תח\"י כנען ולא של שם<sup data-n=\"3689\">7</sup> ויפת שהם חשובים יותר מחם אבי כנען<sup data-n=\"3690\">8</sup>. והענין הוא דהנה ארז\"ל על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח<sup data-n=\"3691\">9</sup>, והנה פעם מצינו בדברי רז\"ל שמעלת התורה גדלה על בחי' העבודה וגמ\"ח, כי העבודה הוא<sup data-n=\"3693\">11</sup> בחי' עבודת הקרבנות<sup data-n=\"3692\">10</sup> ועכשיו תפלות כנגד תמידין תקנו<sup data-n=\"3694\">12</sup>, ומצינו שארז\"ל אלו דברים שאוכל פירותיהם בעוה\"ז, כיבוד אב ואם וגמ\"ח, ופי' רש\"י ז\"ל בשבת בפ' מפנין דקך\"ז<sup data-n=\"3696\">14</sup> שעיון תפלה בכלל גמ\"ח ע\"ש הכתוב גומל נפשו איש חסד<sup data-n=\"3697\">15</sup>, ות\"ת כנגד כולם<sup data-n=\"3695\">13</sup>, וא\"כ ת\"ת גדולה",[["3684","2","<b>כי תבואו אל הארץ ושבתה הארץ</b>: בהר כה, ב [בדילוג]."],["3683","1","<b>כי תבואו . . ושבתה הארץ</b>: מכאן מתחיל המשך של ד' מאמרים, ממאמר ד\"ה זה שנדפס בסה\"מ תרכ\"ז ע' רפא ואילך. מאמר זה הוא חלקו הראשון של מאמר זה שנדפס בסה\"מ תרכ\"ז (ע' רפא-רפה היינו עד אמצע פ\"ה) עם הוספות. וש\"נ. המשך המאמר דתרכ\"ז הוא בהמאמרים דלקמן ד\"ה אר\"א אר\"ח ת\"ח מרבים שלום־ ד\"ה כל אשר חפץ ה' עשה־ ד\"ה בעש\"מ נבה\"ע.\nהמאמר דתרכ\"ז נרשם עוה\"פ בבוך זה בכת\"י מעתיק, וניתוספו בו שני הגהות בגוכתי\"ק (אחת לקמן בפ\"ג, ואחת בשולי היריעה לפ\"ט ולא נדפסה עדיין), וכן ניתוסף שלשה עמודים בגוכתי\"ק שכולל הגהות, וכן סיום למאמר זה (היינו עד אמצע פ\"ה כנ\"ל), בכותרת: ”לד\"ה כי תבואו אל הארץ דתקס\"ב\". והועתק כל הנ\"ל עוה\"פ (היינו ששולבו ההוספות בהמאמר עד אמצע פ\"ה) בכת\"י מעתיק, בתוספות שתי הגהות בגוכתי\"ק. (פרט לשולי הגליונות שלא הועתקו — נדפסו בסה\"מ תרכ\"ז שם].\nמאמר זה הובא לקמן במאמר ד\"ה בעשרה מאמרות נבה\"ע על יד הערה 17.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו [ומשם נעתקה הכותרת שמופיע בריש המאמר ש\"פ בהר]."],["3685","3","<b>שש שנים תזרע . . תזמור</b>: בהר שם, ג."],["3686","4","<b>ובשנה השביעית שבת שבתון</b>: שם כה, ד."],["3687","5","<b>ארץ כנען</b>: לך יז, ח. ועוד. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370125\" data-slug=\"torah-or\" data-id=\"3901370125\">תו\"א וישב כו, ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560071\" data-slug=\"or-hatorah-hb\" data-id=\"8316560071\">אוה\"ת שם ס\"ע 502</a>."],["3688","6","<b>ארור כנען . . יהי'</b>: נח ט, כה."],["3689","7","<b>תחילה תח\"י כנען ולא של שם</b>: ראה תו\"כ ס\"פ קדושים (כ, כד) עה\"פ ואני אתננה לכם לרשת אותה (ובפי' הראב\"ד שם אות טז). יל\"ש שם רמז תרכו. לקח טוב שם. פיוט אהללה אלקי במוסף יום ב' דר\"ה [בברכת מלכיות — אחר אוחילה לאל]. רש\"י לך יב, ו. חזקוני־ רא\"ם־ לבוש־ ושפ\"ח שם. תוספות השלם שם אותיות ז־ ט-י־ יב-יד.\nבנידון התו\"כ שנזכר לעיל יש לציין שבתו\"כ עם פי' קרבן אהרן. וכן בתו\"כ עם פי' הראב\"ד ליתא."],["3690","8","<b>מחם אבי כנען</b>: נח ט, יח. כב."],["3691","9","<b>על שלשה דברים . . גמ\"ח</b>: אבות פ\"א, מ\"ב."],["3693","11","<b>הוא</b>: בסה\"מ תרכ\"ז כאן: היא."],["3692","10","<b>העבודה . . עבודת הקרבנות</b>: ראה אבות שם ובמפרשים שם. סה\"מ תרל\"ח ע' לד הערה 79."],["3694","12","<b>תפלות כנגד תמידין תקנו</b>: ראה ברכות כו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380630\" data-slug=\"likkutei-torah\" data-id=\"4001380630\">לקו\"ת פינחס עז, ג</a>."],["3696","14","<b>ופי' רש\"י ז\"ל בשבת בפ' מפנין דקך\"ז</b>: ריש ע\"ב ד\"ה ה\"ג."],["3697","15","<b>גומל נפשו איש חסד</b>: משלי יא, יז. ראה גם סה\"מ תרל\"ח ע' מב ואילך ובהנסמן שם."],["3695","13","<b>אלו דברים . . ות\"ת כנגד כולם</b>: ראה פאה פ\"א, מ\"א."]]],[2001910371,"יותר מבחי' תפלה וגמ\"ח, ופעם אמר ר\"י והלואי יתפלל אדם<sup data-n=\"3698\">16</sup> כל היום כולו, וא\"כ ממילא לא ילמד תורה ואעפ\"כ הלואי שיתפלל אדם כל היום כולו וא\"כ תפלה גדולה מבחי' התורה, (וכן מצינו שאמר אבא בנימין בפ\"ק דברכות ד\"ה סע\"ב, על שני דברים הייתי מצטער כל ימי על תפלתי שתהא סמוכה למטתי<sup data-n=\"3699\">17</sup>, ופרש\"י<sup data-n=\"3700\">18</sup> כל ימי נזהרתי שלא לעשות מלאכה ושלא לעסוק בתורה עד שאקרא ק\"ש ואתפלל, וכן קודם לימוד התורה מותר לאכול<sup data-n=\"3701\">19</sup> כמ\"ש בש\"ע או\"ח סי' קנ\"ה סעי' ב', משא\"כ קודם התפלה אסור לאכול<sup data-n=\"3702\">20</sup>, כמ\"ש לא תאכלו על הדם<sup data-n=\"3703\">21</sup> וארז\"ל קודם שתתפללו על דמכם, וכתי' חדלו לכם מן האדם אשר נשמה באפו<sup data-n=\"3704\">22</sup>, שנת' מזה במ\"א שקודם התפלה עדיין נשמה באפו כו' ע' בד\"ה אין עומדין להתפלל<sup data-n=\"3705\">23</sup> אלא מתוך כובד ראש, שמכ\"ז מובן שגדלה מעלת התפלה על התורה), ופעם כתיב חסד חפצתי ולא זבח (בהושע סי' וא\"ו<sup data-n=\"3706\">24</sup>) א\"כ גמ\"ח גדולה מבחי' זבח שהוא בחי' תפלה, וכן ארז\"ל ביבמות דק\"ה ע\"א ע\"פ אם יתכפר עון בית עלי בזבח ומנחה<sup data-n=\"3707\">25</sup>, ואמרו שם רבה ואביי בזבח ומנחה אינו מתכפר אבל מתכפר בתורה וגמ\"ח<sup data-n=\"3708\">26</sup> [והיינו כי התורה נק' ג\"כ חסד<sup data-n=\"3709\">27</sup> כמ\"ש פיה פתחה בחכ' ותורת חסד על לשונה<sup data-n=\"3710\">28</sup> שנק' התורה תורת חסד], רבה ואביי מבית עלי קאתו רבה דעסיק בתורה חי מ' שנין<sup data-n=\"3711\">29</sup>, ואביי דעסיק בתורה וגמ\"ח חי ס' שנין, ע' בר\"ה דף י\"ח שאביי סובר שצ\"ל תורה וגמ\"ח, א\"כ בחי' תורה וגמ\"ח גדולים מבחי' זבח ומנחה שהם בחי' תפלה כו'.\nב) <b>ולהבין</b> ענין ג' בחי' אלו תורה ועבודה וגמ\"ח שעליהם העולם עומד, צ\"ל מ\"ש וכל בניך למודי הוי'<sup data-n=\"3712\">30</sup> ורב שלום בניך, וארז\"ל א\"ת בניך אלא בוניך<sup data-n=\"3713\">31</sup>, ואיתא בשל\"ה ממה למדו זה שא\"ת בניך אלא בוניך<sup data-n=\"3714\">32</sup> ממה שכתי' ב\"פ בניך דהל\"ל",[["3698","16","<b>והלואי יתפלל אדם</b>: ראה ברכות כא, א."],["3699","17","<b>אבא בנימין . . סמוכה למטתי</b>: ראה גם לעיל מאמר ד\"ה וענין מתיבתא דרקיע ובהערות 33-34. ד\"ה להבין ענין טהרת המצורע וכו' זאת תהי' תורת המצורע ובהערות 54-55."],["3700","18","<b>ופרש\"י</b>: ד\"ה סמוך למטתי — בדילוג."],["3701","19","<b>קודם לימוד התורה מותר לאכול</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשמז."],["3702","20","<b>קודם התפלה אסור לאכול</b>: ברכות י, ב. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 124."],["3703","21","<b>לא תאכלו על הדם</b>: קדושים יט, כו. ברכות י, ב. ראה גם לעיל שם ובהערה 125."],["3704","22","<b>חדלו לכם מן האדם . . באפו</b>: ישעי' ב, כב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380639\" data-slug=\"likkutei-torah\" data-id=\"4001380639\">לקו\"ת פינחס עט, ד</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תשנז. וש\"נ. הנחות תקע\"ז ע' טו. וש\"נ."],["3705","23","<b>בד\"ה אין עומדין להתפלל</b>: ראה גם אוה\"ת על מארז\"ל ע' יד. ע' יט. ע' כג."],["3706","24","<b>חסד חפצתי . . בהושע סי' וא\"ו</b>: פסוק ו. ראה סה\"מ תרל\"ח ע' לד ואילך. סה\"מ מלוקט ו' ע' צט ואילך."],["3707","25","<b>אם יתכפר. . ומנחה</b>: שמו\"א ג, יד [ושם: ובמנחה — אבל כ\"ה גם בסה\"מ תרכ\"ז כאן ע' רפב]."],["3708","26","<b>רבה ואביי . . בתורה וגמ\"ח</b>: כ\"ה גם בסה\"מ תרכ\"ז שם. אבל ראה בשולי הגליון שם."],["3709","27","<b>התורה נק' ג\"כ חסד</b>: ראה סוכה מט, ב."],["3710","28","<b>פיה פתחה בחכ' ותורת חסד על לשונה</b>: משלי לא, כו."],["3711","29","<b>רבה . . חי מ' שנין</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' פב בהערה."],["3712","30","<b>וכל בניך למודי הוי'</b>: ישעי' נד, יג."],["3713","31","<b>א\"ת בניך אלא בוניך</b>: ברכות סד, א."],["3714","32","<b>ואיתא בשל\"ה . . אלא בוניך</b>: בסה\"מ תרנ\"ט ריש ע' קמב מציין: ד' נ\"ג ע\"א. בסה\"מ תרפ\"ט ע' 71 מציין: תושבע\"פ כלל אל תקרי דת\"ג ע\"א. בסה\"מ תש\"ד ע' 66 מציין: דת\"ג ע\"א. ולכאורה צ\"ל כבאוה\"ת ישעי' כרך ב ע' תתלג: בתשבע\"פ דף ת\"ג ע\"ב."]]],[2001910372,"וכל בניך למודי הוי' ורב שלום, או ורב שלומם<sup data-n=\"3715\">33</sup>, ומפני מה כתי' פעם שנית בניך אלא שבא להורות שא\"ת בניך אלא בוניך, והנה בוניך נקראים הת\"ח<sup data-n=\"3716\">34</sup> כמשארז\"ל בשבת פ' אלו קשרים<sup data-n=\"3717\">35</sup> דקי\"ד ע\"א תנן הבנאין מצד אחד (פי' בגדים של ת\"ח שמקפידין על לבושיהן כשנמצא בו רבב מצד אחד חוצץ) מאי בנאין אלו ת\"ח שעוסקי' בבנינו של עולם, וצ\"ל מהו שייך ת\"ח שלומדי' תורה להיות נקראים עוסקים בבנינו ש\"ע, וגם צ\"ל מפני מה מוצאין ורב שלום מכלל למודי הוי' דאם לא היו קורין בוניך אלא כמ\"ש בניך הי' קאי מ\"ש לימודי הוי' גם על ורב שלום, אבל כשאומרים א\"ת בניך אלא בוניך מוציאי'<sup data-n=\"3718\">36</sup> בחי' ורב שלום מבחי' לימודי הוי', וגם צ\"ל מפני מה ע\"י שלומדים תורה הם מרבין שלום בעולם. אך הענין יובן בהקדם ענין מה שארז\"ל בעשרה מאמרות נבה\"ע והלא במאמר א' יכול להבראות אלא להפרע מן הרשעים שמאבדין את העולם שנברא בעשרה מאמרות<sup data-n=\"3719\">37</sup>, וצ\"ל מפני מה מגיע העונש כ\"כ לרשעים על מה שהם מאבדין את העולם שנברא בע\"מ הלא במאמר א' יכול להבראות<sup data-n=\"3720\">38</sup>, ובמדרש שמואל<sup data-n=\"3721\">39</sup> איתא משל ע\"ז מא' שקנה כלי ביו\"ד זהובים שהכלי זו קונים אותה בעד זהב אחד, ואח\"כ גנבו את הכלי ונמצא הגנב האם יתכן לומר שישלם הגנב בעד הכלי יו\"ד זהובים מפני שזה הוציא עליה יו\"ד זהובים מאחר שיכולים לקנות כלי הלזה בזהב אחד, וכמו\"כ מפני מה העונש של הרשעים להפרע מהם על שמאבדין את העולם שנברא בע\"מ מאחר שבמאמר א' יכול להבראות. והענין הוא דהנה מאמר א' הוא מאמר דבראשית<sup data-n=\"3722\">40</sup> כמשארז\"ל בר\"ה דל\"ב ע\"א ובמגילה ך\"א ע\"ב בע\"מ נברא העולם והלא ט' ויאמר הן<sup data-n=\"3723\">41</sup> אלא בראשית נמי מאמר הוא, ופי' וענין מאמר דבראשית כי הנה יש כלל ופרט, ומאמר דבראשית הוא בחי' כלל של כל הע\"מ, שזהו מ\"ש את השמים ואת הארץ<sup data-n=\"3724\">42</sup> שידוע שכל אתין",[["3715","33","<b>או ורב שלומם</b>: וכ\"ה בסה\"מ תרכ\"ז כאן ע' רפב. אמנם בשל\"ה ובהדרושים שבהערה שלפנ\"ז ליתא."],["3716","34","<b>בוניך נקראים הת\"ח</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תכו. וש\"נ. סה\"מ תרל\"ח ע' קנז. וש\"נ."],["3717","35","<b>אלו קשרים</b>: במשניות: אלו קשרים. וכ\"ה בשו\"ע אדה\"ז הל' שבת מהדורא בתרא שייך לסי' שא (קה\"ת תשכ\"ד ע' תיב). סה\"מ תרכ\"ז כאן. בגמרא: ואלו קשרים. וכ\"ה באוה\"ת שבהערה 32."],["3718","36","<b>מוצאין . . מוציאי'</b>: במהדורא קמא כאן: מוצאין . . מוצאי'. בסה\"מ תרכ\"ט כאן: מוציאי' . . מוציאי'."],["3719","37","<b>בעשרה מאמרות נבה\"ע . . מאמרות</b>: אבות רפ\"ה [בדילוג]. ראה גם בהבא לקמן סה\"מ תרמ\"ד מהדורת תשס\"ב ע' שטז ואילך."],["3720","38","<b>מגיע העונש . . במאמר א' יכול להבראות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410069\" data-slug=\"likkutei-sichot\" data-id=\"1301410069\">לקו\"ש בראשית כרך ל ע' 4</a> ואילך."],["3721","39","<b>ובמדרש שמואל</b>: ראה אבות שם ד\"ה והחסיד.\nמובא גם בכ\"מ ומהם: לקמן מאמר ד\"ה בעשרה מאמרות נבה\"ע בתחילתו (ובשתי ההנחות שם). (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 42. סה\"מ תרכ\"ז כאן ע' רפב. תרל\"ח ע' רעח — נדפס גם באוה\"ת בראשית כרך ו ע' 2076. סה\"מ תרמ\"ד הנ\"ל ע' שטז. תרמ\"ו ע' תג. תרנ\"ב ע' לו."],["3722","40","<b>מאמר א' הוא מאמר דבראשית</b>: בראשית א, א. ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 19."],["3723","41","<b>ט' ויאמר הן</b>: נמנו בפרטיות — ב\"ר רפי\"ז. פדר\"א ספ\"ג וברד\"ל שם אות עג. לקח טוב בראשית א, א ד\"ה את השמים [וראה שם ואתחנן ה, ו]. ראה פרדס שער טעם האצילות ש\"ב, פ\"ג. פ\"ד. פלח הרמון לפרדס שם פ\"ב. פ\"ד. וראה גם ילקוט שמעוני מהדורת ירושלים תשל\"ג בתחילתו הערה 1."],["3724","42","<b>את השמים ואת הארץ</b>: בראשית א, א."]]],[2001910373,"שבתורה הם ריבוים<sup data-n=\"3725\">43</sup>, ולכן כשכתי' את השמים בא לרבות כל צבא השמים<sup data-n=\"3726\">44</sup> וכתי' את הארץ בא לרבות כל בחי' ומדרגות הנמצאים בארץ<sup data-n=\"3727\">45</sup> כו' (ע' מד\"ר פ\"א בפ' בראשית<sup data-n=\"3728\">46</sup>, ר\"י שאל את ר\"ע, עד ואת הארץ לרבות אילנות ודשאים וג\"ע, ואח\"כ נפרטו פרטי ההתהוות שבשמים ובארץ בט' מאמרות הפרטים כו').\nג) <b>ולהבין</b> היטב ענין כלל ופרט, הנה על בראשית ת\"י בחוכמתא<sup data-n=\"3729\">47</sup> שראשית הוא בחי' חכ' כמ\"ש ראשית חכמה<sup data-n=\"3730\">48</sup>, והנה אנו רואים למשל שכאשר הא' מחשב השכל במוחו הנה בשעתא חדא ורגעא חדא יחשוב כל השכל בהברקה אחת, אבל כאשר בא לפרשו לזולתו יצטרך לדבר בזה הרבה<sup data-n=\"3731\">49</sup>, וכ\"ש כשיצטרך ללמוד שכל זה עם הקטן יצטרך לבוא שכל זה בדבורים וצירופים הרבה מאד כו', כמו\"כ יובן למעלה ענין הכלל ופרט שכלל כולל הרבה מהפרט, ולכן במאמר בראשית כולל כל הפרטים שנתבאר בט' מאמרות והט' מאמרות הם פרטיות שהוא בחי' צרופי אותיות שבדבור כנודע שיש ך\"ב א\"ב שהם רל\"א זוגות ויש רל\"א שערים המתגלגלים פנים ואחור כו' (ע' בפרד\"ס<sup data-n=\"3733\">51</sup> שער למ\"ד הוא שער הצירוף פ\"ה<sup data-n=\"3732\">50</sup>, ובסש\"ב בשער היחוד והאמונה<sup data-n=\"3734\">52</sup>). והנה מבחי' המחשבה שבאדם שהיא ג\"כ בחי' הכלל לא יתהוה כלום, שאפי' שכשיחשוב כל היום לא יתהוה כלום, כ\"א דבר מלך שלטון<sup data-n=\"3735\">53</sup> שכאשר המלך מצוה לעבדיו שיעשה הדבר ההוא הם עושים, וא\"כ עפ\"י דבורו יכול להתהוות איזה דבר אבל לא ממחשבתו, אבל למעלה הנה כתי' כי לא מחשבותי מחשבותיכם<sup data-n=\"3736\">54</sup>, שלמעלה כאשר עלה במחשבתו שיהי' מציאות העולם נברא העולם, וכמ\"ש בכהאריז\"ל כשעלה ברצונו לברוא את העולם הנה ע\"י מחשבה זו נברא<sup data-n=\"3737\">55</sup> כו' (וע'",[["3725","43","<b>שכל אתין שבתורה הם ריבוים</b>: ראה ירושלמי ברכות פ\"ט, ה\"ה. פסחים כב, ב. אנציק' תלמודית בערכו ע' שג ואילך ובהנסמן שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151482\" data-slug=\"likkutei-sichot\" data-id=\"1300151482\">לקו\"ש בראשית כרך טו ע' 469</a>."],["3726","44","<b>את השמים . . צבא השמים</b>: ראה רש\"י בראשית א, יד. ב\"ר פ\"א, יד. תנחומא בראשית — באבער — ח. תוד\"ה ואת חגיגה יב, ב."],["3727","45","<b>את הארץ . . הנמצאים בארץ</b>: נסמן בהערה שלפנ\"ז."],["3728","46","<b>מד\"ר פ\"א בפ' בראשית</b>: נסמן לעיל בהערה 44."],["3729","47","<b>בראשית ת\"י בחוכמתא</b>: בראשית א, א. ראה תרגום ירושלמי שם. סה\"מ תר\"ם ח\"ב ע' תקלג. וש\"נ."],["3730","48","<b>ראשית חכמה</b>: תהלים קיא, י. ראה גם מאמרי אדה\"א בראשית ע' א. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550075\" data-slug=\"torat-chaim\" data-id=\"2300550075\">תו\"ח יתרו ח\"ב רסד, ב</a>. וש\"נ."],["3731","49","<b>מחשב השכל במוחו . . לדבר בזה הרבה</b>: ראה שה\"א צג, ב ובהערה 15."],["3733","51","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["3732","50","<b>רל\"א שערים . . ע' בפרד\"ס . . פ\"ה</b>: ראה גם ס\"י פ\"ב, מ\"ד-ה ובמפרשיו. פי' הראב\"ד שם [מב, ד]. עמה\"מ שער שעשועי המלך פ\"ה."],["3734","52","<b>בשער היחוד והאמונה</b>: פ\"א."],["3735","53","<b>דבר מלך שלטון</b>: קהלת ח, ד. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 56. סה\"מ תרל\"ט ח\"ב ע' תנד."],["3736","54","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת שה\"ש יז, ג</a> ואילך. (הועתק ב) סה\"מ תר\"ם ח\"א ע' קלט ואילך ובהנסמן שם."],["3737","55","<b>בכהאריז\"ל כשעלה ברצונו . . נברא</b>: וכ\"ה בסה\"מ תרמ\"ד מהדורת תשס\"ב ע' שיח. ובשם הע\"ח לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 58־ סה\"מ תרכ\"ח ע' קסח־ תרל\"א ח\"א ע' שלב־ ותרל\"ג ח\"א ע' כג.\nראה גם מערכת אלקות רפ\"ז. עבודת הקודש חלק היחוד פ\"ג. פרדס שער הצחצחות שי\"א, פ\"ג הובא בלקו\"ת שה\"ש שם [נדפס גם באוה\"ת שבועות ע' צה]. ר\"ה נה, א. סהמ\"צ להצ\"צ ע' נח. ע' קעח."]]]]});
